class _BizError(Exception):
    """业务错误：抛出后事务回滚并返回友好提示"""

    def __init__(self, msg: str):
        super().__init__(msg)
        self.msg = msg


class _ExactPointsCommandFilter(CustomFilter):
    """只匹配单独的 /积分，避免抢占 /子指令。"""

    def filter(self, event: AstrMessageEvent, cfg) -> bool:
        try:
            return event.get_message_str().strip() == "积分"
        except Exception:
            return False


