    # ============================================================
    #  今日运势（融合自 astrbot_plugin_jrys：签到时附带输出）
    # ============================================================
    def _fortune_enabled(self) -> bool:
        return bool(self.feature_flags.get("enable_fortune", True))

    def _load_jrys_data(self) -> dict:
        """加载运势数据表（jrys.json，随插件分发）"""
        if self._fortune_jrys_data is None:
            try:
                path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "jrys.json")
                with open(path, "r", encoding="utf-8") as f:
                    self._fortune_jrys_data = json.load(f)
            except Exception:
                self.logger.exception("加载运势数据 jrys.json 失败")
                self._fortune_jrys_data = {}
        return self._fortune_jrys_data

    def _fortune_rates(self) -> tuple[int, int, int]:
        """当天适用的运势爆率权重：节假日启用且命中时用节假日权重"""
        if self.config.get("holiday_rates_enabled", True):
            holidays = self.config.get(
                "holidays", ["01-01", "02-14", "05-01", "10-01", "12-25"]
            )
            if isinstance(holidays, str):
                holidays = [x.strip() for x in holidays.replace("，", ",").split(",") if x.strip()]
            today_md = datetime.now().strftime("%m-%d")
            if today_md in {str(x).strip() for x in (holidays or [])}:
                hr = self.config.get("holiday_rates", {}) or {}
                return (
                    int(hr.get("good", 85)),
                    int(hr.get("normal", 15)),
                    int(hr.get("bad", 0)),
                )
        nr = self.config.get("normal_rates", {}) or {}
        return (
            int(nr.get("good", 40)),
            int(nr.get("normal", 40)),
            int(nr.get("bad", 20)),
        )

    def _pick_fortune(self, user_id: str) -> dict | None:
        """按 painter 同款算法抽取运势：用户ID+日期做种子，当天结果固定"""
        data = self._load_jrys_data()
        keys = [k for k in data.keys() if not k.startswith("_")]
        if not keys:
            return None
        rng = random.Random()
        if self.config.get("fixed_daily_fortune", True):
            rng.seed(f"{user_id}-{datetime.now().strftime('%Y-%m-%d')}")
        good = [k for k in keys if int(k) > 70]
        normal = [k for k in keys if 56 <= int(k) <= 70]
        bad = [k for k in keys if int(k) < 56]
        r_good, r_normal, r_bad = self._fortune_rates()
        weights = []
        for k in keys:
            val = int(k)
            if val > 70:
                weights.append(r_good / max(len(good), 1))
            elif val >= 56:
                weights.append(r_normal / max(len(normal), 1))
            else:
                weights.append(r_bad / max(len(bad), 1))
        if sum(weights) <= 0:
            weights = [1] * len(keys)
        key_1 = rng.choices(keys, weights=weights, k=1)[0]
        bucket = data.get(key_1) or []
        if not bucket:
            return None
        fd = rng.choice(bucket)
        # 部分条目缺 luckValue 字段，桶名即为分数
        if isinstance(fd, dict) and "luckValue" not in fd:
            try:
                fd["luckValue"] = int(key_1)
            except (TypeError, ValueError):
                pass
        return fd

    def _fortune_text(self, user_id: str) -> str:
        """文字版今日运势（海报生成失败时的兜底输出）"""
        fd = self._pick_fortune(user_id)
        if not fd:
            return ""
        lines = [
            f"🔮 今日运势：{fd.get('fortuneSummary', '未知')} {fd.get('luckyStar', '')}（{fd.get('luckValue', '?')}分）",
            f"📜 签文：{fd.get('signText', '')}",
            "仅供娱乐 | 相信科学 | 请勿迷信",
        ]
        return "\n".join(lines)

    async def _generate_fortune_image(self, user_id: str) -> Optional[str]:
        """生成今日运势海报，返回临时图片路径；失败返回 None"""
        if not (_FORTUNE_DEPS_OK and self._fortune_resources and self._fortune_painter):
            return None
        avatar_path, background_result = await asyncio.gather(
            self._fortune_resources.get_avatar_img(user_id),
            self._fortune_resources.get_background_image(),
            return_exceptions=True,
        )
        if isinstance(background_result, Exception) or not background_result:
            self.logger.warning(f"获取运势背景图失败：{background_result}")
            return None
        background_path, should_cleanup = background_result
        cleanup = bool(should_cleanup)
        try:
            if isinstance(avatar_path, Exception) or not avatar_path:
                self.logger.warning(f"获取用户头像失败：{avatar_path}")
                return None
            return await asyncio.to_thread(
                self._fortune_painter.generate_image_sync,
                user_id, avatar_path, background_path, self._load_jrys_data(),
            )
        finally:
            if cleanup and background_path and os.path.exists(background_path):
                try:
                    os.remove(background_path)
                except OSError:
                    pass

    async def _send_fortune_result(self, event: AstrMessageEvent):
        """签到成功后输出今日运势：优先海报图片，失败回退文字运势"""
        if not self._fortune_enabled():
            return
        user_id = event.get_sender_id()
        temp_path = None
        try:
            temp_path = await self._generate_fortune_image(user_id)
        except Exception:
            self.logger.exception("生成今日运势海报异常")
        if temp_path and os.path.exists(temp_path):
            try:
                yield event.image_result(temp_path)
            finally:
                try:
                    os.remove(temp_path)
                except OSError:
                    pass
            return
        text = self._fortune_text(user_id)
        if text:
            yield event.plain_result(text)

    async def _sign_in_text(self, event: AstrMessageEvent) -> tuple[bool, str]:
        """执行积分签到并返回结果，供座驾签到监听器合并输出。"""
        ok_gate, msg_gate = await self._check_group_gate(event, "签到")
        if not ok_gate:
            return False, msg_gate
        user_id = event.get_sender_id()
        today = date.today().isoformat()
        yesterday = (date.today() - timedelta(days=1)).isoformat()

        async def fn(session):
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            # 先查后建：is_new 用于判断首次签到（users 表此前无该用户记录）
            row = (
                await session.execute(
                    text("SELECT sign_in_date, sign_in_streak FROM users WHERE user_id=:u"),
                    {"u": user_id},
                )
            ).first()
            is_new = row is None
            # 首次签到判定：users 无记录，或存在记录但从未签到过（sign_in_date 为空）
            # 避免玩家先玩过其他玩法导致"永远不算新人"而领不到送竿
            first_sign_in = row is None or row[0] is None
            await self._ensure_user(session, user_id)
            if row and row[0] == today:
                raise _BizError("今天已经签到过啦，明天再来喵~")
            streak = 1
            if row and row[0] == yesterday:
                streak = int(row[1]) + 1
            reward = random.randint(self.SIGN_IN_MIN, self.SIGN_IN_MAX)
            bonus = self.SIGN_IN_WEEK_BONUS if streak % 7 == 0 else 0
            await self._add_points(session, user_id, reward + bonus, "每日签到")
            await session.execute(
                text("UPDATE users SET sign_in_date=:d, sign_in_streak=:s WHERE user_id=:u"),
                {"d": today, "s": streak, "u": user_id},
            )
            msg = f"📝 签到成功！+{reward} 积分，已连续签到 {streak} 天"
            if bonus:
                msg += f"\n🎉 连续签到 {streak} 天额外 +{bonus} 积分！"
            if first_sign_in:
                # 首次签到：免费赠送 1 号鱼竿 + 5 个鱼饵（已拥有鱼竿则不重复赠送）
                has_rod = (await session.execute(text(
                    "SELECT 1 FROM fishing_rods WHERE user_id=:u LIMIT 1"
                ), {"u": user_id})).first()
                if not has_rod:
                    await session.execute(text(
                        "INSERT INTO fishing_rods(user_id, slot, status, created_at) "
                        "VALUES(:u, :s, 'idle', :t)"
                    ), {"u": user_id, "s": 1, "t": time.time()})
                    # 送 5 个鱼饵
                    await session.execute(text(
                        "INSERT INTO fishing_baits(user_id, count) VALUES(:u, 5) "
                        "ON CONFLICT(user_id) DO UPDATE SET count=count+5"
                    ), {"u": user_id})
                    msg = (f"🎣 签到成功！获得 {reward} 积分！\n"
                           f"🎁 首次签到奖励：免费领取一根鱼竿 + 5 个鱼饵！\n"
                           f"发送 /挂机钓鱼 即可开始挂机赚钱")
            msg += f"\n当前积分：{await self._balance(session, user_id)} 喵~"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        return ok, msg

    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    @filter.regex(re.compile(r"(?i)^(?:签到|jrzj|今日座驾)\s*$"))
    async def daily_car_checkin(self, event: AstrMessageEvent):
        """群内发送 签到、jrzj 或 今日座驾，合并输出签到和座驾。"""
        ok, sign_text = await self._sign_in_text(event)
        car_text = await self._daily_car_text(event)
        yield event.plain_result(f"{sign_text}\n\n{car_text}")
        if ok:
            async for result in self._send_fortune_result(event):
                yield result
        event.stop_event()

    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    @filter.regex(DAILY_CAR_ADD_PATTERN)
    @filter.permission_type(PermissionType.ADMIN)
    async def add_daily_car(self, event: AstrMessageEvent):
        """群管理员发送 添加车辆 车型，将车型写入每日座驾车池。"""
        match = DAILY_CAR_ADD_PATTERN.match(event.get_message_str().strip())
        car_name = self._normalize_car_text(match.group("car")) if match else ""
        if not car_name:
            yield event.plain_result("格式：添加车辆 车辆名称")
            event.stop_event()
            return
        if car_name in self.daily_car_pool:
            yield event.plain_result("这辆车已经在车池里了")
            event.stop_event()
            return
        try:
            await self._save_daily_car_config([*self.daily_car_pool, car_name])
            yield event.plain_result(f"已添加车辆：{car_name}")
        except _BizError as e:
            yield event.plain_result(e.msg)
        event.stop_event()

    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    @filter.regex(re.compile(r"^查看车池$"))
    async def view_daily_car_pool(self, event: AstrMessageEvent):
        """群成员发送 查看车池，列出每日座驾车辆池。"""
        message = "车池为空" if not self.daily_car_pool else "当前车池：\n" + "\n".join(
            self._format_car_entry(car) for car in self.daily_car_pool
        )
        yield event.plain_result(message)
        event.stop_event()

    @filter.event_message_type(EventMessageType.GROUP_MESSAGE)
    @filter.regex(DAILY_CAR_DELETE_PATTERN)
    @filter.permission_type(PermissionType.ADMIN)
    async def delete_daily_car(self, event: AstrMessageEvent):
        """群管理员发送 删除车辆 车型，从每日座驾车池移除。"""
        match = DAILY_CAR_DELETE_PATTERN.match(event.get_message_str().strip())
        car_name = self._normalize_car_text(match.group("car")) if match else ""
        if not car_name:
            yield event.plain_result("格式：删除车辆 车辆名称")
            event.stop_event()
            return
        if car_name not in self.daily_car_pool:
            yield event.plain_result("车池里没有这辆车")
            event.stop_event()
            return
        try:
            await self._save_daily_car_config([car for car in self.daily_car_pool if car != car_name])
            yield event.plain_result(f"已删除车辆：{car_name}")
        except _BizError as e:
            yield event.plain_result(e.msg)
        event.stop_event()

    # ============================================================
    #  WebUI 面板（API + 页面）
    # ============================================================
    def _register_web_apis(self):
        ctx = self.context
        if not hasattr(ctx, "register_web_api"):
            self.logger.warning("当前 AstrBot 版本不支持 register_web_api，WebUI 面板不可用")
            return
        ctx.register_web_api("/point_games/dashboard", self._web_dashboard, ["GET"], "积分游戏面板（独立窗口）")
        ctx.register_web_api("/point_games/api/whoami", self._web_whoami, ["GET"], "当前面板用户")
        ctx.register_web_api("/point_games/api/stats", self._web_stats, ["GET"], "积分游戏总览")
        ctx.register_web_api("/point_games/api/leaderboard", self._web_leaderboard, ["GET"], "积分排行榜")
        ctx.register_web_api("/point_games/api/users", self._web_users, ["GET"], "用户列表")
        ctx.register_web_api("/point_games/api/user_detail", self._web_user_detail, ["GET"], "玩家积分明细")
        ctx.register_web_api("/point_games/api/boss", self._web_boss, ["GET"], "BOSS 状态")
        ctx.register_web_api("/point_games/api/lottery", self._web_lottery, ["GET"], "彩票信息")
        ctx.register_web_api("/point_games/api/transactions", self._web_transactions, ["GET"], "积分流水明细")
        ctx.register_web_api("/point_games/api/groups", self._web_groups, ["GET"], "群设置列表")
        ctx.register_web_api("/point_games/api/groups/toggle", self._web_group_toggle, ["POST"], "开关群玩法")
        ctx.register_web_api("/point_games/api/config/mode", self._web_mode_set, ["POST"], "切换全局模式")
        ctx.register_web_api("/point_games/api/admin/grant", self._web_grant, ["POST"], "WebUI 加/扣积分")

    def _web_admin_ok(self) -> bool:
        """WebUI 管理操作已开放给所有已登录面板用户（AstrBot 面板登录即视为可信）"""
        return True

    async def _web_dashboard(self):
        from fastapi.responses import HTMLResponse
        import os
        html_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "dashboard.html")
        try:
            with open(html_path, "r", encoding="utf-8") as f:
                html = f.read()
        except Exception:
            html = "<h1>dashboard.html 缺失</h1><p>请确认插件目录下存在 dashboard.html</p>"
        return HTMLResponse(content=html, media_type="text/html; charset=utf-8")

    async def _web_whoami(self):
        from astrbot.api.web import json_response, request as web_request
        try:
            req = web_request
            username = getattr(req, "username", "") or ""
        except Exception:
            username = ""
        return json_response({"username": username, "is_admin": True})

    async def _web_stats(self):
        from astrbot.api.web import json_response
        today = date.today().isoformat()

        async def fn(session):
            user_cnt = (await session.execute(text("SELECT COUNT(*) FROM users"))).first()
            txn_today = (
                await session.execute(
                    text("SELECT COALESCE(SUM(amount),0) FROM point_transactions WHERE create_time >= :t"),
                    {"t": datetime.combine(date.today(), datetime.min.time()).timestamp()},
                )
            ).first()
            spin_cnt = (
                await session.execute(
                    text("SELECT COUNT(*) FROM point_transactions WHERE operation='幸运转盘'")
                )
            ).first()
            boss_row = (await session.execute(text("SELECT current_hp FROM boss WHERE id=1"))).first()
            bought = (
                await session.execute(
                    text("SELECT COALESCE(SUM(cost),0), COUNT(DISTINCT user_id) FROM lottery WHERE period=:p"), {"p": today}
                )
            ).first()
            carry = 0
            prev = (date.today() - timedelta(days=1)).isoformat()
            c_row = (await session.execute(text("SELECT pool FROM lottery_pool WHERE period=:p"), {"p": prev})).first()
            if c_row:
                carry = int(c_row[0])
            uc_cnt = (
                await session.execute(text("SELECT COUNT(*) FROM undercover_games WHERE status IN ('waiting','speech','voting')"))
            ).first()
            return True, "ok", {
                "users": int(user_cnt[0]),
                "today_transactions": int(txn_today[0]),
                "spin_total": int(spin_cnt[0]),
                "boss_hp": int(boss_row[0]) if boss_row else 0,
                "lottery_pool": int(bought[0]) + self.LOTTERY_BASE_POOL + carry,
                "lottery_participants": int(bought[1]),
                "active_undercover": int(uc_cnt[0]),
            }

        ok, _, data = await self._tx(fn)
        return json_response(data if data else {})

    async def _web_leaderboard(self):
        from astrbot.api.web import json_response

        async def fn(session):
            rows = (
                await session.execute(
                    text("SELECT user_id, user_name, balance, total_earned, total_spent, sign_in_streak FROM users ORDER BY balance DESC LIMIT 50")
                )
            ).all()
            return True, "ok", [
                {"user_id": r[0], "user_name": r[1] or "未知玩家", "balance": int(r[2]), "total_earned": int(r[3]),
                 "total_spent": int(r[4]), "sign_in_streak": int(r[5])}
                for r in rows
            ]

        ok, _, data = await self._tx(fn)
        return json_response(data if data else [])

    async def _web_users(self):
        from astrbot.api.web import json_response, request as web_request
        try:
            req = web_request
            params = getattr(req, "query", None) or getattr(req, "query_params", {})
        except Exception:
            params = {}
        page = max(1, int(params.get("page", 1)))
        page_size = min(50, max(5, int(params.get("page_size", 20))))
        keyword = str(params.get("search", "") or "").strip()

        async def fn(session):
            if keyword:
                total = (
                    await session.execute(text("SELECT COUNT(*) FROM users WHERE user_id LIKE :k OR user_name LIKE :k"), {"k": f"%{keyword}%"})
                ).first()
                rows = (
                    await session.execute(
                        text("SELECT user_id, user_name, balance, total_earned, total_spent, sign_in_date, sign_in_streak FROM users WHERE user_id LIKE :k OR user_name LIKE :k ORDER BY balance DESC LIMIT :n OFFSET :o"),
                        {"k": f"%{keyword}%", "n": page_size, "o": (page - 1) * page_size},
                    )
                ).all()
            else:
                total = (await session.execute(text("SELECT COUNT(*) FROM users"))).first()
                rows = (
                    await session.execute(
                        text("SELECT user_id, user_name, balance, total_earned, total_spent, sign_in_date, sign_in_streak FROM users ORDER BY balance DESC LIMIT :n OFFSET :o"),
                        {"n": page_size, "o": (page - 1) * page_size},
                    )
                ).all()
            return True, "ok", {
                "total": int(total[0]),
                "page": page,
                "page_size": page_size,
                "users": [
                    {"user_id": r[0], "user_name": r[1] or "未知玩家", "balance": int(r[2]), "total_earned": int(r[3]),
                     "total_spent": int(r[4]), "sign_in_date": r[5], "sign_in_streak": int(r[6])}
                    for r in rows
                ],
            }

        ok, _, data = await self._tx(fn)
        return json_response(data if data else {})

    async def _web_user_detail(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        try:
            req = web_request
            params = getattr(req, "query", None) or getattr(req, "query_params", {})
            user_id = str(params.get("user_id", "")).strip()
        except Exception:
            user_id = ""
        if not user_id:
            return error_response("缺少 user_id")

        async def fn(session):
            user = (await session.execute(text(
                "SELECT user_id, user_name, balance, total_earned, total_spent, sign_in_streak "
                "FROM users WHERE user_id=:u"
            ), {"u": user_id})).first()
            if not user:
                return False, "玩家不存在", None
            rows = (await session.execute(text(
                "SELECT amount, earned, spent, balance_after, operation, create_time "
                "FROM point_transactions WHERE user_id=:u ORDER BY id DESC LIMIT 100"
            ), {"u": user_id})).all()
            return True, "ok", {
                "user_id": user[0], "user_name": user[1] or "未知玩家", "balance": int(user[2]),
                "total_earned": int(user[3]), "total_spent": int(user[4]),
                "sign_in_streak": int(user[5]),
                "transactions": [
                    {"amount": int(r[0]), "earned": int(r[1] or 0), "spent": int(r[2] or 0),
                     "balance_after": int(r[3] or 0), "operation": r[4],
                     "detail": f"收入 +{int(r[1] or 0)}，支出 -{int(r[2] or 0)}，净变化 {int(r[0])}，余额 {int(r[3] or 0)}",
                     "time": datetime.fromtimestamp(float(r[5])).strftime("%Y-%m-%d %H:%M:%S") if r[5] else ""}
                    for r in rows
                ],
            }

        ok, msg, data = await self._tx(fn)
        if not ok:
            return error_response(msg, 404)
        return json_response(data)

    async def _web_boss(self):
        from astrbot.api.web import json_response

        async def fn(session):
            await self._ensure_boss_reset(session)
            row = (await session.execute(text("SELECT current_hp, pool, reset_date FROM boss WHERE id=1"))).first()
            agg = (await session.execute(text("SELECT COALESCE(SUM(damage),0), COUNT(DISTINCT user_id) FROM boss_damage"))).first()
            top = (
                await session.execute(
                    text("SELECT b.user_id, u.user_name, SUM(b.damage) AS dmg FROM boss_damage b LEFT JOIN users u ON u.user_id=b.user_id GROUP BY b.user_id, u.user_name ORDER BY dmg DESC LIMIT 10")
                )
            ).all()
            return True, "ok", {
                "hp": int(row[0]) if row else 0,
                "max_hp": self.BOSS_MAX_HP,
                "pool": int(row[1]) if row else 0,
                "reset_date": row[2] if row else None,
                "today_damage": int(agg[0]),
                "participants": int(agg[1]),
                "top": [{"user_id": r[0], "user_name": r[1] or "未知玩家", "damage": int(r[2])} for r in top],
            }

        ok, _, data = await self._tx(fn)
        return json_response(data if data else {})

    async def _web_lottery(self):
        from astrbot.api.web import json_response
        today = date.today().isoformat()

        async def fn(session):
            bought = (
                await session.execute(
                    text("SELECT COALESCE(SUM(cost),0), COUNT(DISTINCT user_id), COUNT(*) FROM lottery WHERE period=:p"),
                    {"p": today},
                )
            ).first()
            carry = 0
            prev = (date.today() - timedelta(days=1)).isoformat()
            c_row = (await session.execute(text("SELECT pool FROM lottery_pool WHERE period=:p"), {"p": prev})).first()
            if c_row:
                carry = int(c_row[0])
            last_rows = (
                await session.execute(
                    text("SELECT user_id, numbers, cost, period FROM lottery ORDER BY id DESC LIMIT 10")
                )
            ).all()
            return True, "ok", {
                "pool": int(bought[0]) + self.LOTTERY_BASE_POOL + carry,
                "bought": int(bought[0]),
                "participants": int(bought[1]),
                "tickets": int(bought[2]),
                "limit_per_day": self.LOTTERY_LIMIT_PER_DAY,
                "base_pool": self.LOTTERY_BASE_POOL,
                "carry": carry,
                "recent": [
                    {"user_id": r[0], "numbers": json.loads(r[1]), "cost": int(r[2]), "period": r[3]}
                    for r in last_rows
                ],
            }

        ok, _, data = await self._tx(fn)
        return json_response(data if data else {})

    async def _web_transactions(self):
        from astrbot.api.web import json_response
        try:
            from astrbot.api.web import request as web_request
            req = web_request
            params = req.query if hasattr(req, "query") else {}
        except Exception:
            params = {}
        limit = min(100, max(5, int(params.get("limit", 20))))

        async def fn(session):
            rows = (
                await session.execute(
                    text(
                        "SELECT t.user_id, u.user_name, t.amount, t.earned, t.spent, "
                        "t.balance_after, t.operation, t.create_time "
                        "FROM point_transactions t LEFT JOIN users u ON u.user_id=t.user_id "
                        "ORDER BY t.id DESC LIMIT :n"
                    ),
                    {"n": limit},
                )
            ).all()
            return True, "ok", [
                {"user_id": r[0], "user_name": r[1] or "未知玩家", "amount": int(r[2]),
                 "earned": int(r[3] or 0), "spent": int(r[4] or 0), "balance_after": int(r[5] or 0),
                 "operation": r[6],
                 "detail": f"收入 +{int(r[3] or 0)}，支出 -{int(r[4] or 0)}，净变化 {int(r[2])}，余额 {int(r[5] or 0)}",
                 "time": datetime.fromtimestamp(float(r[7])).strftime("%Y-%m-%d %H:%M:%S") if r[7] else ""}
                for r in rows
            ]

        ok, _, data = await self._tx(fn)
        return json_response(data if data else [])

    async def _web_groups(self):
        from astrbot.api.web import json_response

        async def fn(session):
            mode = await self._get_config_value(session, "group_mode", self.DEFAULT_GROUP_MODE)
            rows = (
                await session.execute(text("SELECT group_id, enabled, updated_at FROM group_settings ORDER BY updated_at DESC LIMIT 100"))
            ).all()
            return True, "ok", {
                "mode": mode,
                "groups": [
                    {"group_id": r[0], "enabled": int(r[1]),
                     "updated_at": datetime.fromtimestamp(float(r[2])).strftime("%Y-%m-%d %H:%M:%S") if r[2] else ""}
                    for r in rows
                ],
            }

        ok, _, data = await self._tx(fn)
        return json_response(data if data else {})

    async def _web_group_toggle(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        if not self._web_admin_ok():
            return error_response("无权限：当前面板用户不在管理名单中", 403)
        try:
            req = web_request
            body = await req.json()
            group_id = str(body.get("group_id", "")).strip()
            enabled = 1 if body.get("enabled") else 0
            platform_id = str(body.get("platform_id", "")).strip()
        except Exception as e:
            return error_response(f"参数错误：{e}")
        if not group_id:
            return error_response("缺少 group_id")

        async def fn(session):
            await session.execute(
                text(
                    "INSERT INTO group_settings(group_id, enabled, updated_at, platform_id) VALUES(:g, :e, :t, :p) "
                    "ON CONFLICT(group_id) DO UPDATE SET enabled=:e, updated_at=:t, platform_id=:p"
                ),
                {"g": group_id, "e": enabled, "t": time.time(), "p": platform_id},
            )
            return True, "ok", None

        ok, msg, _ = await self._tx(fn)
        return json_response({"ok": ok, "message": msg})

    async def _web_mode_set(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        if not self._web_admin_ok():
            return error_response("无权限：当前面板用户不在管理名单中", 403)
        try:
            req = web_request
            body = await req.json()
            mode = str(body.get("mode", "")).strip()
        except Exception as e:
            return error_response(f"参数错误：{e}")
        if mode not in ("whitelist", "blacklist"):
            return error_response("mode 只能是 whitelist 或 blacklist")

        async def fn(session):
            await self._set_config_value(session, "group_mode", mode)
            return True, "ok", None

        ok, msg, _ = await self._tx(fn)
        return json_response({"ok": ok, "message": msg})

    async def _web_grant(self):
        from astrbot.api.web import json_response, error_response, request as web_request
        if not self._web_admin_ok():
            return error_response("无权限：当前面板用户不在管理名单中", 403)
        try:
            req = web_request
            body = await req.json()
            user_id = str(body.get("user_id", "")).strip()
            amount = int(body.get("amount", 0))
        except Exception as e:
            return error_response(f"参数错误：{e}")
        if not user_id:
            return error_response("缺少 user_id")
        if amount == 0:
            return error_response("amount 不能为 0")

        async def fn(session):
            await self._ensure_user(session, user_id)
            await self._add_points(session, user_id, amount, "管理员加分" if amount > 0 else "管理员扣分")
            new_bal = await self._balance(session, user_id)
            return True, f"ok", {"user_id": user_id, "balance": new_bal}

        ok, msg, data = await self._tx(fn)
        if not ok:
            return error_response(msg)
        return json_response(data)

    # ============================================================
    #  钓鱼系统
    # ============================================================
    def _fishing_roll_event(self) -> str:
        """按 FISHING_EVENTS 概率表随机判定一次挂机事件"""
        roll = random.uniform(0, 100)
        cumulative = 0.0
        for name, prob in FISHING_EVENTS:
            cumulative += prob
            if roll <= cumulative:
                return name
        return "空钩"

    def _fishing_pick_fish(self):
        """按概率加权随机抽一条鱼，返回 (鱼名, 售价, 稀有度, 单条概率%)。"""
        roll = random.uniform(0, 100)
        cumulative = 0.0
        for name, (price, rarity, prob) in FISH_POOL.items():
            cumulative += prob
            if roll <= cumulative:
                return name, price, rarity, prob
        return None  # 杂物：水面漂过一片水草，一无所得

    def _fishing_apply_pond_upgrade(self, picked):
        """在每条渔获判定时应用鱼塘加成，返回 (渔获, 是否由鱼塘升级)。

        放在 _fishing_check 的逐条渔获路径调用，普通上钩和鱼汛普通保底都会生效，
        同时让播报能明确展示「鱼塘加成升级」。
        """
        if picked is None:
            return None, False
        name, price, rarity, prob = picked
        bonus = int(getattr(self, "_pond_rare_bonus", 0) or 0)
        if rarity == "普通" and bonus > 0 and random.random() < (bonus / 100.0):
            return self._fishing_pick_fish_tier("稀有"), True
        return picked, False

    def _fishing_pick_fish_tier(self, tier: str):
        """从指定稀有度档位随机抽一条鱼（保底必出，不含杂物）"""
        prob_total, fishes = FISH_TABLE.get(tier, FISH_TABLE["普通"])
        name, price = random.choice(fishes)
        return name, price, tier, prob_total / len(fishes)

    async def _fishing_ensure_stats(self, session, user_id: str) -> None:
        """确保钓鱼统计行存在，并惰性重置过期计数（必须在事务内调用）"""
        today = date.today().isoformat()
        row = (await session.execute(
            text("SELECT today_date FROM fishing_stats WHERE user_id=:u"), {"u": user_id}
        )).first()
        if not row:
            await session.execute(
                text("INSERT INTO fishing_stats(user_id, today_date, pond_level) VALUES(:u, :d, 1)"),
                {"u": user_id, "d": today},
            )
        elif row[0] != today:
            await session.execute(
                text("UPDATE fishing_stats SET today_count=0, today_date=:d WHERE user_id=:u"),
                {"u": user_id, "d": today},
            )

    async def _fishing_bait_count(self, session, user_id: str) -> int:
        """查询当前鱼饵数量（必须在事务内调用）"""
        row = (await session.execute(
            text("SELECT count FROM fishing_baits WHERE user_id=:u"), {"u": user_id}
        )).first()
        return int(row[0] or 0) if row else 0

    async def _get_broadcast_groups(self) -> list[tuple[str, str]]:
        """获取已开启玩法的群列表（group_settings 优先，platform_manager 全平台兜底）"""
        try:
            async with self._session() as session:
                rows = (await session.execute(text(
                    "SELECT group_id, platform_id FROM group_settings WHERE enabled=1"
                ))).all()
            groups = [(str(p or ""), str(g)) for g, p in rows]
            if not groups:
                self.logger.warning("没有已开启玩法的群（group_settings 为空），无法兜底播报")
            return groups
        except Exception:
            self.logger.exception("获取播报群列表失败")
            return []

    async def _get_platform_ids(self) -> list[str]:
        """获取当前所有平台实例 ID（AstrBot 兼容写法）"""
        ids: list[str] = []
        try:
            manager = getattr(self.context, "platform_manager", None)
            if manager and hasattr(manager, "get_insts"):
                ids = [str(p.meta().id) for p in manager.get_insts() if p.meta().id]
            elif manager and hasattr(manager, "platform_insts"):
                ids = [str(p.meta().id) for p in manager.platform_insts if p.meta().id]
        except Exception:
            pass
        return ids

    async def _send_with_fallback(
        self, platform_id: str, group_id: str, chain: list, tag: str,
        cross_group_fallback: bool = True,
    ) -> bool:
        """多重路径发送播报。

        配置了 fishing_broadcast_groups 时只发配置的群（所有平台实例都试）；
        否则按「竿里存的平台ID → 当前所有平台实例」重试；
        cross_group_fallback=True 时最后还会尝试所有已开启玩法的群（跨群兜底）。

        聚合播报图必须传 cross_group_fallback=False：目标群发送失败时宁可丢弃，
        也不能把 A 群的播报漏发到 B 群（否则 B 群一周期收到两张播报图）。
        """
        targets: list[tuple[str, str]] = []
        if self.FISHING_BROADCAST_GROUPS:
            # 配置了播报群：定向发送到配置的群
            pids = await self._get_platform_ids() or [str(platform_id or "")]
            for group in self.FISHING_BROADCAST_GROUPS:
                for pid in pids:
                    targets.append((pid, group))
            for t_platform, t_group in targets:
                try:
                    await self._send_group_chain(t_platform, t_group, chain)
                except Exception:
                    self.logger.exception(
                        f"{tag}发送到播报群失败（{t_platform}:{t_group}）"
                    )
            return True
        if group_id:
            targets.append((str(platform_id), str(group_id)))
            for pid in await self._get_platform_ids():
                if pid and (pid, str(group_id)) not in targets:
                    targets.append((pid, str(group_id)))
        if cross_group_fallback:
            for fb_platform, fb_group in await self._get_broadcast_groups():
                if (fb_platform, fb_group) not in targets:
                    targets.append((fb_platform, fb_group))
        for t_platform, t_group in targets:
            try:
                await self._send_group_chain(t_platform, t_group, chain)
                if (t_platform, t_group) != (str(platform_id), str(group_id)):
                    self.logger.info(f"{tag}已通过兜底路径送达（{t_platform}:{t_group}）")
                return True
            except Exception:
                self.logger.exception(f"{tag}发送失败（{t_platform}:{t_group}）")
        self.logger.warning(f"{tag}所有发送路径均失败（群号：{group_id or '空'}）")
        return False

    # ============================================================
    #  指令入口：系统钱包
    # ============================================================
    @filter.command("系统")
    async def system_wallet_command(self, event: AstrMessageEvent):
        """/系统 —— 查看系统钱包；管理员可 存/取/流水"""
        gate_ok, gate_msg = await self._check_group_gate(event, "系统")
        if not gate_ok:
            yield event.plain_result(gate_msg)
            return
        sender = str(event.get_sender_id()).strip()
        parts = self._strip_command(event, "系统").split()
        subcmd = parts[0] if parts else ""

        # ---- 无参数：所有人可查余额概况 ----
        if not subcmd:
            async def fn(session):
                bal, t_in, t_out = await self._wallet_ensure(session)
                return True, "ok", (bal, t_in, t_out)
            ok, _, data = await self._tx(fn)
            if not ok or data is None:
                yield event.plain_result("数据库开小差了喵~ 稍后再试")
                return
            bal, t_in, t_out = data
            yield event.plain_result(
                "🏦 【系统钱包】\n"
                f"💰 当前余额：{bal} 积分\n"
                f"📈 累计流入：{t_in} 积分\n"
                f"📉 累计流出：{t_out} 积分"
            )
            return

        # ---- 以下子命令仅管理员可用 ----
        if sender not in self.ADMIN_QQ:
            yield event.plain_result("❌ 仅管理员可操作")
            return

        if subcmd in ("存", "取"):
            if len(parts) < 2:
                yield event.plain_result(f"❌ 格式：/系统 {subcmd} [积分]")
                return
            try:
                amount = int(parts[1])
            except ValueError:
                yield event.plain_result("❌ 积分必须是整数喵~")
                return
            if amount < 1:
                yield event.plain_result("❌ 积分必须大于 0")
                return

            if subcmd == "存":
                async def fn(session):
                    # 只扣普通余额（贷款余额不可充值资金池，防止套现）
                    await self._ensure_user(session, sender)
                    row = (await session.execute(text(
                        "SELECT balance FROM users WHERE user_id=:u"
                    ), {"u": sender})).first()
                    bal = int(row[0]) if row else 0
                    if bal < amount:
                        raise _BizError(
                            f"❌ 你的余额不足！当前余额：{bal} 积分"
                        )
                    await self._add_points(
                        session, sender, -amount, "admin_wallet_deposit",
                        earned=0, spent=amount, force_normal=True,
                    )
                    await self._wallet_inflow_s(
                        session, amount, "admin_deposit",
                        f"管理员 {sender} 存入"
                    )
                    new_bal = await self._wallet_ensure(session)
                    return True, "ok", new_bal[0]
                ok, msg, data = await self._tx(fn)
                yield event.plain_result(
                    f"✅ 已存入系统钱包 {amount} 积分！\n"
                    f"当前系统钱包余额：{data}"
                    if ok else msg
                )
                return

            # 取
            async def fn(session):
                if not await self._wallet_outflow_s(
                    session, amount, "admin_withdraw",
                    f"管理员 {sender} 取出"
                ):
                    raise _BizError(
                        "❌ 系统钱包余额不足！当前余额："
                        f"{await self._wallet_balance_q(session)}"
                    )
                await self._add_points(
                    session, sender, amount, "admin_wallet_withdraw",
                    earned=amount, spent=0,
                )
                new_bal = await self._wallet_ensure(session)
                return True, "ok", new_bal[0]
            ok, msg, data = await self._tx(fn)
            yield event.plain_result(
                f"✅ 已取出 {amount} 积分到你的余额！\n"
                f"当前系统钱包余额：{data}"
                if ok else msg
            )
            return

        if subcmd == "流水":
            try:
                page = int(parts[1]) if len(parts) > 1 else 1
            except ValueError:
                page = 1
            page = max(1, page)
            size = self.WALLET_LOG_PAGE_SIZE

            async def fn(session):
                total = int((await session.execute(text(
                    "SELECT COUNT(*) FROM system_wallet_log"
                ))).first()[0])
                rows = (await session.execute(text(
                    "SELECT type, amount, source, remark, create_time "
                    "FROM system_wallet_log ORDER BY id DESC LIMIT :n OFFSET :o"
                ), {"n": size, "o": (page - 1) * size})).all()
                return True, "ok", (total, rows)
            ok, _, data = await self._tx(fn)
            if not ok or data is None:
                yield event.plain_result("数据库开小差了喵~ 稍后再试")
                return
            total, rows = data
            if not rows:
                yield event.plain_result("📭 该页没有流水记录喵~")
                return
            total_pages = max(1, (total + size - 1) // size)
            lines = [f"📒 系统钱包流水（第 {page}/{total_pages} 页，共 {total} 条）"]
            for rtype, ramount, rsource, rremark, rtime in rows:
                arrow = "↑" if rtype == "inflow" else "↓"
                try:
                    time_txt = datetime.fromtimestamp(float(rtime), TZ).strftime("%m-%d %H:%M")
                except (TypeError, ValueError):
                    time_txt = str(rtime)[:16]
                lines.append(
                    f"{arrow} {'+' if rtype == 'inflow' else '-'}{ramount} "
                    f"[{rsource}] {rremark or ''} {time_txt}"
                )
            yield event.plain_result("\n".join(lines))
            return

        yield event.plain_result("❌ 可用子命令：存、取、流水（无参数=查看余额）")

    async def _wallet_balance_q(self, session) -> int:
        """事务内快捷读取钱包余额（不建行）。"""
        row = (await session.execute(text(
            "SELECT balance FROM system_wallet LIMIT 1"
        ))).first()
        return int(row[0]) if row else 0

    async def _fishing_check(self):
        """定时任务：每 30 分钟判定一次所有挂机中的鱼竿。

        每根竿消耗 1 个鱼饵后随机判定事件：
        上钩的鱼先进 fishing_pending，等玩家 /收鱼 进鱼篓；
        高价值鱼 / 至高传说直接全群广播（真实 At 组件）。

        休息时间：北京时间 0:00-7:00 不进行判定（鱼儿也要休息喵~）
        """
        # 0点到7点为休息时间，不判定
        bj_hour = datetime.now(self._beijing_tz).hour
        if 0 <= bj_hour < 7:
            return

        async def fn(session):
            rods = (await session.execute(text(
                "SELECT r.id, r.user_id, r.slot, r.platform_id, r.group_id, "
                "COALESCE(NULLIF(u.user_name, ''), r.user_id) "
                "FROM fishing_rods r LEFT JOIN users u ON u.user_id = r.user_id "
                "WHERE r.status='fishing'"
            ))).all()
            if not rods:
                return False, "没有挂机中的鱼竿", None
            fishing_count = len(rods)  # 鱼群效应：当前全服挂机竿数
            broadcasts: list[tuple[str, str, list]] = []   # (platform_id, group_id, 消息链)
            notices: list[tuple[str, str, str]] = []       # (platform_id, group_id, 事件播报文本)
            # 今日天气（全服统一，惰性生成，影响本判定所有鱼竿）
            weather_key, weather_cfg = await self._weather_today(session)
            for rod in rods:
                rid, uid, slot, platform_id, group_id, user_name = rod
                group_id = str(group_id or "")

                def notify(text_line: str):
                    """本群事件播报（不艾特，只说谁遇到了什么事）"""
                    if group_id:
                        notices.append((platform_id, group_id, f"🎣 {user_name} {text_line}"))
                await self._fishing_ensure_stats(session, uid)
                # 鱼塘等级（每判定读取一次，应用到本判定的鱼饵与稀有加成）
                pond_row = (await session.execute(text(
                    "SELECT pond_level FROM fishing_stats WHERE user_id=:u"
                ), {"u": uid})).first()
                pond_level = int(pond_row[0] or 1) if pond_row else 1
                pond_rare_bonus = self.POND_RARE_BONUS.get(pond_level, 0)
                # 商店加成：幸运符生效中+5稀有；高级竿生效中本判定多捕1条(见渔获)；双倍/VIP在卖鱼生效
                fish_shop = await self._get_shop_items(session, uid)
                if self._shop_active(fish_shop, "charm"):
                    pond_rare_bonus = pond_rare_bonus + 5  # 幸运护身符生效中
                self._pond_rare_bonus = pond_rare_bonus   # 供本次判定抽鱼使用
                self._active_shop = fish_shop              # 供本判定后续阶段读取
                # 判定前消耗 1 个鱼饵，没鱼饵自动收杆
                bait = await self._fishing_bait_count(session, uid)
                if bait <= 0:
                    await session.execute(
                        text("UPDATE fishing_rods SET status='idle' WHERE id=:i"), {"i": rid}
                    )
                    notify("的鱼饵用完了，自动收杆休息啦~")
                    continue
                await session.execute(
                    text("UPDATE fishing_baits SET count=count-1 WHERE user_id=:u"), {"u": uid}
                )
                # 鱼塘减耗效果：按减耗百分比有几率回补鱼饵（折扣卡生效中额外+20%省饵）
                pond_bait_pct = self.POND_BAIT_REDUCTION.get(pond_level, 0)
                if self._shop_active(self._active_shop or {}, "discount"):
                    pond_bait_pct = pond_bait_pct + 20  # 鱼饵折扣卡生效中
                if pond_bait_pct > 0 and random.random() < (min(pond_bait_pct, 95) / 100.0):
                    await session.execute(
                        text("UPDATE fishing_baits SET count=count+1 WHERE user_id=:u"),
                        {"u": uid},
                    )
                # 幸运日 buff：有效期内空钩视为上钩
                st = (await session.execute(
                    text("SELECT lucky_day_expire FROM fishing_stats WHERE user_id=:u"),
                    {"u": uid},
                )).first()
                lucky_active = bool(st and st[0] and float(st[0]) > time.time())
                event = self._fishing_roll_event()
                if event == "空钩" and lucky_active:
                    event = "正常上钩"
                # 本次判定统计（每次判定消耗 1 鱼饵）
                await session.execute(text(
                    "UPDATE fishing_stats SET total_baits_used=total_baits_used+1, "
                    "today_count=today_count+1 WHERE user_id=:u"
                ), {"u": uid})
                # 鱼群效应：挂机竿越多越有收获（概率=竿数×7%，+1积分）
                if random.randint(1, 100) <= min(100, fishing_count * 7):
                    await self._add_points(session, uid, 1, "鱼群效应")
                multi_map = {
                    "正常上钩": (1, None), "双鱼上钩": (2, None), "鱼群爆发": (3, None),
                    "黄金鱼群": (2, None), "鱼汛大潮": (3, "普通"), "河水涨潮": (2, "普通"),
                    "传说召唤阵": (1, "传说"),
                }
                # 暴风雨：上钩类事件 30% 概率化为空钩（钓鱼成功率-30%）
                if weather_cfg.get("fail_pct") and event in multi_map and \
                        random.random() < weather_cfg["fail_pct"] / 100.0:
                    event = "空钩"
                    notify("暴风雨太猛了，到手的鱼脱钩跑掉了…")
                if event in multi_map:
                    # 上钩：鱼先进入 pending，等 /收鱼（指定档位保底必出，普通档可能钓上杂物）
                    caught, force_tier = multi_map[event]
                    if self._shop_active(self._active_shop or {}, "advanced"):
                        caught = caught + 1  # 高级鱼竿生效中：额外多捕1条
                    fish_names: list[str] = []
                    junk = 0
                    for _ in range(caught):
                        raw_picked = self._fishing_pick_fish_tier(force_tier) if force_tier else self._fishing_pick_fish()
                        # 鱼塘转化明确在每条渔获的判定路径执行，方便播报和排查
                        picked, pond_upgraded = self._fishing_apply_pond_upgrade(raw_picked)
                        if picked is None:
                            junk += 1
                            continue  # 杂物
                        name, price, rarity, prob = picked
                        upgrade_tag = "·鱼塘加成↑" if pond_upgraded else ""
                        # 天气加成：雨天/寒冷/雾天把普通鱼升级为稀有/珍稀/传说
                        wtier = weather_cfg.get("tier")
                        if wtier and rarity == "普通" and \
                                random.random() < weather_cfg["pct"] / 100.0:
                            name, price, rarity, prob = self._fishing_pick_fish_tier(wtier)
                            upgrade_tag = f"{upgrade_tag}·天气加成↑" if upgrade_tag else "·天气加成↑"
                        # 天气大型鱼/满月价值乘数（随渔获保留到卖出）
                        bigfish = bool(weather_cfg.get("bigfish")) and \
                            random.random() < weather_cfg["bigfish"] / 100.0
                        value_mult = self._weather_value_mult(weather_cfg, bigfish)
                        if bigfish:
                            upgrade_tag = f"{upgrade_tag}·🐋大鱼" if upgrade_tag else "·🐋大鱼"
                        # 闪光判定：1% 概率为闪光版，售价 ×3（pending 以 ✨闪光 前缀名携带闪光标记）
                        if random.random() < self.FISHING_SHINY_RATE:
                            name = f"{self.FISHING_SHINY_PREFIX}{name}"
                            price = int(price * self.FISHING_SHINY_MULT)
                            upgrade_tag = f"{upgrade_tag}·闪光×3" if upgrade_tag else "·闪光×3"
                        fish_names.append(f"{name}（{price}积分{upgrade_tag}）")
                        await session.execute(text(
                            "INSERT INTO fishing_pending(user_id, fish_name, value_mult, catch_time) "
                            "VALUES(:u, :n, :m, :t)"
                        ), {"u": uid, "n": name, "m": value_mult, "t": time.time()})
                        await session.execute(text(
                            "UPDATE fishing_stats SET total_caught=total_caught+1 WHERE user_id=:u"
                        ), {"u": uid})
                        # 更新每日钓鱼任务
                        await self._fishing_task_tick(session, uid, 1, name, price)
                        # 全群广播：传说级及以上（售价 > 1000 也触发）
                        if rarity in self.FISHING_BROADCAST_RARITIES or price > self.FISHING_BROADCAST_PRICE:
                            chain = [At(qq=str(uid))]
                            if rarity == "至高传说":
                                chain.append(Plain(
                                    f" 🌟🌟🌟 钓到了传说中的 {name}（价值{price}积分！概率{f'{prob:.6f}'.rstrip('0').rstrip('.')}%！！！）\n"
                                    f"此乃万中无一之奇迹！"
                                ))
                            else:
                                chain.append(Plain(
                                    f" 🎉🎉🎉 钓到了 {name}（价值{price}积分！概率{f'{prob:.6f}'.rstrip('0').rstrip('.')}%！！！）"
                                ))
                            if group_id:
                                broadcasts.append((platform_id, group_id, chain))
                    if junk and not fish_names:
                        notify("感觉有东西咬钩，拉上来一只破靴子，一无所得…")
                    elif fish_names:
                        prefix = "一次钓上两条！" if caught == 2 and fish_names else ""
                        notify(f"{prefix}有鱼上钩啦，{('、'.join(fish_names))} 进了鱼篓！")
                        await self._fishing_task_streak(session, uid, broke=False)
                elif event == "神秘宝箱":
                    amount = random.randint(self.FISHING_BOX_MIN, self.FISHING_BOX_MAX)
                    await self._add_points(session, uid, amount, "钓鱼宝箱")
                    notify(f"捞到一个神秘宝箱，开出 {amount} 积分！")
                elif event == "双倍宝箱":
                    amount = random.randint(100, 200)
                    await self._add_points(session, uid, amount, "钓鱼宝箱")
                    notify(f"捞到一个双倍宝箱，开出 {amount} 积分！")
                elif event == "沉船宝藏":
                    amount = random.randint(80, 150)
                    await self._add_points(session, uid, amount, "钓鱼宝藏")
                    notify(f"发现一处沉船宝藏，获得 {amount} 积分！")
                elif event == "老渔夫传授":
                    await self._add_points(session, uid, 200, "钓鱼奇遇")
                    notify("遇到一位老渔夫传授毕生经验，获得 200 积分！")
                elif event == "渔协补贴":
                    await self._add_points(session, uid, 100, "钓鱼补贴")
                    notify("渔业协会发放挂机补贴，+100 积分！")
                elif event == "钓到旧靴子":
                    amount = random.randint(5, 20)
                    await self._add_points(session, uid, amount, "钓鱼杂货")
                    notify(f"钓到一只旧靴子，里面居然藏着 {amount} 积分！")
                elif event == "钓到漂流瓶":
                    amount = random.randint(10, 50)
                    await self._add_points(session, uid, amount, "钓鱼杂货")
                    notify(f"钓到一个漂流瓶，瓶中藏着 {amount} 积分！")
                elif event == "钓到旧轮胎":
                    await self._add_points(session, uid, 10, "钓鱼杂货")
                    notify("钓到一个旧轮胎，卖废品得了 10 积分…")
                elif event == "钓到易拉罐":
                    await self._add_points(session, uid, 5, "钓鱼杂货")
                    notify("钓到一个易拉罐，回收得 5 积分…")
                elif event == "钓到无名古币":
                    await self._add_points(session, uid, 150, "钓鱼奇遇")
                    notify("钓到一枚无名古币，收藏家出价 150 积分收购！")
                elif event == "幸运日":
                    expire = time.time() + self.FISHING_LUCKY_HOURS * 3600
                    await session.execute(text(
                        "UPDATE fishing_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify(f"时来运转！获得 {self.FISHING_LUCKY_HOURS} 小时幸运buff，期间必定上钩！")
                elif event == "龙王赐福":
                    expire = time.time() + 4 * 3600
                    await session.execute(text(
                        "UPDATE fishing_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify("龙王赐福！获得 4 小时超级幸运buff，期间必定上钩！")
                elif event == "美人鱼祝福":
                    expire = time.time() + 3 * 3600
                    await session.execute(text(
                        "UPDATE fishing_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify("美人鱼的祝福！获得 3 小时幸运buff，期间必定上钩！")
                elif event == "螃蟹夹饵":
                    # 额外损失最多 FISHING_CRAB_BAITS 个鱼饵
                    lost = min(self.FISHING_CRAB_BAITS, bait - 1)
                    if lost > 0:
                        await session.execute(
                            text("UPDATE fishing_baits SET count=count-:c WHERE user_id=:u"),
                            {"c": lost, "u": uid},
                        )
                        notify(f"的鱼饵被螃蟹夹走了，额外损失 {lost} 个…")
                    else:
                        notify("碰到一只螃蟹，好在没夹走鱼饵")
                elif event in ("钓具保养", "设备进水", "渔政罚款", "撞上暗礁",
                               "河豚毒素", "鲨鱼来袭", "鱼钩卷刃", "巨浪拍船",
                               "鱼群暴动", "冰雹灾害", "水蛇惊魂"):
                    fine_map = {
                        "钓具保养": self.FISHING_FINE_MAINTAIN,
                        "设备进水": self.FISHING_FINE_DEVICE,
                        "渔政罚款": self.FISHING_FINE_POLICE,
                        "撞上暗礁": self.FISHING_FINE_REEF,
                        "河豚毒素": 200, "鲨鱼来袭": 250, "鱼钩卷刃": 80,
                        "巨浪拍船": 50, "鱼群暴动": 120, "冰雹灾害": 180, "水蛇惊魂": 100,
                    }
                    fine_desc = {
                        "钓具保养": "钓具该保养了，花 30 积分换个新鱼线",
                        "设备进水": "设备进水损坏，花 40 积分维修",
                        "渔政罚款": "被渔政突击检查，无证捕捞罚款 100 积分！",
                        "撞上暗礁": "船撞上暗礁！维修费 150 积分…",
                        "河豚毒素": "处理河豚时中毒，医药费 200 积分！",
                        "鲨鱼来袭": "鲨鱼撞坏渔船，赔偿 250 积分！",
                        "鱼钩卷刃": "鱼钩卷刃无法使用，花 80 积分更换",
                        "巨浪拍船": "巨浪拍上船头，设备受损 50 积分",
                        "鱼群暴动": "鱼群暴动撞翻鱼篓，损失 120 积分",
                        "冰雹灾害": "遭遇冰雹，船顶被砸 180 积分",
                        "水蛇惊魂": "被水蛇吓到扭伤腰，医药费 100 积分",
                    }
                    amount = fine_map[event]
                    # 余额不足时只扣到 0，避免事务失败中断判定
                    fine = min(int(amount), int(await self._balance(session, uid)))
                    if fine > 0:
                        await self._add_points(session, uid, -fine, f"钓鱼罚款-{event}")
                        notify(f"{fine_desc[event]}（-{fine} 积分）")
                    else:
                        notify(f"{fine_desc[event]}（穷得叮当响，赊账了喵…）")
                elif event in ("鱼竿断裂", "海怪来袭", "雷电击中"):
                    await session.execute(
                        text("UPDATE fishing_rods SET status='broken' WHERE id=:i"), {"i": rid}
                    )
                    if event == "鱼竿断裂":
                        notify("啪！鱼竿断了，记得 /修鱼竿 哦~")
                    elif event == "海怪来袭":
                        notify("被海怪吓了一跳，鱼跑了，鱼竿也断了…")
                    else:
                        fine = min(300, int(await self._balance(session, uid)))
                        if fine > 0:
                            await self._add_points(session, uid, -fine, "钓鱼罚款-雷电击中")
                        notify(f"雷电击中船桅！设备烧毁损失 {fine} 积分，鱼竿也断了…")
                elif event in ("磁暴干扰", "灯塔故障"):
                    # 挂机中断：鱼竿回到 idle（无需修理）
                    await session.execute(
                        text("UPDATE fishing_rods SET status='idle' WHERE id=:i"), {"i": rid}
                    )
                    notify("磁暴干扰了设备，挂机中断休息…" if event == "磁暴干扰"
                           else "灯塔故障一片漆黑，提前收工…")
                elif event == "鱼篓破洞":
                    lost_n = random.randint(1, 3)
                    lost_rows = (await session.execute(text(
                        "SELECT id, fish_name, is_shiny FROM fishing_inventory WHERE user_id=:u "
                        "ORDER BY RANDOM() LIMIT :n"
                    ), {"u": uid, "n": lost_n})).all()
                    if lost_rows:
                        for r in lost_rows:
                            await session.execute(text(
                                "DELETE FROM fishing_inventory WHERE id=:i"
                            ), {"i": r[0]})
                        lost_names = "、".join(
                            (f"{self.FISHING_SHINY_PREFIX}{r[1]}" if int(r[2] or 0) else str(r[1]))
                            for r in lost_rows
                        )
                        notify(f"鱼篓破了个洞，{lost_names} 溜走了…")
                    else:
                        notify("鱼篓破了个洞，好在鱼篓是空的…")
                elif event == "海鸥偷食":
                    lost = min(2, bait - 1)
                    if lost > 0:
                        await session.execute(
                            text("UPDATE fishing_baits SET count=count-:c WHERE user_id=:u"),
                            {"c": lost, "u": uid},
                        )
                        notify(f"海鸥俯冲偷食，损失 {lost} 个鱼饵…")
                    else:
                        notify("海鸥俯冲偷食，好在没偷到鱼饵")
                elif event == "大鱼拔河":
                    notify("和大鱼拔河输了，眼睁睁看它跑掉…")
                elif event == "暴风雨":
                    notify("遇上暴风雨，空手而归…")
                # 空钩：普通事件也播报一下
                elif event == "空钩":
                    notify("守了半天，只有鱼饵被啃了，啥也没钓到…")
                    await self._fishing_task_streak(session, uid, broke=True)
                elif event in ("水草缠竿", "暗流漩涡", "锚被卡住"):
                    skip_desc = {
                        "水草缠竿": "水草缠住鱼竿，折腾半天才解开，本次判定跳过…",
                        "暗流漩涡": "遇上暗流漩涡，鱼漂打转，本次判定跳过…",
                        "锚被卡住": "锚被水底石头卡住，忙活半天啥也没捞到…",
                    }
                    notify(skip_desc[event])
                elif event in ("雾锁海面", "乌贼喷墨", "海市蜃楼", "钓到水草团"):
                    fog_desc = {
                        "雾锁海面": "大雾弥漫海面，啥也看不见，空手而归…",
                        "乌贼喷墨": "乌贼喷了一船墨，黑漆漆啥也没有…",
                        "海市蜃楼": "看到一条大鱼跃出水面，可惜只是海市蜃楼…",
                        "钓到水草团": "拉上来一大团水草，一无所得…",
                    }
                    notify(fog_desc[event])
                # 自动收鱼器生效中：本竿判定结束后把渔获（含本轮新钓的）直接收进鱼篓
                if self._shop_active(self._active_shop or {}, "auto"):
                    got = await self._fishing_auto_collect(session, uid)
                    if got:
                        notify(f"的自动收鱼器把 {got} 条鱼收进了鱼篓")
                # 系统钱包奖池抽成：上钩判定有概率从资金池抽比例积分奖励玩家
                if event in multi_map:
                    reward_info = await self.trigger_fishing_reward(session, uid, user_name)
                    if reward_info:
                        reward, percent = reward_info
                        notify(
                            f"🎉 触发系统奖池抽成！从资金池获得 {reward} 积分"
                            f"（钱包的 {percent:.2f}%）"
                        )
            return True, "判定完成", (broadcasts, notices)

        ok, msg, data = await self._tx(fn)
        if not ok or not data:
            self.logger.warning(f"钓鱼判定未执行：{msg}")
            return
        broadcasts, notices = data
        self.logger.info(f"钓鱼判定完成：播报 {len(notices)} 条事件，{len(broadcasts)} 条高价广播")
        # 事务外发送全群广播，避免阻塞数据库
        for platform_id, group_id, chain in broadcasts:
            await self._send_with_fallback(platform_id, group_id, chain, "钓鱼高价广播")
        # 事件播报：按群聚合所有人的播报，合并渲染成一张图发送
        # 渲染优先级：平台 t2i 服务（text_to_image，网络失败自动落 Playwright）
        #           → 本地 PIL 汇总海报（fishing_poster）→ 纯文字兜底
        # 只按群号聚合（同群跨平台实例的播报合并为一条消息，避免拆成多张图）
        per_group: dict[str, dict] = {}
        if self.FISHING_BROADCAST_GROUPS:
            # 配置了播报群：所有源群的事件合并成一张图统一推送。
            # 播报群本身就是"全服实况频道"，若按源群逐张推送，
            # 玩家跨多个群挂机时播报群一个周期会收到多张图。
            per_group["__broadcast__"] = {
                "platform": "", "lines": [str(t[2]) for t in notices]}
        else:
            # 未配置播报群：只按群号聚合（同群跨平台实例合并为一条消息），
            # 且只发目标群（cross_group_fallback=False，别群的图不漏进来）
            for platform_id, group_id, text_line in notices:
                g = str(group_id)
                if g not in per_group:
                    per_group[g] = {"platform": str(platform_id), "lines": []}
                per_group[g]["lines"].append(str(text_line))
        for group_id, info in per_group.items():
            platform_id = info["platform"]
            lines = info["lines"]
            aggregate = "\n".join(lines)
            img_chain = None
            # 首选：自定义「烛之播报」模板走 t2i 服务（成员分卡、每条动态一行）
            if FISHING_T2I_TEMPLATE:
                members_d: dict[str, list] = {}
                m_order: list[str] = []
                for line in lines:
                    parts = line.split(" ", 2)
                    who = parts[1] if len(parts) >= 2 and parts[0] == "🎣" else "未知"
                    ev = parts[2] if len(parts) >= 3 else line
                    if who not in members_d:
                        members_d[who] = []
                        m_order.append(who)
                    members_d[who].append(ev)
                tmpl_data = {
                    "date": datetime.now(TZ).strftime("%m月%d日 %H:%M"),
                    "members": [
                        {"name": w, "events": members_d[w]} for w in m_order
                    ],
                }
                try:
                    raw = await _t2i_render_direct(FISHING_T2I_TEMPLATE, tmpl_data)
                    img_chain = [Image.fromBase64(base64.b64encode(raw).decode())]
                except Exception:
                    self.logger.exception("烛之播报直连 t2i 渲染失败，尝试平台 t2i 策略")
                    img_chain = None
                if img_chain is None:
                    try:
                        renderer = _get_t2i_net_renderer()
                        ret = await renderer.render_custom_template(
                            FISHING_T2I_TEMPLATE, tmpl_data, return_url=True,
                        )
                        if isinstance(ret, str) and ret.startswith("http"):
                            img_chain = [Image.fromURL(ret)]
                    except Exception:
                        self.logger.exception("烛之播报平台 t2i 策略也失败，改用本地 PIL 海报")
                        img_chain = None
            # 其次：本地 PIL 汇总海报（自带字体，不依赖服务器环境）
            if img_chain is None and _render_fishing_batch is not None:
                img_path = None
                try:
                    fd, img_path = tempfile.mkstemp(prefix="fishing_bcast_", suffix=".png")
                    os.close(fd)
                    _render_fishing_batch(lines, img_path)
                    img_chain = [Image.fromFileSystem(img_path)]
                except Exception:
                    self.logger.exception("钓鱼播报汇总图渲染失败，本次回退文字播报")
                    img_chain = None
                    if img_path and os.path.exists(img_path):
                        try:
                            os.remove(img_path)
                        except OSError:
                            pass
            if img_chain is not None:
                try:
                    await self._send_with_fallback(
                        platform_id, group_id, img_chain, "钓鱼播报汇总图",
                        cross_group_fallback=False,
                    )
                finally:
                    # 清理本地临时文件（仅本地渲染路径产生的 mkstemp 文件）
                    for c in img_chain:
                        try:
                            fp = str(getattr(c, "path", "") or "")
                            if fp.startswith(tempfile.gettempdir()) and "fishing_bcast_" in fp and os.path.exists(fp):
                                os.remove(fp)
                        except Exception:
                            pass
            else:
                await self._send_with_fallback(
                    platform_id, group_id, [Plain(aggregate)], "钓鱼播报",
                    cross_group_fallback=False,
                )

    async def _fishing_daily_reset(self):
        """定时任务：每天凌晨 0 点重置今日统计（today_count / today_date）"""
        async def fn(session):
            await session.execute(text(
                "UPDATE fishing_stats SET today_count=0, today_date=:d"
            ), {"d": date.today().isoformat()})
            return True, "今日钓鱼统计已重置", None

        await self._tx(fn)

    async def _fishing_grant_titles(
        self, session, user_id: str, collected: set[str]
    ) -> list[str]:
        """图鉴收集奖励判定（必须在事务内调用），返回奖励提示列表。

        称号规则：
        - 钓到烛心 → 烛心持有者；钓到闲鱼 → 闲鱼之王（纯称号，无积分）
        - 同时拥有烛心和闲鱼 → 额外 1000 积分 + 至高传说之主（只发一次）
        - 集齐全部 102 种 → 5000 积分 + 万物之主（只发一次）
        """
        rewards: list[str] = []
        if {"烛心", "闲鱼"} <= collected:
            already = (await session.execute(text(
                "SELECT 1 FROM point_transactions WHERE user_id=:u AND operation='钓鱼至高奖励'"
            ), {"u": user_id})).first()
            if not already:
                await self._add_points(
                    session, user_id, self.FISHING_BOTH_LEGEND_REWARD, "钓鱼至高奖励"
                )
                rewards.append(
                    f"🏆 同时拥有烛心和闲鱼：获得「至高传说之主」称号 "
                    f"+{self.FISHING_BOTH_LEGEND_REWARD} 积分！"
                )
        if len(collected) >= len(FISH_POOL):
            already = (await session.execute(text(
                "SELECT 1 FROM point_transactions WHERE user_id=:u AND operation='钓鱼集齐奖励'"
            ), {"u": user_id})).first()
            if not already:
                await self._add_points(
                    session, user_id, self.FISHING_FULL_REWARD, "钓鱼集齐奖励"
                )
                rewards.append(
                    f"👑 集齐全部 {len(FISH_POOL)} 种鱼：获得「万物之主」称号 "
                    f"+{self.FISHING_FULL_REWARD} 积分！"
                )
        return rewards

    @filter.command("买鱼竿")
    async def fishing_buy_rod(self, event: AstrMessageEvent):
        """/买鱼竿 —— 花费 200 积分购买一根鱼竿（最多 5 根）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买鱼竿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._ensure_user(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cnt = (await session.execute(text(
                "SELECT COUNT(*) FROM fishing_rods WHERE user_id=:u"
            ), {"u": user_id})).first()
            if int(cnt[0]) >= self.MAX_RODS:
                raise _BizError(f"鱼竿已经满 {self.MAX_RODS} 根啦，不能再买了喵~")
            slots = {int(r[0]) for r in (await session.execute(text(
                "SELECT slot FROM fishing_rods WHERE user_id=:u"
            ), {"u": user_id})).all()}
            slot = next(i for i in range(1, self.MAX_RODS + 1) if i not in slots)
            bal = await self._total_balance(session, user_id)
            if bal < self.ROD_COST:
                raise _BizError(
                    f"积分不足喵~ 买鱼竿需要 {self.ROD_COST} 积分，你只有 {bal} 积分"
                )
            await self._add_points(session, user_id, -self.ROD_COST, "buy_rod")
            await session.execute(text(
                "INSERT INTO fishing_rods(user_id, slot, status, created_at) "
                "VALUES(:u, :s, 'idle', :t)"
            ), {"u": user_id, "s": slot, "t": time.time()})
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🎣 购买成功！获得 {slot} 号鱼竿，花费 {self.ROD_COST} 积分，"
                f"当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("买鱼饵")
    async def fishing_buy_bait(self, event: AstrMessageEvent):
        """/买鱼饵 [数量] —— 10 积分/个购买鱼饵，不填数量默认买 1 个"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买鱼饵")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        count = 1
        args = self._strip_command(event, "买鱼饵")
        if args:
            try:
                count = int(args.split()[0])
                if count <= 0:
                    raise ValueError
            except ValueError:
                yield event.plain_result("鱼饵数量得是正整数喵~")
                return

        async def fn(session):
            await self._ensure_user(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cost = count * self.BAIT_COST
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"积分不足喵~ 买 {count} 个鱼饵需要 {cost} 积分，你只有 {bal} 积分"
                )
            await self._add_points(session, user_id, -cost, "buy_bait")
            await session.execute(text(
                "INSERT INTO fishing_baits(user_id, count) VALUES(:u, :c) "
                "ON CONFLICT(user_id) DO UPDATE SET count=fishing_baits.count+:c"
            ), {"u": user_id, "c": count})
            bait = await self._fishing_bait_count(session, user_id)
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🪱 购买成功！获得 {count} 个鱼饵（花费 {cost} 积分），"
                f"现有鱼饵 {bait} 个，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("挂机钓鱼")
    async def fishing_start(self, event: AstrMessageEvent):
        """/挂机钓鱼 [编号] —— 让鱼竿开始挂机，不填编号则全部待机鱼竿一起挂机"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挂机钓鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")
        args = self._strip_command(event, "挂机钓鱼")

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            rods = (await session.execute(text(
                "SELECT id, slot, status FROM fishing_rods WHERE user_id=:u ORDER BY slot"
            ), {"u": user_id})).all()
            if not rods:
                raise _BizError("你还没有鱼竿，先 /买鱼竿 喵~")
            # 选出目标鱼竿
            if args:
                try:
                    slot = int(args.split()[0])
                except ValueError:
                    raise _BizError("鱼竿编号得是数字喵~")
                matched = [r for r in rods if int(r[1]) == slot]
                if not matched:
                    raise _BizError(f"没有 {slot} 号鱼竿喵~ 发 /鱼竿列表 查看你的鱼竿")
                rod = matched[0]
                if rod[2] == "fishing":
                    raise _BizError(f"{slot} 号鱼竿已经在挂机啦喵~")
                if rod[2] == "broken":
                    raise _BizError(f"{slot} 号鱼竿断了，先 /修鱼竿 {slot} 喵~")
                targets = [rod]
            else:
                targets = [r for r in rods if r[2] == "idle"]
                if not targets:
                    raise _BizError("没有待机的鱼竿喵~（挂机中或损坏的竿不能用）")
            bait = await self._fishing_bait_count(session, user_id)
            if bait <= 0:
                raise _BizError("没有鱼饵啦，先 /买鱼饵 再来钓鱼喵~")
            weather_key, weather_cfg = await self._weather_today(session)
            # 鱼饵不足以全覆盖时只启动部分鱼竿（每次判定每竿消耗 1 个鱼饵）
            start_n = min(len(targets), bait)
            for rod in targets[:start_n]:
                await session.execute(text(
                    "UPDATE fishing_rods SET status='fishing', platform_id=:p, group_id=:g "
                    "WHERE id=:i"
                ), {"p": platform_id, "g": group_id, "i": rod[0]})
            msg = (
                f"🎣 今日天气{weather_cfg['name']}！{weather_cfg['desc']}！\n"
                f"{start_n} 根鱼竿开始挂机啦！每 {self.CHECK_INTERVAL} 分钟判定一次，"
                f"每次每竿消耗 1 个鱼饵，钓到的鱼用 /收鱼 收取喵~"
            )
            if start_n < len(targets):
                msg += f"\n（鱼饵只够 {start_n} 根竿，剩下的先补鱼饵喵~）"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("收鱼")
    async def fishing_collect(self, event: AstrMessageEvent):
        """/收鱼 —— 把 pending 里的鱼收进鱼篓，并记录图鉴/判定收集奖励"""
        ok_gate, msg_gate = await self._check_group_gate(event, "收鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            pending = (await session.execute(text(
                "SELECT fish_name, value_mult, COUNT(*) FROM fishing_pending WHERE user_id=:u "
                "GROUP BY fish_name, value_mult"
            ), {"u": user_id})).all()
            if not pending:
                raise _BizError("还没钓到鱼喵~ 挂机中的鱼竿每 30 分钟判定一次，等等再来")
            total = 0
            new_species: list[str] = []
            details: list[str] = []
            new_shiny = 0
            for name, mult, cnt in pending:
                name = str(name)
                cnt = int(cnt)
                mult = float(mult or 1)
                total += cnt
                base, is_shiny = self._shiny_split(name)
                price = int(self._shiny_price(base, is_shiny) * mult)
                rarity = FISH_POOL.get(base, (0, "未知", 0.0))[1]
                # 并入鱼篓（闪光版与普通版分行存放）
                await session.execute(text(
                    "INSERT INTO fishing_inventory(user_id, fish_name, is_shiny, value_mult, count) "
                    "VALUES(:u, :n, :s, :m, :c) "
                    "ON CONFLICT(user_id, fish_name, is_shiny) DO UPDATE SET "
                    "count=fishing_inventory.count+:c"
                ), {"u": user_id, "n": base, "s": is_shiny, "m": mult, "c": cnt})
                # 记录图鉴（钓到过即收集，卖鱼不影响进度；闪光版独立收录）
                result = await session.execute(text(
                    "INSERT OR IGNORE INTO fishing_collection(user_id, fish_name, first_time) "
                    "VALUES(:u, :n, :t)"
                ), {"u": user_id, "n": name, "t": time.time()})
                if result.rowcount == 1:
                    new_species.append(f"{name}（{rarity}·{price}积分）")
                    if is_shiny:
                        new_shiny += 1
                details.append(f"{name}×{cnt}")
            await session.execute(
                text("DELETE FROM fishing_pending WHERE user_id=:u"), {"u": user_id}
            )
            # 图鉴收集奖励判定（烛心/闲鱼/集齐）
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            rewards = await self._fishing_grant_titles(session, user_id, collected)
            # 图鉴榜：按永久图鉴记录统计，卖鱼后也不会减少
            await session.execute(text(
                "UPDATE fishing_stats SET collection_count=:c WHERE user_id=:u"
            ), {"u": user_id, "c": len(collected)})
            # 闪光收集数同步 + 阶段奖励判定
            shiny_n, shiny_rewards = await self._fishing_shiny_sync(session, user_id)
            rewards.extend(shiny_rewards)
            msg = f"🐟 收鱼成功！本次进篓 {total} 条：{'、'.join(details)}喵~"
            if new_species:
                msg += f"\n✨ 图鉴新收录：{'、'.join(new_species)}"
            if new_shiny:
                msg += f"\n✨ 这是你的第 {shiny_n} 种闪光鱼！"
            for line in rewards:
                msg += f"\n{line}"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("卖鱼")
    async def fishing_sell(self, event: AstrMessageEvent):
        """/卖鱼 —— 一键卖出鱼篓里所有鱼，按鱼类售价换算积分"""
        ok_gate, msg_gate = await self._check_group_gate(event, "卖鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            rows = (await session.execute(text(
                "SELECT fish_name, is_shiny, value_mult, count FROM fishing_inventory WHERE user_id=:u"
            ), {"u": user_id})).all()
            if not rows:
                raise _BizError("鱼篓里没有鱼可以卖喵~ 先 /挂机钓鱼 再来")
            total = 0
            fish_cnt = 0
            details: list[str] = []
            for name, is_shiny, mult, cnt in rows:
                name = str(name)
                cnt = int(cnt or 0)
                is_shiny = int(is_shiny or 0)
                mult = float(mult or 1)
                # 闪光版 ×3，大型鱼/满月乘数随渔获保留
                price = int(self._shiny_price(name, is_shiny) * mult)
                total += price * cnt
                fish_cnt += cnt
                display = f"{self.FISHING_SHINY_PREFIX}{name}" if is_shiny else name
                if mult >= self.FISHING_BIGFISH_MULT:
                    display = f"🐋{display}"
                details.append(f"{display}×{cnt}")
            # 卖鱼收入进账并记录流水（operation='sell_fish'），商店时效加成在此兑现
            shop = await self._get_shop_items(session, user_id)
            vip_on = self._shop_active(shop, "vip")
            double_on = self._shop_active(shop, "double")
            if vip_on:
                total = int(total * 1.1)
            eff_total = total * 2 if double_on else total
            # 组队收益加成
            team_mult = await self._team_bonus_mult(session, user_id)
            if team_mult > 1.0:
                eff_total = int(eff_total * team_mult)
            # 修仙加成：境界（每大境界+5%）+ 宗门（每级+1.5%）
            x_realm_mult, x_sect_mult = await self._xiuxian_income_bonus(session, user_id)
            if x_realm_mult > 1.0:
                eff_total = int(eff_total * x_realm_mult)
            if x_sect_mult > 1.0:
                eff_total = int(eff_total * x_sect_mult)
            await self._add_points(session, user_id, eff_total, "sell_fish", earned=eff_total)
            await session.execute(text(
                "UPDATE fishing_stats SET total_income=total_income+:t, "
                "total_fish_count=total_fish_count+:c WHERE user_id=:u"
            ), {"u": user_id, "t": eff_total, "c": fish_cnt})
            # 兼容旧数据：从本次售出的鱼中维护最高价值鱼
            best_name, best_value = max(
                ((str(name), int(FISH_POOL.get(str(name), (0,))[0])) for name, _ in rows),
                key=lambda item: item[1], default=(None, 0)
            )
            current_best = (await session.execute(text(
                "SELECT best_fish_value FROM fishing_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            if best_name and (not current_best or best_value > int(current_best[0] or 0)):
                await session.execute(text(
                    "UPDATE fishing_stats SET best_fish_name=:n, best_fish_value=:v WHERE user_id=:u"
                ), {"u": user_id, "n": best_name, "v": best_value})
            await session.execute(
                text("DELETE FROM fishing_inventory WHERE user_id=:u"), {"u": user_id}
            )
            new_bal = await self._balance(session, user_id)
            return True, (
                f"💰 卖鱼成功！共卖出 {fish_cnt} 条：{'、'.join(details)}\n"
                f"收入 {total} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("鱼图鉴")
    async def fishing_book(self, event: AstrMessageEvent):
        """/鱼图鉴 —— 查看已收集鱼类种类与总进度（共 102 种）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "鱼图鉴")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            # 闪光版以「✨闪光」前缀独立收录，与普通版分开统计
            prefix = self.FISHING_SHINY_PREFIX
            normal = {n for n in collected if not n.startswith(prefix)}
            shiny = {n for n in collected if n.startswith(prefix)}
            lines = [
                "📊 【鱼类图鉴】",
                f"已收集：{len(normal)}/{len(FISH_POOL)}种（普通）",
                f"✨ 闪光收集：{len(shiny)}/{len(FISH_POOL)}种（闪光）",
            ]
            for rarity, (_total_prob, fishes) in FISH_TABLE.items():
                names = {n for n, _p in fishes}
                lines.append(f"{rarity}：{len(names & normal)}/{len(names)}")
            if shiny:
                lines.append("✨ 已收集的闪光鱼：")
                lines.extend(f"✨ {n[len(prefix):]} ✅" for n in sorted(shiny))
            next_tier = next(
                ((need, pts) for need, pts, _t in self.FISHING_SHINY_REWARDS if len(shiny) < need),
                None,
            )
            if next_tier:
                lines.append(
                    f"🎯 下一阶段奖励：收集 {next_tier[0]} 种闪光鱼 → +{next_tier[1]} 积分"
                )
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("钓鱼天气")
    async def fishing_weather_cmd(self, event: AstrMessageEvent):
        """/钓鱼天气 —— 查看今日钓鱼天气、效果加成与刷新倒计时"""
        ok_gate, msg_gate = await self._check_group_gate(event, "钓鱼天气")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return

        async def fn(session):
            _wkey, wcfg = await self._weather_today(session)
            now = datetime.now(self._beijing_tz)
            tomorrow = (now + timedelta(days=1)).replace(
                hour=0, minute=0, second=0, microsecond=0
            )
            left = tomorrow - now
            hours = left.seconds // 3600
            minutes = (left.seconds % 3600) // 60
            msg = (
                "🌤️ 【今日钓鱼天气】\n"
                f"天气：{wcfg['name']}\n"
                f"效果：{wcfg['desc']}\n"
                f"建议：{wcfg['advice']}\n"
                f"距离下次刷新：{hours}小时{minutes}分钟"
            )
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("鱼竿列表")
    async def fishing_rod_list(self, event: AstrMessageEvent):
        """/鱼竿列表 —— 查看每根鱼竿的状态和鱼饵余量"""
        ok_gate, msg_gate = await self._check_group_gate(event, "鱼竿列表")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        status_text = {"idle": "待机", "fishing": "挂机中", "broken": "已损坏"}

        async def fn(session):
            rods = (await session.execute(text(
                "SELECT slot, status FROM fishing_rods WHERE user_id=:u ORDER BY slot"
            ), {"u": user_id})).all()
            if not rods:
                raise _BizError("你还没有鱼竿，先 /买鱼竿 喵~")
            bait = await self._fishing_bait_count(session, user_id)
            lines = [f"🎣 鱼竿列表（鱼饵余量：{bait} 个）"]
            for slot, status in rods:
                lines.append(f"{int(slot)} 号竿：{status_text.get(str(status), str(status))}")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("鱼塘")
    async def pond_status(self, event: AstrMessageEvent):
        """/鱼塘 —— 查看自己的鱼塘等级与加成效果"""
        ok_gate, msg_gate = await self._check_group_gate(event, "鱼塘")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            row = (await session.execute(text(
                "SELECT pond_level FROM fishing_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            level = int(row[0] or 1) if row else 1
            bait_red = self.POND_BAIT_REDUCTION.get(level, 0)
            rare_bonus = self.POND_RARE_BONUS.get(level, 0)
            max_hours = self.POND_BASE_HOURS + self.POND_EXTRA_HOURS.get(level, 0)
            lines = [
                "🏊 【鱼塘状态】",
                f"等级：{level}级",
                f"鱼饵消耗：-{bait_red}%",
                f"稀有鱼转化：普通鱼有 {rare_bonus}% 概率升级为稀有鱼",
                f"挂机时间上限：{max_hours}小时",
            ]
            if level < self.POND_MAX_LEVEL:
                nxt = level + 1
                cost = self.POND_UPGRADE_COST.get(nxt, 0)
                lines.append(f"升级到{nxt}级需要：{cost}积分")
                lines.append("发送 /升级鱼塘 升级！")
            else:
                lines.append("✅ 已满级，鱼塘欣欣向荣！")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("升级鱼塘")
    async def pond_upgrade(self, event: AstrMessageEvent):
        """/升级鱼塘 —— 花费积分永久提升钓鱼收益"""
        ok_gate, msg_gate = await self._check_group_gate(event, "升级鱼塘")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            row = (await session.execute(text(
                "SELECT pond_level FROM fishing_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            level = int(row[0] or 1) if row else 1
            if level >= self.POND_MAX_LEVEL:
                raise _BizError(f"✅ 已满级！当前等级：{self.POND_MAX_LEVEL}级")
            nxt = level + 1
            cost = self.POND_UPGRADE_COST.get(nxt, 0)
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"❌ 积分不足！升级需要 {cost} 积分，当前余额：{bal} 积分"
                )
            await self._add_points(session, user_id, -cost, "pond_upgrade", spent=cost)
            await session.execute(
                text("UPDATE fishing_stats SET pond_level=:l WHERE user_id=:u"),
                {"u": user_id, "l": nxt},
            )
            bait_red = self.POND_BAIT_REDUCTION.get(nxt, 0)
            rare_bonus = self.POND_RARE_BONUS.get(nxt, 0)
            extra = self.POND_EXTRA_HOURS.get(nxt, 0)
            new_bal = await self._balance(session, user_id)
            add_effects = [f"鱼饵消耗-{bait_red}%", f"稀有鱼概率+{rare_bonus}%"]
            if extra:
                add_effects.append(f"挂机上限+{extra}小时")
            return True, (
                f"✅ 鱼塘升级成功！当前等级：{nxt}级\n"
                f"新增效果：{'，'.join(add_effects)}\n"
                f"花费 {cost} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 钓鱼每日任务 ====================
    async def _ensure_daily_fishing_tasks(self, session, user_id: str):
        """为今日生成每日任务（已有今日任务则跳过）"""
        today = date.today().isoformat()
        exist = (await session.execute(text(
            "SELECT 1 FROM fishing_tasks WHERE user_id=:u AND task_date=:d LIMIT 1"
        ), {"u": user_id, "d": today})).first()
        if exist:
            return
        types = random.sample(self.FISH_TASK_TYPES, 3)
        for t in types:
            req_opts = self.FISH_TASK_REQUIREMENTS[t]
            req = random.choice(req_opts)
            lo, hi = self.FISH_TASK_REWARD_RANGES[t]
            reward = random.randint(lo, hi)
            target = str(req)
            if t == "specific":
                target = random.choice(list(FISH_POOL.keys())[:196])
            elif t == "value":
                target = str(random.choice(self.FISH_TASK_REQUIREMENTS["value"]))
            req = int(target) if str(target).isdigit() else 1
            await session.execute(text(
                "INSERT INTO fishing_tasks(user_id, task_date, task_type, task_target, "
                "task_requirement, task_reward) VALUES(:u,:d,:ty,:tg,:rq,:rw)"
            ), {"u": user_id, "d": today, "ty": t, "tg": target,
                "rq": req, "rw": reward})

    async def _fishing_task_tick(self, session, user_id: str,
                                 n_fish: int = 0, name: str = "", value: int = 0):
        await self._ensure_daily_fishing_tasks(session, user_id)
        today = date.today().isoformat()
        tasks = (await session.execute(text(
            "SELECT id, task_type, task_target, task_requirement, task_progress, task_reward "
            "FROM fishing_tasks WHERE user_id=:u AND task_date=:d AND task_status='pending'"
        ), {"u": user_id, "d": today})).all()
        if not tasks:
            return
        for t in tasks:
            tid, ty, tg, req, prog, reward = t
            req = int(req); prog = int(prog or 0)
            if ty == "collection":
                cnt = (await session.execute(text(
                    "SELECT COUNT(DISTINCT fish_name) FROM fishing_collection WHERE user_id=:u"
                ), {"u": user_id})).first()
                distinct = int(cnt[0] or 0) if cnt else 0
                np = max(prog, min(distinct, req))
                await session.execute(text(
                    "UPDATE fishing_tasks SET task_progress=:p WHERE id=:i"),
                    {"p": np, "i": tid})
                complete = distinct >= req
            elif ty == "count":
                np = min(prog + n_fish, req)
                await session.execute(text(
                    "UPDATE fishing_tasks SET task_progress=:p WHERE id=:i"),
                    {"p": np, "i": tid})
                complete = np >= req
            elif ty == "specific":
                complete = name and name == tg and prog < 1
                if complete:
                    await session.execute(text(
                        "UPDATE fishing_tasks SET task_progress=1 WHERE id=:i"), {"i": tid})
            elif ty == "value":
                complete = prog < 1 and value >= int(tg)
                if complete:
                    await session.execute(text(
                        "UPDATE fishing_tasks SET task_progress=1 WHERE id=:i"), {"i": tid})
            else:  # combo
                complete = False
            if complete:
                await session.execute(text(
                    "UPDATE fishing_tasks SET task_status='completed' WHERE id=:i"), {"i": tid})
                await self._add_points(session, user_id, int(reward), "fishing_task")

    async def _fishing_task_streak(self, session, user_id: str, broke: bool):
        """维护今日连续成功数并推进 combo 任务"""
        today = date.today().isoformat()
        row = (await session.execute(text(
            "SELECT today_success FROM fishing_stats WHERE user_id=:u"
        ), {"u": user_id})).first()
        val = 0 if broke else (int(row[0] or 0) + (0 if broke else 1))
        if not broke:
            await session.execute(text(
                "UPDATE fishing_stats SET today_success=:s WHERE user_id=:u"),
                {"s": val, "u": user_id})
        await self._ensure_daily_fishing_tasks(session, user_id)
        tasks = (await session.execute(text(
            "SELECT id, task_type, task_target, task_requirement, task_progress "
            "FROM fishing_tasks WHERE user_id=:u AND task_date=:d "
            "AND task_type='combo' AND task_status='pending'"),
            {"u": user_id, "d": today})).all()
        for t in tasks:
            tid, ty, tg, req, prog = t
            req = int(req); nv = max(int(prog or 0), min(val, req))
            await session.execute(text(
                "UPDATE fishing_tasks SET task_progress=:p WHERE id=:i"),
                {"p": nv, "i": tid})
            if nv >= req:
                rw = (await session.execute(text(
                    "SELECT task_reward FROM fishing_tasks WHERE id=:i"), {"i": tid})).first()
                await session.execute(text(
                    "UPDATE fishing_tasks SET task_status='completed' WHERE id=:i"), {"i": tid})
                if rw and int(rw[0] or 0) > 0:
                    await self._add_points(session, user_id, int(rw[0]), "fishing_task")

    @filter.command("钓鱼任务")
    async def fishing_task_view(self, event: AstrMessageEvent):
        """/钓鱼任务 —— 查看今日钓鱼任务"""
        user_id = event.get_sender_id()
        today = date.today().isoformat()
        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            await self._ensure_daily_fishing_tasks(session, user_id)
            tasks = (await session.execute(text(
                "SELECT task_type, task_target, task_requirement, task_progress, "
                "task_reward, task_status FROM fishing_tasks "
                "WHERE user_id=:u AND task_date=:d ORDER BY id"),
                {"u": user_id, "d": today})).all()
            lines = ["📋 【今日钓鱼任务】"]
            done = 0
            for ty, tg, req, prog, rwd, st in tasks:
                req = int(req); p = int(prog or 0)
                if ty == "count":
                    disp = f"钓到{tg}条鱼"
                elif ty == "specific":
                    disp = f"钓到 1 条「{tg}」"
                elif ty == "value":
                    disp = f"钓到价值>{tg}的鱼"
                elif ty == "combo":
                    disp = f"连续上钩{req}次（不空钩）"
                else:
                    disp = f"钓到{req}种不同鱼"
                done += 1 if st == "completed" else 0
                mark = " ✅ 已领取" if st == "completed" else ""
                lines.append(f"• {disp}（{min(p,req)}/{req}）→ {rwd}积分{mark}")
            lines.append("─────────────")
            lines.append(f"完成进度：{done}/{len(tasks)}")
            if done < len(tasks):
                lines.append(f"还差 {len(tasks)-done} 个任务")
            else:
                bonus = (await session.execute(text(
                    "SELECT bonus_claimed FROM fishing_tasks WHERE user_id=:u "
                    "AND task_date=:d LIMIT 1"), {"u": user_id, "d": today})).first()
                if bonus and int(bonus[0] or 0):
                    lines.append(f"✅ 全部完成！额外奖励 {self.FISH_TASK_BONUS} 积分已领取！")
                else:
                    lines.append(f"🎉 全部完成！发 /领取任务奖励 领额外 {self.FISH_TASK_BONUS} 积分！")
            return True, "\n".join(lines), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("领取任务奖励")
    async def fishing_task_claim(self, event: AstrMessageEvent):
        """/领取任务奖励 —— 全部完成时发额外奖励"""
        user_id = event.get_sender_id()
        today = date.today().isoformat()
        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            await self._ensure_daily_fishing_tasks(session, user_id)
            pend = (await session.execute(text(
                "SELECT COUNT(*) FROM fishing_tasks WHERE user_id=:u AND task_date=:d "
                "AND task_status='pending'"), {"u": user_id, "d": today})).first()
            if pend and int(pend[0] or 0) > 0:
                raise _BizError(f"还有 {int(pend[0])} 个任务未完成，完成后再来喵~")
            b = (await session.execute(text(
                "SELECT bonus_claimed FROM fishing_tasks WHERE user_id=:u "
                "AND task_date=:d LIMIT 1"), {"u": user_id, "d": today})).first()
            if b and int(b[0] or 0):
                raise _BizError("今日额外奖励已领取喵~")
            await session.execute(text(
                "UPDATE fishing_tasks SET bonus_claimed=1 WHERE user_id=:u AND task_date=:d"),
                {"u": user_id, "d": today})
            await self._add_points(session, user_id, self.FISH_TASK_BONUS, "fishing_task_bonus")
            new_bal = await self._balance(session, user_id)
            return True, (f"🎉 全部完成！额外奖励 {self.FISH_TASK_BONUS} 积分已到账！\n"
                          f"当前积分：{new_bal} 喵~"), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 钓鱼商店 ====================
    async def _get_shop_items(self, session, user_id: str) -> dict:
        """读取玩家已购道具。

        v4.22.26 起为时效制：非 onekey 的值=到期时间戳；生效判断用 _shop_active。
        旧版叠加数量制（值为小整数）读取时视为失效并自动清除 —— 旧效果统一作废重算。
        """
        if not self.feature_flags.get("enable_fish_shop", False):
            return {}
        row = (await session.execute(text(
            "SELECT items FROM fishing_shop WHERE user_id=:u"), {"u": user_id})).first()
        if not row:
            await session.execute(text(
                "INSERT INTO fishing_shop(user_id, items, updated_at) VALUES(:u,'{}',:t)"),
                {"u": user_id, "t": time.time()})
            return {}
        try:
            items = json.loads(row[0] or "{}")
        except Exception:
            return {}
        if not isinstance(items, dict):
            return {}
        cleaned: dict = {}
        for k, v in items.items():
            if k == "onekey":
                cleaned[k] = 1
                continue
            try:
                v = float(v)
            except (TypeError, ValueError):
                continue
            if v > 1e9:  # 只有到期时间戳有效；旧版叠加数量（小整数）全部作废
                cleaned[k] = v
        if len(cleaned) != len(items):
            await self._save_shop_items(session, user_id, cleaned)
        return cleaned

    async def _save_shop_items(self, session, user_id: str, items: dict):
        await session.execute(text(
            "UPDATE fishing_shop SET items=:i, updated_at=:t WHERE user_id=:u"),
            {"u": user_id, "i": json.dumps(items, ensure_ascii=False), "t": time.time()})

    @filter.command("钓鱼商店")
    async def fishing_shop_view(self, event: AstrMessageEvent):
        """/钓鱼商店 —— 查看可用钓鱼道具"""
        if not self.feature_flags.get("enable_fish_shop", False):
            yield event.plain_result("🎏 渔具商店暂时关闭，敬请期待喵~")
            return

        user_id = event.get_sender_id()
        async def fn(session):
            items = await self._get_shop_items(session, user_id)
            # 一键钓鱼通行证以 fishing_stats 标记为准（可脱离商店直接 /一键钓鱼 购买）
            await self._fishing_ensure_stats(session, user_id)
            onekey_on = (await session.execute(text(
                "SELECT onekey_fishing FROM fishing_stats WHERE user_id=:u"), {"u": user_id})).first()
            if onekey_on and int(onekey_on[0] or 0) > 0:
                items["onekey"] = 1
            lines = ["🏪 【钓鱼商店】"]
            for idx, (key, name, price, desc, icon, hours) in enumerate(self.SHOP_ITEMS, 1):
                if key == "onekey":
                    cnt = int(items.get(key, 0) or 0)
                    owned = f"｜拥有×{cnt}" if cnt > 0 else "｜永久"
                else:
                    remain = self._shop_remaining_text(items, key)
                    owned = f"｜⏳生效中·剩{remain}" if remain else f"｜时效{self._shop_hours_text(hours)}"
                lines.append(f"{idx}. {icon} {name} {price}积分 {owned}\n   {desc}")
            lines.append("发送 /购买鱼具 [编号] 购买（时效道具生效中不可重复购买，过期后可续购）")
            return True, "\n".join(lines), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("购买渔具", alias={"购买鱼具", "购买道具"})
    async def fishing_shop_buy(self, event: AstrMessageEvent):
        """/购买渔具 [编号] —— 购买钓鱼商店道具"""
        if not self.feature_flags.get("enable_fish_shop", False):
            yield event.plain_result("🎏 渔具商店暂时关闭，敬请期待喵~")
            return
        user_id = event.get_sender_id()
        text = self._strip_command(event, "购买渔具").strip()
        if not text:
            yield event.plain_result("用法：/购买渔具 [编号]（发 /钓鱼商店 查看）")
            return
        try:
            idx = int(text.split()[0])
        except ValueError:
            yield event.plain_result("请填商品编号数字喵~")
            return
        if not (1 <= idx <= len(self.SHOP_ITEMS)):
            yield event.plain_result("没有这个商品喵~")
            return
        key, name, price, desc, icon, hours = self.SHOP_ITEMS[idx - 1]
        async def fn(session):
            items = await self._get_shop_items(session, user_id)
            if key == "onekey":
                # 通行证永久有效，无需重复购买
                await self._fishing_ensure_stats(session, user_id)
                if await self._fishing_onekey_owned(session, user_id):
                    raise _BizError("你已经有一键钓鱼通行证了喵~ 直接发 /一键钓鱼 使用")
            elif self._shop_active(items, key):
                remain = self._shop_remaining_text(items, key)
                raise _BizError(f"{name}生效中（剩 {remain}），不能重复购买喵~ 过期后再来续购")
            bal = await self._total_balance(session, user_id)
            if bal < price:
                raise _BizError(f"积分不足！购买需 {price} 积分，当前余额：{bal}")
            await self._add_points(session, user_id, -price, "fish_shop", spent=price)
            if key == "onekey":
                # 注意：本函数局部 text 变量遮蔽了 sqlalchemy.text，必须走辅助方法
                await self._fishing_set_onekey(session, user_id)
                items[key] = 1
            else:
                # 时效道具：写入到期时间戳，同道具生效期内不可重复购买
                items[key] = time.time() + hours * 3600
            await self._save_shop_items(session, user_id, items)
            new_bal = await self._balance(session, user_id)
            if key == "onekey":
                head = f"{icon} 购买成功！获得 {name}"
            else:
                head = f"{icon} 购买成功！{name} 已生效（时效 {self._shop_hours_text(hours)}）"
            return True, (
                f"{head}\n{desc}\n"
                f"剩余积分：{new_bal} 喵~"
            ), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 钓鱼组队 ====================
    async def _team_for(self, session, user_id: str):
        """返回 用户所在队伍 row 或 None"""
        return (await session.execute(text(
            "SELECT id, captain_id, members, current_size, group_id FROM fishing_teams "
            "WHERE members LIKE :like ESCAPE '\\' LIMIT 1"
        ), {"like": f'%"{user_id}"%'})).first()

    async def _team_bonus_mult(self, session, user_id: str) -> float:
        """用户钓鱼收益加成倍率（队伍加成），默认 1.0"""
        row = await self._team_for(session, user_id)
        if not row:
            return 1.0
        _id, captain, members_json, size, _g = row
        base = self.TEAM_BONUS.get(int(size or 1), 0.0)
        if str(user_id) == str(captain):
            base += self.CAPTAIN_BONUS
        return 1.0 + base

    @filter.command("创建队伍")
    async def team_create(self, event: AstrMessageEvent):
        """/创建队伍 —— 组成钓鱼小队（2-4人共享收益）"""
        user_id = str(event.get_sender_id() or "").strip()
        group_id = str(event.get_group_id() or "").strip() or "PM"
        async def fn(session):
            if await self._team_for(session, user_id):
                raise _BizError("你已在队伍中喵~")
            await session.execute(text(
                "INSERT INTO fishing_teams(captain_id, members, current_size, group_id) "
                "VALUES(:c,:m,1,:g)"), {
                "c": user_id, "m": json.dumps([user_id]), "g": group_id})
            return True, ("🏠 队伍创建成功！\n当前队伍：1/4人\n"
                          "收益加成：0%（需2人以上）\n队友发送 /加入队伍 加入"), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("加入队伍")
    async def team_join(self, event: AstrMessageEvent):
        """/加入队伍 —— 加入本群已有钓鱼小队"""
        user_id = str(event.get_sender_id() or "").strip()
        group_id = str(event.get_group_id() or "").strip() or "PM"
        async def fn(session):
            if await self._team_for(session, user_id):
                raise _BizError("你已在队伍中喵~")
            row = (await session.execute(text(
                "SELECT id, captain_id, current_size FROM fishing_teams "
                "WHERE group_id=:g AND current_size < :m ORDER BY id LIMIT 1"
            ), {"g": group_id, "m": self.TEAM_MAX_SIZE})).first()
            if not row:
                raise _BizError("本群没有可加入的队伍，先 /创建队伍 喵~")
            tid, captain, size = int(row[0]), row[1], int(row[2] or 1)
            cur = (await session.execute(text(
                "SELECT members FROM fishing_teams WHERE id=:i"), {"i": tid})).first()
            members = json.loads(cur[0] or "[]")
            if user_id in members:
                raise _BizError("你已在队伍中喵~")
            members.append(user_id)
            await session.execute(text(
                "UPDATE fishing_teams SET members=:m, current_size=:s WHERE id=:i"),
                {"m": json.dumps(members), "s": size + 1, "i": tid})
            full = (size + 1) >= self.TEAM_MAX_SIZE
            base = int(self.TEAM_BONUS.get(size + 1, 0) * 100)
            cap = base + int(self.CAPTAIN_BONUS * 100)
            tail = "（已满员）" if full else ""
            return True, (f"✅ {user_id} 加入队伍！当前：{size+1}/4人{tail}\n"
                          f"收益加成：成员+{base}%，队长+{cap}%"), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("队伍状态")
    async def team_status(self, event: AstrMessageEvent):
        """/队伍状态 —— 查看小队成员与加成"""
        user_id = str(event.get_sender_id() or "").strip()
        async def fn(session):
            row = await self._team_for(session, user_id)
            if not row:
                raise _BizError("你不在任何队伍中喵~")
            tid, captain, members_json, size, g = row
            members = json.loads(members_json or "[]")
            full = int(size) >= self.TEAM_MAX_SIZE
            base = int(self.TEAM_BONUS.get(int(size), 0) * 100)
            cap = base + int(self.CAPTAIN_BONUS * 100)
            ct = "（队长）" if str(user_id) == str(captain) else ""
            txt = [f"🏠 【队伍状态】队长：{captain}",
                   f"成员：{'、'.join(members)}（{size}/4人）",
                   f"收益加成：队长+{cap}%，其余+{base}%",
                   f"状态：✅ 已满员" if full else f"状态：欢迎加入（{self.TEAM_MAX_SIZE-int(size)}个空位）{ct}"]
            return True, "\n".join(txt), None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("退出队伍")
    async def team_leave(self, event: AstrMessageEvent):
        """/退出队伍 —— 主动离开小队（队长退出即解散）"""
        user_id = str(event.get_sender_id() or "").strip()
        async def fn(session):
            row = await self._team_for(session, user_id)
            if not row:
                raise _BizError("你不在任何队伍中喵~")
            tid, captain, members_json, size, g = row
            members = json.loads(members_json or "[]")
            if str(user_id) == str(captain):
                await session.execute(text("DELETE FROM fishing_teams WHERE id=:i"),
                                       {"i": int(tid)})
                return True, "🏠 队伍已解散（队长离开）", None
            members.remove(user_id)
            n = int(size) - 1
            if n <= 0:
                await session.execute(text("DELETE FROM fishing_teams WHERE id=:i"),
                                       {"i": int(tid)})
                return True, "🏠 队伍已解散", None
            await session.execute(text(
                "UPDATE fishing_teams SET members=:m,current_size=:s WHERE id=:i"),
                {"m": json.dumps(members), "s": n, "i": int(tid)})
            return True, f"✅ 已退出队伍，剩余 {n} 人", None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("解散队伍")
    async def team_disband(self, event: AstrMessageEvent):
        """/解散队伍 —— 队长解散"""
        user_id = str(event.get_sender_id() or "").strip()
        async def fn(session):
            row = (await session.execute(text(
                "SELECT id FROM fishing_teams WHERE captain_id=:c"), {"c": user_id})).first()
            if not row:
                raise _BizError("你不是队长或无队伍喵~")
            await session.execute(text("DELETE FROM fishing_teams WHERE id=:i"),
                                   {"i": int(row[0])})
            return True, "🏠 队伍已解散", None
        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("修鱼竿")
    async def fishing_repair(self, event: AstrMessageEvent):
        """/修鱼竿 [编号] —— 自动修理损坏的鱼竿（不带编号=一键修好全部）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "修鱼竿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        args = self._strip_command(event, "修鱼竿").strip()

        # 解析编号：不带编号 = 一键修理全部损坏鱼竿
        slot = None
        if args:
            try:
                slot = int(args.split()[0])
            except ValueError:
                yield event.plain_result("鱼竿编号得是数字喵~ 不带编号则一键修理全部")
                return

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")

            if slot is not None:
                # 指定编号：修单根
                rod = (await session.execute(text(
                    "SELECT id, status FROM fishing_rods WHERE user_id=:u AND slot=:s"
                ), {"u": user_id, "s": slot})).first()
                if not rod:
                    raise _BizError(f"没有 {slot} 号鱼竿喵~ 发 /鱼竿列表 查看你的鱼竿")
                if rod[1] != "broken":
                    raise _BizError(f"{slot} 号鱼竿没坏，不用修喵~")
                bal = await self._total_balance(session, user_id)
                if bal < self.REPAIR_COST:
                    raise _BizError(
                        f"积分不足喵~ 修鱼竿需要 {self.REPAIR_COST} 积分，你只有 {bal} 积分"
                    )
                await self._add_points(session, user_id, -self.REPAIR_COST, "repair_rod")
                await session.execute(
                    text("UPDATE fishing_rods SET status='idle' WHERE id=:i"), {"i": rod[0]}
                )
                new_bal = await self._balance(session, user_id)
                return True, (
                    f"🔧 {slot} 号鱼竿修好啦！花费 {self.REPAIR_COST} 积分，"
                    f"当前积分：{new_bal} 喵~"
                ), None

            # 一键模式：自动修理全部损坏的鱼竿
            broken = (await session.execute(text(
                "SELECT id, slot FROM fishing_rods WHERE user_id=:u AND status='broken' ORDER BY slot"
            ), {"u": user_id})).all()
            if not broken:
                raise _BizError("没有损坏的鱼竿喵~ 全部完好无损！")
            cost = self.REPAIR_COST * len(broken)
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"积分不足喵~ 修理 {len(broken)} 根鱼竿需要 {cost} 积分"
                    f"（{self.REPAIR_COST}/根），你只有 {bal} 积分"
                )
            for rod in broken:
                await session.execute(
                    text("UPDATE fishing_rods SET status='idle' WHERE id=:i"), {"i": rod[0]}
                )
            await self._add_points(session, user_id, -cost, "repair_rod")
            slots = "、".join(str(r[1]) for r in broken)
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🔧 一键修理完成！{slots} 号鱼竿全部修好啦！\n"
                f"共修理 {len(broken)} 根，花费 {cost} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 一键钓鱼（通行证玩法） ====================
    async def _fishing_set_onekey(self, session, user_id: str):
        """激活一键钓鱼通行证标记（可安全在各闭包内调用，避免局部 text 遮蔽问题）"""
        await self._fishing_ensure_stats(session, user_id)
        await session.execute(text(
            "UPDATE fishing_stats SET onekey_fishing=1 WHERE user_id=:u"), {"u": user_id})

    # ==================== 钓鱼天气系统 ====================
    async def _weather_today(self, session) -> tuple[str, dict]:
        """获取今日天气（无则按概率惰性生成，必须在事务内调用）。返回 (key, 配置)"""
        today = date.today().isoformat()
        row = (await session.execute(text(
            "SELECT weather FROM fishing_weather WHERE date=:d"
        ), {"d": today})).first()
        if not row:
            keys = list(self.WEATHER_CONFIG.keys())
            weights = [self.WEATHER_CONFIG[k]["prob"] for k in keys]
            key = random.choices(keys, weights=weights)[0]
            # 并发生成时后写方忽略，date 主键防重复
            await session.execute(text(
                "INSERT OR IGNORE INTO fishing_weather(date, weather, created_at) "
                "VALUES(:d, :w, :t)"
            ), {"d": today, "w": key, "t": time.time()})
            row = (await session.execute(text(
                "SELECT weather FROM fishing_weather WHERE date=:d"
            ), {"d": today})).first()
        key = str(row[0])
        return key, self.WEATHER_CONFIG.get(key, self.WEATHER_CONFIG["sunny"])

    def _weather_value_mult(self, weather_cfg: dict, bigfish: bool) -> float:
        """渔获价值乘数：大型鱼 ×1.5 ×（满月 ×1.3）"""
        mult = self.FISHING_BIGFISH_MULT if bigfish else 1.0
        return round(mult * float(weather_cfg.get("value_mult", 1.0)), 4)

    async def _fishing_weather_refresh(self):
        """每天 0 点预生成当日天气并通知钓鱼播报群"""
        try:
            async def fn(session):
                wkey, wcfg = await self._weather_today(session)
                return True, "ok", (wkey, wcfg)
            ok, _msg, data = await self._tx(fn)
            if not ok or not data:
                return
            _wkey, wcfg = data
            chain = [Plain(f"🌤️ 今日钓鱼天气更新！{wcfg['name']}：{wcfg['desc']}")]
            for gid in list(self.FISHING_BROADCAST_GROUPS or []):
                try:
                    await self._broadcast_to_group(str(gid), chain)
                except Exception:
                    self.logger.exception("钓鱼天气通知失败 group=%s", gid)
        except Exception:
            self.logger.exception("钓鱼天气刷新任务失败")

    # ==================== 闪光鱼系统 ====================
    def _shiny_split(self, name: str) -> tuple[str, int]:
        """拆分闪光前缀：返回 (基础鱼名, 是否闪光 is_shiny)"""
        prefix = self.FISHING_SHINY_PREFIX
        if name.startswith(prefix):
            return name[len(prefix):], 1
        return name, 0

    def _shiny_price(self, base: str, is_shiny: int) -> int:
        """按基础鱼名+闪光标记计算售价（闪光版 ×3）"""
        price = FISH_POOL.get(base, (0,))[0]
        return int(price * self.FISHING_SHINY_MULT) if is_shiny else price

    async def _fishing_shiny_sync(self, session, user_id: str) -> tuple[int, list[str]]:
        """同步闪光收集数并判定阶段奖励（必须在事务内调用）。

        图鉴中闪光鱼以「✨闪光{鱼名}」前缀记录，与普通版天然区分。
        返回 (闪光种类数, 奖励提示列表)。
        """
        await self._fishing_ensure_stats(session, user_id)
        shiny_names = {str(r[0]) for r in (await session.execute(text(
            "SELECT fish_name FROM fishing_collection WHERE user_id=:u AND fish_name LIKE :p"
        ), {"u": user_id, "p": self.FISHING_SHINY_PREFIX + "%"})).all()}
        shiny_n = len(shiny_names)
        await session.execute(text(
            "UPDATE fishing_stats SET shiny_count=:c WHERE user_id=:u"
        ), {"u": user_id, "c": shiny_n})
        rewards: list[str] = []
        row = (await session.execute(text(
            "SELECT shiny_reward_level FROM fishing_stats WHERE user_id=:u"
        ), {"u": user_id})).first()
        claimed = int(row[0] or 0) if row else 0
        newly = claimed
        for idx, (need, pts, title) in enumerate(self.FISHING_SHINY_REWARDS, start=1):
            if shiny_n >= need and claimed < idx:
                await self._add_points(session, user_id, pts, "shiny_reward")
                rewards.append(f"🌟 收集 {need} 种闪光鱼达成：+{pts} 积分 +「{title}」称号！")
                newly = idx
        if newly != claimed:
            await session.execute(text(
                "UPDATE fishing_stats SET shiny_reward_level=:l WHERE user_id=:u"
            ), {"u": user_id, "l": newly})
        return shiny_n, rewards

    async def _fishing_auto_collect(self, session, user_id: str) -> int:
        """自动收鱼器：把 pending 渔获直接收进鱼篓（含图鉴/称号/统计），返回收取条数"""
        pending = (await session.execute(text(
            "SELECT fish_name, value_mult, COUNT(*) FROM fishing_pending WHERE user_id=:u "
            "GROUP BY fish_name, value_mult"
        ), {"u": user_id})).all()
        if not pending:
            return 0
        total = 0
        for name, mult, cnt in pending:
            name = str(name)
            cnt = int(cnt)
            mult = float(mult or 1)
            total += cnt
            base, is_shiny = self._shiny_split(name)
            await session.execute(text(
                "INSERT INTO fishing_inventory(user_id, fish_name, is_shiny, value_mult, count) "
                "VALUES(:u, :n, :s, :m, :c) "
                "ON CONFLICT(user_id, fish_name, is_shiny) DO UPDATE SET "
                "count=fishing_inventory.count+:c"
            ), {"u": user_id, "n": base, "s": is_shiny, "m": mult, "c": cnt})
            await session.execute(text(
                "INSERT OR IGNORE INTO fishing_collection(user_id, fish_name, first_time) "
                "VALUES(:u, :n, :t)"
            ), {"u": user_id, "n": name, "t": time.time()})
        await session.execute(
            text("DELETE FROM fishing_pending WHERE user_id=:u"), {"u": user_id}
        )
        collected = {str(r[0]) for r in (await session.execute(text(
            "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
        ), {"u": user_id})).all()}
        await self._fishing_grant_titles(session, user_id, collected)
        await session.execute(text(
            "UPDATE fishing_stats SET collection_count=:c WHERE user_id=:u"
        ), {"u": user_id, "c": len(collected)})
        # 闪光收集数同步 + 阶段奖励判定
        await self._fishing_shiny_sync(session, user_id)
        return total

    async def _fishing_onekey_owned(self, session, user_id: str) -> bool:
        """是否已购买一键钓鱼通行证（钓鱼统计标记或商店道具任一即可）"""
        row = (await session.execute(text(
            "SELECT onekey_fishing FROM fishing_stats WHERE user_id=:u"), {"u": user_id})).first()
        if row and int(row[0] or 0) > 0:
            return True
        shop = await self._get_shop_items(session, user_id)
        return int(shop.get("onekey", 0) or 0) > 0

    @filter.command("一键钓鱼")
    async def fishing_onekey(self, event: AstrMessageEvent):
        """/一键钓鱼 —— 通行证功能：自动完成 收鱼→卖鱼→修断竿→重新挂机
        /一键钓鱼 购买 —— 20000 积分购买通行证（永久有效）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "一键钓鱼")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")
        args = self._strip_command(event, "一键钓鱼").strip()

        # ---------- 购买通行证 ----------
        if args in ("购买", "解锁"):
            async def fn_buy(session):
                await self._ensure_user(session, user_id)
                await self._fishing_ensure_stats(session, user_id)
                remaining = await self._enforce_cooldown(session, user_id)
                if remaining > 0:
                    raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
                if await self._fishing_onekey_owned(session, user_id):
                    raise _BizError("你已经有一键钓鱼通行证了喵~ 直接发 /一键钓鱼 使用")
                bal = await self._total_balance(session, user_id)
                if bal < self.ONEKEY_FISH_COST:
                    raise _BizError(
                        f"积分不足喵~ 一键钓鱼通行证需要 {self.ONEKEY_FISH_COST} 积分，"
                        f"你只有 {bal} 积分"
                    )
                await self._add_points(
                    session, user_id, -self.ONEKEY_FISH_COST, "onekey_pass",
                    spent=self.ONEKEY_FISH_COST,
                )
                await self._fishing_set_onekey(session, user_id)
                new_bal = await self._balance(session, user_id)
                return True, (
                    f"⚡ 购买成功！一键钓鱼通行证（{self.ONEKEY_FISH_COST} 积分）已永久激活喵~\n"
                    "以后发送 /一键钓鱼 即可自动完成：收鱼 → 卖鱼 → 修断竿 → 重新挂机\n"
                    f"当前积分：{new_bal}"
                ), None
            ok, msg, _ = await self._tx(fn_buy)
            yield event.plain_result(msg)
            return

        # ---------- 执行一键全流程 ----------
        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            if not await self._fishing_onekey_owned(session, user_id):
                raise _BizError(
                    f"你还没有一键钓鱼通行证喵~ 发送 /一键钓鱼 购买 解锁"
                    f"（{self.ONEKEY_FISH_COST} 积分，永久有效）"
                )
            rod_cnt = (await session.execute(text(
                "SELECT COUNT(*) FROM fishing_rods WHERE user_id=:u"), {"u": user_id})).first()
            if int(rod_cnt[0]) <= 0:
                raise _BizError("你还没有鱼竿，先 /买鱼竿 开钓喵~")

            parts: list[str] = []

            # ① 收鱼：pending → 鱼篓 + 图鉴 + 收集奖励（同 /收鱼）
            pending = (await session.execute(text(
                "SELECT fish_name, value_mult, COUNT(*) FROM fishing_pending WHERE user_id=:u "
                "GROUP BY fish_name, value_mult"
            ), {"u": user_id})).all()
            if pending:
                total = 0
                new_species: list[str] = []
                new_shiny = 0
                for name, mult, cnt in pending:
                    name = str(name)
                    cnt = int(cnt)
                    mult = float(mult or 1)
                    total += cnt
                    base, is_shiny = self._shiny_split(name)
                    price = int(self._shiny_price(base, is_shiny) * mult)
                    rarity = FISH_POOL.get(base, (0, "未知", 0.0))[1]
                    await session.execute(text(
                        "INSERT INTO fishing_inventory(user_id, fish_name, is_shiny, value_mult, count) "
                        "VALUES(:u, :n, :s, :m, :c) "
                        "ON CONFLICT(user_id, fish_name, is_shiny) DO UPDATE SET "
                        "count=fishing_inventory.count+:c"
                    ), {"u": user_id, "n": base, "s": is_shiny, "m": mult, "c": cnt})
                    result = await session.execute(text(
                        "INSERT OR IGNORE INTO fishing_collection(user_id, fish_name, first_time) "
                        "VALUES(:u, :n, :t)"
                    ), {"u": user_id, "n": name, "t": time.time()})
                    if result.rowcount == 1:
                        new_species.append(f"{name}（{rarity}·{price}积分）")
                        if is_shiny:
                            new_shiny += 1
                await session.execute(
                    text("DELETE FROM fishing_pending WHERE user_id=:u"), {"u": user_id}
                )
                collected = {str(r[0]) for r in (await session.execute(text(
                    "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
                ), {"u": user_id})).all()}
                rewards = await self._fishing_grant_titles(session, user_id, collected)
                await session.execute(text(
                    "UPDATE fishing_stats SET collection_count=:c WHERE user_id=:u"
                ), {"u": user_id, "c": len(collected)})
                shiny_n, shiny_rewards = await self._fishing_shiny_sync(session, user_id)
                rewards.extend(shiny_rewards)
                line = f"🐟 收鱼 {total} 条"
                if new_species:
                    line += f"\n✨ 图鉴新收录：{'、'.join(new_species)}"
                if new_shiny:
                    line += f"\n✨ 这是你的第 {shiny_n} 种闪光鱼！"
                for rline in rewards:
                    line += f"\n{rline}"
                parts.append(line)

            # ② 卖鱼：鱼篓全部出售换积分（商店/队伍加成同 /卖鱼）
            inv_rows = (await session.execute(text(
                "SELECT fish_name, is_shiny, value_mult, count FROM fishing_inventory WHERE user_id=:u"
            ), {"u": user_id})).all()
            if inv_rows:
                total = 0
                fish_cnt = 0
                for name, is_shiny, mult, cnt in inv_rows:
                    # 闪光版 ×3，大型鱼/满月乘数随渔获保留
                    price = int(self._shiny_price(str(name), int(is_shiny or 0)) * float(mult or 1))
                    total += price * int(cnt or 0)
                    fish_cnt += int(cnt or 0)
                shop = await self._get_shop_items(session, user_id)
                vip_on = self._shop_active(shop, "vip")
                double_on = self._shop_active(shop, "double")
                if vip_on:
                    total = int(total * 1.1)
                eff_total = total * 2 if double_on else total
                team_mult = await self._team_bonus_mult(session, user_id)
                if team_mult > 1.0:
                    eff_total = int(eff_total * team_mult)
                await self._add_points(
                    session, user_id, eff_total, "sell_fish", earned=eff_total
                )
                await session.execute(text(
                    "UPDATE fishing_stats SET total_income=total_income+:t, "
                    "total_fish_count=total_fish_count+:c WHERE user_id=:u"
                ), {"u": user_id, "t": eff_total, "c": fish_cnt})
                best_name, best_value = max(
                    ((str(n), int(self._shiny_price(str(n), int(s or 0)) * float(m or 1)))
                     for n, s, m, _ in inv_rows),
                    key=lambda item: item[1], default=(None, 0)
                )
                current_best = (await session.execute(text(
                    "SELECT best_fish_value FROM fishing_stats WHERE user_id=:u"
                ), {"u": user_id})).first()
                if best_name and (not current_best or best_value > int(current_best[0] or 0)):
                    await session.execute(text(
                        "UPDATE fishing_stats SET best_fish_name=:n, best_fish_value=:v WHERE user_id=:u"
                    ), {"u": user_id, "n": best_name, "v": best_value})
                await session.execute(
                    text("DELETE FROM fishing_inventory WHERE user_id=:u"), {"u": user_id}
                )
                parts.append(f"💰 卖鱼 {fish_cnt} 条，收入 {eff_total} 积分")
            elif not pending:
                parts.append("🐟 暂时无鱼可收、无鱼可卖")

            # ③ 修竿：自动修理断竿（余额不足时按编号顺序尽量多修）
            broken = (await session.execute(text(
                "SELECT id, slot FROM fishing_rods WHERE user_id=:u AND status='broken' "
                "ORDER BY slot"
            ), {"u": user_id})).all()
            if broken:
                bal = await self._total_balance(session, user_id)
                afford = min(len(broken), max(0, int(bal // self.REPAIR_COST)))
                if afford > 0:
                    cost = afford * self.REPAIR_COST
                    for rod in broken[:afford]:
                        await session.execute(
                            text("UPDATE fishing_rods SET status='idle' WHERE id=:i"),
                            {"i": rod[0]},
                        )
                    await self._add_points(session, user_id, -cost, "repair_rod")
                    slots = "、".join(str(r[1]) for r in broken[:afford])
                    line = f"🔧 修好 {afford} 根断竿（{slots} 号），花费 {cost} 积分"
                    if afford < len(broken):
                        line += (
                            f"\n⚠️ 余额只够修 {afford} 根，"
                            f"剩余 {len(broken) - afford} 根还断着喵~"
                        )
                    parts.append(line)
                else:
                    parts.append(
                        f"⚠️ 有 {len(broken)} 根断竿，但积分不足修理"
                        f"（每根 {self.REPAIR_COST} 积分）"
                    )

            # ④ 挂机：所有待机鱼竿（含刚修好的）重新下水，受鱼饵数量限制
            idle = (await session.execute(text(
                "SELECT id, slot FROM fishing_rods WHERE user_id=:u AND status='idle' "
                "ORDER BY slot"
            ), {"u": user_id})).all()
            fishing_now = (await session.execute(text(
                "SELECT COUNT(*) FROM fishing_rods WHERE user_id=:u AND status='fishing'"
            ), {"u": user_id})).first()
            bait = await self._fishing_bait_count(session, user_id)
            if idle:
                start_n = min(len(idle), bait)
                if start_n > 0:
                    for rod in idle[:start_n]:
                        await session.execute(text(
                            "UPDATE fishing_rods SET status='fishing', platform_id=:p, "
                            "group_id=:g WHERE id=:i"
                        ), {"p": platform_id, "g": group_id, "i": rod[0]})
                    line = (
                        f"🎣 {start_n} 根鱼竿下水挂机，"
                        f"每 {self.CHECK_INTERVAL} 分钟自动判定一次"
                    )
                    if start_n < len(idle):
                        line += (
                            f"\n⚠️ 鱼饵只够 {start_n} 根竿（现有 {bait} 个），"
                            f"剩下的先 /买鱼饵 补给喵~"
                        )
                    parts.append(line)
                else:
                    parts.append(
                        f"🪱 没有鱼饵啦，{len(idle)} 根竿待命中——先 /买鱼饵 再来挂机喵~"
                    )
            elif int(fishing_now[0] or 0) > 0:
                parts.append(f"🎣 {int(fishing_now[0])} 根鱼竿已在水中挂机，无需重复下水")
            else:
                parts.append("🎣 没有可挂机的鱼竿（都断着或没竿了）")

            new_bal = await self._balance(session, user_id)
            return True, (
                "⚡【一键钓鱼】自动作业完成\n" + "\n".join(parts) +
                f"\n💡 当前积分：{new_bal}"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("钓鱼排行")
    async def fishing_rank(self, event: AstrMessageEvent):
        """/钓鱼排行 [收入|数量|大鱼|图鉴] —— 钓鱼排行榜（默认收入榜）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "钓鱼排行")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        subcmd = self._strip_command(event, "钓鱼排行").strip() or "收入"

        async def fn(session):
            medals = ["👑", "🥈", "🥉"] + [f"{i}." for i in range(4, self.FISHING_RANK_SIZE + 1)]
            
            if subcmd == "收入":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), s.total_income "
                    "FROM fishing_stats s LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.total_income > 0 ORDER BY s.total_income DESC LIMIT :n"
                ), {"n": self.FISHING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人有卖鱼收入喵~ 快去 /挂机钓鱼 抢占榜首！")
                lines = [f"📊 【钓鱼排行·收入榜】TOP{len(rows)}"]
                for i, (uid, name, income) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(income)} 积分")
            
            elif subcmd == "数量":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), s.total_fish_count "
                    "FROM fishing_stats s LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.total_fish_count > 0 ORDER BY s.total_fish_count DESC LIMIT :n"
                ), {"n": self.FISHING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人卖过鱼喵~ 快去钓鱼吧！")
                lines = [f"📊 【钓鱼排行·数量榜】TOP{len(rows)}"]
                for i, (uid, name, count) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(count)} 条")
            
            elif subcmd == "大鱼":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), "
                    "s.best_fish_name, s.best_fish_value "
                    "FROM fishing_stats s LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.best_fish_value > 0 ORDER BY s.best_fish_value DESC LIMIT :n"
                ), {"n": self.FISHING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人钓到大鱼喵~ 快去碰碰运气！")
                lines = [f"📊 【钓鱼排行·大鱼榜】TOP{len(rows)}"]
                for i, (uid, name, fish_name, fish_value) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{fish_name}（{int(fish_value)} 积分）")
            
            elif subcmd == "图鉴":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), s.collection_count "
                    "FROM fishing_stats s LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.collection_count > 0 ORDER BY s.collection_count DESC LIMIT :n"
                ), {"n": self.FISHING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人收集过图鉴喵~")
                total_species = len(FISH_POOL)
                lines = [f"📊 【钓鱼排行·图鉴榜】TOP{len(rows)}"]
                for i, (uid, name, count) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(count)}/{total_species} 种")
            
            else:
                raise _BizError("用法：/钓鱼排行 [收入|数量|大鱼|图鉴]")
            
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("钓鱼统计")
    async def fishing_stats_cmd(self, event: AstrMessageEvent):
        """/钓鱼统计 —— 查看今日次数、鱼饵消耗、累计收入、最高价值鱼与称号"""
        ok_gate, msg_gate = await self._check_group_gate(event, "钓鱼统计")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._fishing_ensure_stats(session, user_id)
            row = (await session.execute(text(
                "SELECT total_caught, total_income, total_baits_used, today_count, "
                "lucky_day_expire FROM fishing_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT fish_name FROM fishing_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            # 最高价值鱼：从图鉴里按售价取最高
            best_line = "暂无"
            if collected:
                best = max(collected, key=lambda n: FISH_POOL.get(n, (0,))[0])
                best_line = f"{best}（{FISH_POOL[best][0]}积分）"
            # 称号判定（烛心持有者 / 闲鱼之王 / 至高传说之主 / 万物之主）
            titles: list[str] = []
            if "烛心" in collected:
                titles.append("烛心持有者")
            if "闲鱼" in collected:
                titles.append("闲鱼之王")
            if {"烛心", "闲鱼"} <= collected:
                rewarded = (await session.execute(text(
                    "SELECT 1 FROM point_transactions WHERE user_id=:u "
                    "AND operation='钓鱼至高奖励'"
                ), {"u": user_id})).first()
                if rewarded:
                    titles.append("至高传说之主")
            if len(collected) >= len(FISH_POOL):
                rewarded = (await session.execute(text(
                    "SELECT 1 FROM point_transactions WHERE user_id=:u "
                    "AND operation='钓鱼集齐奖励'"
                ), {"u": user_id})).first()
                if rewarded:
                    titles.append("万物之主")
            lines = [
                "📊 钓鱼统计",
                f"今日钓鱼：{int(row[3] or 0)} 次",
                f"累计钓鱼：{int(row[0] or 0)} 条（消耗鱼饵 {int(row[2] or 0)} 个）",
                f"累计卖鱼收入：{int(row[1] or 0)} 积分",
                f"最高价值鱼：{best_line}",
                f"图鉴进度：{len(collected)}/{len(FISH_POOL)} 种",
            ]
            lucky_expire = float(row[4]) if row[4] else 0.0
            if lucky_expire > time.time():
                remain = int((lucky_expire - time.time()) / 60)
                lines.append(f"🍀 幸运日 buff 剩余 {remain} 分钟（必定上钩）")
            if titles:
                lines.append(f"🎖 称号：{'、'.join(titles)}")
            else:
                lines.append("🎖 称号：暂无（钓到烛心/闲鱼或集齐图鉴可获得）")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _zhuxi_render_image(self, title: str, cards: list):
        """用「烛之游」通用模板渲染播报卡片图，返回 [Image] 消息链或 None。

        cards: [{"name": 标题, "count": 附加计数(可空), "events": [一行条目]}]
        渲染失败返回 None（调用方回退纯文字），绝不抛异常中断播报。
        """
        if not ZHUXI_T2I_TEMPLATE:
            return None
        try:
            import html as _html
            safe_cards = []
            for c in cards:
                safe_cards.append({
                    "name": _html.escape(str(c.get("name", ""))),
                    "count": _html.escape(str(c.get("count", ""))),
                    "events": [_html.escape(str(e)) for e in c.get("events", [])],
                })
            tmpl_data = {
                "title": str(title),
                "date": datetime.now(TZ).strftime("%m月%d日 %H:%M"),
                "cards": safe_cards,
            }
            raw = await _t2i_render_direct(ZHUXI_T2I_TEMPLATE, tmpl_data)
            return [Image.fromBase64(base64.b64encode(raw).decode())]
        except Exception:
            self.logger.exception("烛之游播报渲染失败，回退文字播报")
            return None

    # ============================================================
    #  挖矿系统（v4.24.0）：矿镐挂机 + 矿洞养成 + 连击 + 任务 + 天气 + 组队 + 偷矿
    # ============================================================
    def _mining_roll_event(self) -> str:
        """按 MINING_EVENTS 概率表随机判定一次挂机事件"""
        roll = random.uniform(0, 100)
        cumulative = 0.0
        for name, prob in MINING_EVENTS:
            cumulative += prob
            if roll <= cumulative:
                return name
        return "空洞"

    def _mining_pick_ore(self):
        """按概率加权随机抽一块矿石，返回 (矿名, 售价, 稀有度, 单块概率%)。

        roll 超出各档概率总和时兜底回落普通档（保证挖到必有收获）。
        """
        roll = random.uniform(0, ORE_PROB_TOTAL)
        cumulative = 0.0
        for name, (price, rarity, prob) in ORE_POOL.items():
            cumulative += prob
            if roll <= cumulative:
                return name, price, rarity, prob
        return self._mining_pick_ore_tier("普通")

    def _mining_pick_ore_tier(self, tier: str):
        """从指定稀有度档位随机抽一块矿石（保底必出）"""
        _total, ores = ORE_TABLE.get(tier, ORE_TABLE["普通"])
        name, price = random.choice(ores)
        prob = ORE_POOL.get(name, (0, tier, 0.0))[2]
        return name, price, tier, prob

    def _mining_apply_cave_upgrade(self, picked, bonus: int):
        """在每块矿石判定时应用矿洞加成，返回 (矿石, 是否由矿洞升级)。

        普通矿按 bonus% 概率升级为稀有矿（矿洞等级 + 20 连击加成共用此入口）。
        """
        name, price, rarity, prob = picked
        if rarity == "普通" and bonus > 0 and random.random() < (bonus / 100.0):
            return self._mining_pick_ore_tier("稀有"), True
        return picked, False

    def _mining_combo_effect(self, combo: int):
        """按连击数取效果，返回 (价值加成倍率, 额外积分, 保底档位或 None)

        5连+10%｜10连+20%+10分｜20连+50%+30分+稀有率+10%｜
        50连+100%+100分+必定稀有｜100连+200%+500分+必定传说
        """
        mult, bonus, force_tier = 1.0, 0, None
        for need, m, b in self.MINING_COMBO_TIERS:
            if combo >= need:
                mult = m
                bonus = b
                break
        if combo >= 100:
            force_tier = "传说"
        elif combo >= 50:
            force_tier = "稀有"
        return mult, bonus, force_tier

    async def _mining_ensure_stats(self, session, user_id: str) -> None:
        """确保挖矿统计行存在，并惰性重置过期计数（必须在事务内调用）"""
        today = date.today().isoformat()
        row = (await session.execute(
            text("SELECT today_date FROM mining_stats WHERE user_id=:u"), {"u": user_id}
        )).first()
        if not row:
            await session.execute(
                text("INSERT INTO mining_stats(user_id, today_date, cave_level) VALUES(:u, :d, 1)"),
                {"u": user_id, "d": today},
            )
        elif row[0] != today:
            await session.execute(
                text("UPDATE mining_stats SET today_count=0, today_success=0, today_date=:d "
                     "WHERE user_id=:u"),
                {"u": user_id, "d": today},
            )

    async def _mining_energy_count(self, session, user_id: str) -> int:
        """查询当前体力数量（必须在事务内调用）"""
        row = (await session.execute(
            text("SELECT count FROM mining_energy WHERE user_id=:u"), {"u": user_id}
        )).first()
        return int(row[0] or 0) if row else 0

    async def _mining_grant_titles(
        self, session, user_id: str, collected: set[str]
    ) -> list[str]:
        """图鉴收集奖励判定（必须在事务内调用），返回奖励提示列表。

        称号规则：
        - 挖到烛心 → 烛心矿主；挖到闲鱼 → 闲鱼矿主（纯称号，无积分）
        - 同时拥有烛心和闲鱼 → 额外 1000 积分 + 至高矿主（只发一次）
        - 集齐全部矿石 → 5000 积分 + 万物矿主（只发一次）
        """
        rewards: list[str] = []
        if {"烛心", "闲鱼"} <= collected:
            already = (await session.execute(text(
                "SELECT 1 FROM point_transactions WHERE user_id=:u AND operation='挖矿至高奖励'"
            ), {"u": user_id})).first()
            if not already:
                await self._add_points(
                    session, user_id, self.MINING_BOTH_LEGEND_REWARD, "挖矿至高奖励"
                )
                rewards.append(
                    f"🏆 同时挖到烛心和闲鱼：获得「至高矿主」称号 "
                    f"+{self.MINING_BOTH_LEGEND_REWARD} 积分！"
                )
        if len(collected) >= len(ORE_POOL):
            already = (await session.execute(text(
                "SELECT 1 FROM point_transactions WHERE user_id=:u AND operation='挖矿集齐奖励'"
            ), {"u": user_id})).first()
            if not already:
                await self._add_points(
                    session, user_id, self.MINING_FULL_REWARD, "挖矿集齐奖励"
                )
                rewards.append(
                    f"👑 集齐全部 {len(ORE_POOL)} 种矿石：获得「万物矿主」称号 "
                    f"+{self.MINING_FULL_REWARD} 积分！"
                )
        return rewards

    async def _mining_check(self):
        """定时任务：每 30 分钟判定一次所有挂机中的矿镐。

        enable_mining 关闭时整体跳过（不判定、不播报、不耗体力），恢复开启后继续正常判定。


        每把矿镐消耗 1 个体力后随机判定事件：
        挖到的矿石先进 mining_pending，等玩家 /收矿 进矿仓；
        高价值矿直接全群广播（真实 At 组件）。

        休息时间：北京时间 0:00-7:00 不进行判定（矿工也要休息喵~）
        """
        if not self.feature_flags.get("enable_mining", True):
            return  # _mining_switch_patch
        bj_hour = datetime.now(self._beijing_tz).hour
        if 0 <= bj_hour < 7:
            return

        async def fn(session):
            picks = (await session.execute(text(
                "SELECT p.id, p.user_id, p.slot, p.platform_id, p.group_id, "
                "COALESCE(NULLIF(u.user_name, ''), p.user_id) "
                "FROM mining_picks p LEFT JOIN users u ON u.user_id = p.user_id "
                "WHERE p.status='mining'"
            ))).all()
            if not picks:
                return False, "没有挂机中的矿镐", None
            broadcasts: list[tuple[str, str, list]] = []   # (platform_id, group_id, 消息链)
            notices: list[tuple[str, str, str]] = []       # (platform_id, group_id, 事件播报文本)
            weather_key, weather_cfg = await self._mining_weather_today(session)
            for pick in picks:
                pid, uid, slot, platform_id, group_id, user_name = pick
                group_id = str(group_id or "")

                def notify(text_line: str):
                    """本群事件播报（不艾特，只说谁遇到了什么事）"""
                    if group_id:
                        notices.append((platform_id, group_id, f"⛏️ {user_name} {text_line}"))

                await self._mining_ensure_stats(session, uid)
                st = (await session.execute(text(
                    "SELECT lucky_day_expire, storm_expire, cave_level "
                    "FROM mining_stats WHERE user_id=:u"
                ), {"u": uid})).first()
                # 暴风雪暂停：该玩家所有矿镐停工，跳过本次判定
                if st and st[1] and float(st[1]) > time.time():
                    continue
                lucky_active = bool(st and st[0] and float(st[0]) > time.time())
                cave_level = int(st[2] or 1) if st else 1
                cave_rare_bonus = self.CAVE_RARE_BONUS.get(cave_level, 0)
                # 判定前消耗 1 个体力，没体力自动收工
                energy = await self._mining_energy_count(session, uid)
                if energy <= 0:
                    await session.execute(
                        text("UPDATE mining_picks SET status='idle' WHERE id=:i"), {"i": pid}
                    )
                    notify("的体力用完了，矿镐自动收工休息啦~")
                    continue
                await session.execute(
                    text("UPDATE mining_energy SET count=count-1 WHERE user_id=:u"), {"u": uid}
                )
                # 矿洞减耗效果：按减耗百分比有几率回补 1 体力
                red_pct = self.CAVE_ENERGY_REDUCTION.get(cave_level, 0)
                if red_pct > 0 and random.random() < (min(red_pct, 95) / 100.0):
                    await session.execute(
                        text("UPDATE mining_energy SET count=count+1 WHERE user_id=:u"),
                        {"u": uid},
                    )
                # 本次判定统计（每次判定消耗 1 体力）
                await session.execute(text(
                    "UPDATE mining_stats SET total_energy_used=total_energy_used+1, "
                    "today_count=today_count+1 WHERE user_id=:u"
                ), {"u": uid})
                event = self._mining_roll_event()
                # 幸运日 buff：有效期内空洞视为挖到
                if event == "空洞" and lucky_active:
                    event = "正常挖到"
                    notify("幸运日加持！空洞里居然也挖出了矿石！")
                multi_map = {"正常挖到": 1, "双倍矿石": 2, "矿脉爆发": 1}
                # 暴风雪天气：挖矿类事件 30% 概率化为空洞（挖矿成功率-30%）
                if weather_cfg.get("fail_pct") and event in multi_map and \
                        random.random() < weather_cfg["fail_pct"] / 100.0:
                    event = "空洞"
                    notify("暴风雪太猛了，矿道被迫封闭，白干一场…")
                if event in multi_map:
                    # 矿脉爆发：额外消耗 1 体力
                    if event == "矿脉爆发":
                        if (await self._mining_energy_count(session, uid)) > 0:
                            await session.execute(
                                text("UPDATE mining_energy SET count=count-1 WHERE user_id=:u"),
                                {"u": uid},
                            )
                            await session.execute(text(
                                "UPDATE mining_stats SET total_energy_used=total_energy_used+1 "
                                "WHERE user_id=:u"
                            ), {"u": uid})
                            notify("触发矿脉爆发！额外消耗 1 体力，多挖出一块矿石！")
                        else:
                            notify("触发矿脉爆发！可惜没有多余体力，只能干瞪眼…")
                    caught = multi_map[event]
                    # 连击推进：连续成功挖到，空洞/断镐/塌方中断
                    combo_row = (await session.execute(text(
                        "SELECT current_combo FROM mining_stats WHERE user_id=:u"
                    ), {"u": uid})).first()
                    new_combo = int(combo_row[0] or 0) + 1
                    await session.execute(text(
                        "UPDATE mining_stats SET current_combo=:c, "
                        "max_combo=MAX(max_combo, :c) WHERE user_id=:u"
                    ), {"c": new_combo, "u": uid})
                    combo_mult, combo_bonus, force_tier = self._mining_combo_effect(new_combo)
                    if combo_bonus > 0:
                        await self._add_points(session, uid, combo_bonus, "挖矿连击奖励")
                    # 20 连击：本次稀有概率+10%
                    catch_bonus = cave_rare_bonus + (10 if new_combo >= 20 else 0)
                    ore_texts: list[str] = []
                    for _ in range(caught):
                        if force_tier:
                            picked = self._mining_pick_ore_tier(force_tier)
                        else:
                            picked = self._mining_pick_ore()
                        picked, cave_upgraded = self._mining_apply_cave_upgrade(
                            picked, catch_bonus)
                        name, price, rarity, prob = picked
                        upgrade_tag = "·矿洞加成↑" if cave_upgraded else ""
                        # 天气加成：雨天/寒冷/雾天把普通矿升级为稀有/珍稀/传说
                        wtier = weather_cfg.get("tier")
                        if wtier and rarity == "普通" and \
                                random.random() < weather_cfg["pct"] / 100.0:
                            name, price, rarity, prob = self._mining_pick_ore_tier(wtier)
                            upgrade_tag = f"{upgrade_tag}·天气加成↑" if upgrade_tag else "·天气加成↑"
                        # 天气大矿/满月价值乘数（随矿石保留到卖出）× 连击价值加成
                        bigore = bool(weather_cfg.get("bigore")) and \
                            random.random() < weather_cfg["bigore"] / 100.0
                        value_mult = round(
                            self._mining_weather_value_mult(weather_cfg, bigore) * combo_mult, 4)
                        if bigore:
                            upgrade_tag = f"{upgrade_tag}·🪨大矿" if upgrade_tag else "·🪨大矿"
                        if combo_mult > 1.0:
                            upgrade_tag = f"{upgrade_tag}·🔥{new_combo}连击"
                        ore_texts.append(f"{name}（{price}积分{upgrade_tag}）")
                        await session.execute(text(
                            "INSERT INTO mining_pending(user_id, ore_name, value_mult, catch_time) "
                            "VALUES(:u, :n, :m, :t)"
                        ), {"u": uid, "n": name, "m": value_mult, "t": time.time()})
                        await session.execute(text(
                            "UPDATE mining_stats SET total_caught=total_caught+1 WHERE user_id=:u"
                        ), {"u": uid})
                        # 更新每日挖矿任务
                        await self._mining_task_tick(session, uid, 1, name, price)
                        # 全群广播：传说级及以上（售价 > 1000 也触发）
                        if rarity in self.MINING_BROADCAST_RARITIES or price > self.MINING_BROADCAST_PRICE:
                            chain = [At(qq=str(uid))]
                            if rarity == "至高传说":
                                chain.append(Plain(
                                    f" 🌟🌟🌟 挖到了传说中的 {name}（价值{price}积分！"
                                    f"概率{f'{prob:.6f}'.rstrip('0').rstrip('.')}%！！！）\n"
                                    f"此乃万中无一之奇迹！"
                                ))
                            else:
                                chain.append(Plain(
                                    f" 🎉🎉🎉 挖到了 {name}（价值{price}积分！"
                                    f"概率{f'{prob:.6f}'.rstrip('0').rstrip('.')}%！！！）"
                                ))
                            if group_id:
                                broadcasts.append((platform_id, group_id, chain))
                    notify(f"挖到了 {'、'.join(ore_texts)}，进矿仓啦！")
                    await self._mining_task_streak(session, uid, broke=False)
                elif event == "空洞":
                    await session.execute(
                        text("UPDATE mining_stats SET current_combo=0 WHERE user_id=:u"),
                        {"u": uid},
                    )
                    notify("挖了半天只有一个空洞，体力白费…")
                    await self._mining_task_streak(session, uid, broke=True)
                elif event == "神秘宝箱":
                    amount = random.randint(self.MINING_BOX_MIN, self.MINING_BOX_MAX)
                    await self._add_points(session, uid, amount, "挖矿宝箱")
                    notify(f"挖到一个神秘宝箱，开出 {amount} 积分！")
                elif event == "矿镐断裂":
                    await session.execute(
                        text("UPDATE mining_picks SET status='broken' WHERE id=:i"), {"i": pid}
                    )
                    await session.execute(
                        text("UPDATE mining_stats SET current_combo=0 WHERE user_id=:u"),
                        {"u": uid},
                    )
                    notify("咔嚓！矿镐断了，记得 /修矿镐 哦~")
                    await self._mining_task_streak(session, uid, broke=True)
                elif event == "塌方":
                    # 矿镐永久消失：整行删除
                    await session.execute(
                        text("DELETE FROM mining_picks WHERE id=:i"), {"i": pid}
                    )
                    await session.execute(
                        text("UPDATE mining_stats SET current_combo=0 WHERE user_id=:u"),
                        {"u": uid},
                    )
                    notify(f"矿道塌方！{int(slot)} 号矿镐被永远埋在了地下…默哀")
                    await self._mining_task_streak(session, uid, broke=True)
                elif event == "暴风雪":
                    expire = time.time() + self.MINING_STORM_HOURS * 3600
                    await session.execute(text(
                        "UPDATE mining_stats SET storm_expire=:e WHERE user_id=:u"
                    ), {"e": expire, "u": uid})
                    notify(f"暴风雪来袭！所有矿镐暂停 {self.MINING_STORM_HOURS} 小时…")
                elif event == "幸运日":
                    expire = time.time() + self.MINING_LUCKY_HOURS * 3600
                    await session.execute(text(
                        "UPDATE mining_stats SET lucky_day=lucky_day+1, lucky_day_expire=:e "
                        "WHERE user_id=:u"
                    ), {"u": uid, "e": expire})
                    notify(f"时来运转！获得 {self.MINING_LUCKY_HOURS} 小时幸运buff，"
                           "期间空洞视为挖到、卖矿收入翻倍！")
            return True, "判定完成", (broadcasts, notices)

        ok, msg, data = await self._tx(fn)
        if not ok or not data:
            self.logger.info(f"挖矿判定未执行：{msg}")
            return
        broadcasts, notices = data
        self.logger.info(f"挖矿判定完成：播报 {len(notices)} 条事件，{len(broadcasts)} 条高价广播")
        # 事务外发送全群广播，避免阻塞数据库
        for platform_id, group_id, chain in broadcasts:
            await self._send_with_fallback(platform_id, group_id, chain, "挖矿高价广播")
        # 事件播报：按群聚合所有人的播报，合并为一条文字消息
        # 只按群号聚合（同群跨平台实例的播报合并为一条消息，避免拆成多张图）
        per_group: dict[str, dict] = {}
        if self.FISHING_BROADCAST_GROUPS:
            # 配置了播报群：所有源群的事件合并成一张图统一推送。
            # 播报群本身就是"全服实况频道"，若按源群逐张推送，
            # 玩家跨多个群挂机时播报群一个周期会收到多张图。
            per_group["__broadcast__"] = {
                "platform": "", "lines": [str(t[2]) for t in notices]}
        else:
            # 未配置播报群：只按群号聚合（同群跨平台实例合并为一条消息），
            # 且只发目标群（cross_group_fallback=False，别群的图不漏进来）
            for platform_id, group_id, text_line in notices:
                g = str(group_id)
                if g not in per_group:
                    per_group[g] = {"platform": str(platform_id), "lines": []}
                per_group[g]["lines"].append(str(text_line))
        for group_id, info in per_group.items():
            platform_id = info["platform"]
            lines = info["lines"]
            img_chain = None
            if ZHUXI_T2I_TEMPLATE:
                members_d: dict[str, list] = {}
                m_order: list[str] = []
                for line in lines:
                    parts = line.split(" ", 2)
                    who = parts[1] if len(parts) >= 2 and parts[0] == "⛏️" else "未知"
                    ev = parts[2] if len(parts) >= 3 else line
                    if who not in members_d:
                        members_d[who] = []
                        m_order.append(who)
                    members_d[who].append(ev)
                img_chain = await self._zhuxi_render_image(
                    "挖矿实况",
                    [{"name": w, "count": f"{len(members_d[w])} 条", "events": members_d[w]}
                     for w in m_order],
                )
            if img_chain:
                await self._send_with_fallback(platform_id, group_id, img_chain,
                                               "挖矿播报图", cross_group_fallback=False)
            else:
                await self._send_with_fallback(
                    platform_id, group_id, [Plain("\n".join(lines))], "挖矿播报",
                    cross_group_fallback=False)

    async def _mining_daily_reset(self):
        """定时任务：每天凌晨 0 点重置今日统计（today_count / today_date）"""
        async def fn(session):
            await session.execute(text(
                "UPDATE mining_stats SET today_count=0, today_success=0, today_date=:d"
            ), {"d": date.today().isoformat()})
            return True, "今日挖矿统计已重置", None

        await self._tx(fn)

    # ==================== 挖矿天气 ====================
    async def _mining_weather_today(self, session) -> tuple[str, dict]:
        """获取今日矿洞天气（无则按概率惰性生成，必须在事务内调用）。返回 (key, 配置)"""
        today = date.today().isoformat()
        row = (await session.execute(text(
            "SELECT weather FROM mining_weather WHERE date=:d"
        ), {"d": today})).first()
        if not row:
            keys = list(self.MINING_WEATHER_CONFIG.keys())
            weights = [self.MINING_WEATHER_CONFIG[k]["prob"] for k in keys]
            key = random.choices(keys, weights=weights)[0]
            # 并发生成时后写方忽略，date 主键防重复
            await session.execute(text(
                "INSERT OR IGNORE INTO mining_weather(date, weather, created_at) "
                "VALUES(:d, :w, :t)"
            ), {"d": today, "w": key, "t": time.time()})
            row = (await session.execute(text(
                "SELECT weather FROM mining_weather WHERE date=:d"
            ), {"d": today})).first()
        key = str(row[0])
        return key, self.MINING_WEATHER_CONFIG.get(key, self.MINING_WEATHER_CONFIG["sunny"])

    def _mining_weather_value_mult(self, weather_cfg: dict, bigore: bool) -> float:
        """矿石价值乘数：大型矿 ×1.5 ×（满月 ×1.3）"""
        mult = self.FISHING_BIGFISH_MULT if bigore else 1.0
        return round(mult * float(weather_cfg.get("value_mult", 1.0)), 4)

    async def _mining_weather_refresh(self):
        """每天 0 点预生成当日矿洞天气"""
        try:
            async def fn(session):
                wkey, wcfg = await self._mining_weather_today(session)
                return True, "ok", (wkey, wcfg)
            ok, _msg, data = await self._tx(fn)
            if ok and data:
                self.logger.info(f"今日矿洞天气已生成：{data[1]['name']}")
        except Exception:
            self.logger.exception("挖矿天气刷新任务失败")

    @filter.command("买矿镐")
    async def mining_buy_pick(self, event: AstrMessageEvent):
        """/买矿镐 —— 花费 200 积分购买一把矿镐（最多 5 把）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买矿镐")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._ensure_user(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cnt = (await session.execute(text(
                "SELECT COUNT(*) FROM mining_picks WHERE user_id=:u"
            ), {"u": user_id})).first()
            if int(cnt[0]) >= self.MINING_MAX_PICKS:
                raise _BizError(f"矿镐已经满 {self.MINING_MAX_PICKS} 把啦，不能再买了喵~")
            slots = {int(r[0]) for r in (await session.execute(text(
                "SELECT slot FROM mining_picks WHERE user_id=:u"
            ), {"u": user_id})).all()}
            slot = next(i for i in range(1, self.MINING_MAX_PICKS + 1) if i not in slots)
            bal = await self._total_balance(session, user_id)
            if bal < self.MINING_PICK_COST:
                raise _BizError(
                    f"积分不足喵~ 买矿镐需要 {self.MINING_PICK_COST} 积分，你只有 {bal} 积分"
                )
            await self._add_points(session, user_id, -self.MINING_PICK_COST, "buy_pick")
            await session.execute(text(
                "INSERT INTO mining_picks(user_id, slot, status, created_at) "
                "VALUES(:u, :s, 'idle', :t)"
            ), {"u": user_id, "s": slot, "t": time.time()})
            owned = int(cnt[0]) + 1
            new_bal = await self._balance(session, user_id)
            return True, (
                f"⛏️ 矿镐购买成功！获得 {slot} 号矿镐，当前拥有 {owned}/{self.MINING_MAX_PICKS} 把，"
                f"花费 {self.MINING_PICK_COST} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("买体力")
    async def mining_buy_energy(self, event: AstrMessageEvent):
        """/买体力 [数量] —— 10 积分/个购买体力，不填数量默认买 1 个"""
        ok_gate, msg_gate = await self._check_group_gate(event, "买体力")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        count = 1
        args = self._strip_command(event, "买体力")
        if args:
            try:
                count = int(args.split()[0])
                if count <= 0:
                    raise ValueError
            except ValueError:
                yield event.plain_result("体力数量得是正整数喵~")
                return

        async def fn(session):
            await self._ensure_user(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            cost = count * self.MINING_ENERGY_COST
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"积分不足喵~ 买 {count} 个体力需要 {cost} 积分，你只有 {bal} 积分"
                )
            await self._add_points(session, user_id, -cost, "buy_energy")
            await session.execute(text(
                "INSERT INTO mining_energy(user_id, count) VALUES(:u, :c) "
                "ON CONFLICT(user_id) DO UPDATE SET count=mining_energy.count+:c"
            ), {"u": user_id, "c": count})
            energy = await self._mining_energy_count(session, user_id)
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🔋 成功购买 {count} 个体力，共消耗 {cost} 积分，"
                f"现有体力 {energy} 个，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("挂机挖矿")
    async def mining_start(self, event: AstrMessageEvent):
        """/挂机挖矿 [编号] —— 让矿镐开始挂机，不填编号则全部待机矿镐一起开工"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挂机挖矿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")
        args = self._strip_command(event, "挂机挖矿")

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            picks = (await session.execute(text(
                "SELECT id, slot, status FROM mining_picks WHERE user_id=:u ORDER BY slot"
            ), {"u": user_id})).all()
            if not picks:
                raise _BizError("你还没有矿镐，先 /买矿镐 喵~")
            # 选出目标矿镐
            if args:
                try:
                    slot = int(args.split()[0])
                except ValueError:
                    raise _BizError("矿镐编号得是数字喵~")
                matched = [p for p in picks if int(p[1]) == slot]
                if not matched:
                    raise _BizError(f"没有 {slot} 号矿镐喵~ 发 /矿镐列表 查看你的矿镐")
                pick = matched[0]
                if pick[2] == "mining":
                    raise _BizError(f"{slot} 号矿镐已经在挂机啦喵~")
                if pick[2] == "broken":
                    raise _BizError(f"{slot} 号矿镐断了，先 /修矿镐 {slot} 喵~")
                targets = [pick]
            else:
                targets = [p for p in picks if p[2] == "idle"]
                if not targets:
                    raise _BizError("没有待机的矿镐喵~（挂机中或损坏的镐不能用）")
            energy = await self._mining_energy_count(session, user_id)
            if energy <= 0:
                raise _BizError("没有体力啦，先 /买体力 再来挖矿喵~")
            weather_key, weather_cfg = await self._mining_weather_today(session)
            # 体力不足以全覆盖时只启动部分矿镐（每次判定每镐消耗 1 个体力）
            start_n = min(len(targets), energy)
            for pick in targets[:start_n]:
                await session.execute(text(
                    "UPDATE mining_picks SET status='mining', platform_id=:p, group_id=:g "
                    "WHERE id=:i"
                ), {"p": platform_id, "g": group_id, "i": pick[0]})
            msg = (
                f"⛏️ 今日矿洞天气{weather_cfg['name']}！{weather_cfg['desc']}！\n"
                f"{start_n} 把矿镐已开工！每 {self.MINING_CHECK_INTERVAL} 分钟来收一次，"
                f"每次消耗 1 个体力，挖到的矿用 /收矿 收取喵~"
            )
            if start_n < len(targets):
                msg += f"\n（体力只够 {start_n} 把镐，剩下的先补体力喵~）"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("收矿")
    async def mining_collect(self, event: AstrMessageEvent):
        """/收矿 —— 把 pending 里的矿石收进矿仓，并记录图鉴/判定收集奖励"""
        ok_gate, msg_gate = await self._check_group_gate(event, "收矿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            pending = (await session.execute(text(
                "SELECT ore_name, value_mult, COUNT(*) FROM mining_pending WHERE user_id=:u "
                "GROUP BY ore_name, value_mult"
            ), {"u": user_id})).all()
            if not pending:
                raise _BizError("还没挖到矿喵~ 挂机中的矿镐每 30 分钟判定一次，等等再来")
            total = 0
            new_species: list[str] = []
            details: list[str] = []
            for name, mult, cnt in pending:
                name = str(name)
                cnt = int(cnt)
                mult = float(mult or 1)
                total += cnt
                price = int(ORE_POOL.get(name, (0,))[0] * mult)
                rarity = ORE_POOL.get(name, (0, "未知", 0.0))[1]
                # 并入矿仓（同矿同名合并，价值乘数取首见值）
                await session.execute(text(
                    "INSERT INTO mining_inventory(user_id, ore_name, value_mult, count) "
                    "VALUES(:u, :n, :m, :c) "
                    "ON CONFLICT(user_id, ore_name) DO UPDATE SET "
                    "count=mining_inventory.count+:c"
                ), {"u": user_id, "n": name, "m": mult, "c": cnt})
                # 记录图鉴（挖到过即收集，卖矿不影响进度）
                result = await session.execute(text(
                    "INSERT OR IGNORE INTO mining_collection(user_id, ore_name, first_time) "
                    "VALUES(:u, :n, :t)"
                ), {"u": user_id, "n": name, "t": time.time()})
                if result.rowcount == 1:
                    new_species.append(f"{name}（{rarity}·{price}积分）")
                details.append(f"{name}×{cnt}")
            await session.execute(
                text("DELETE FROM mining_pending WHERE user_id=:u"), {"u": user_id}
            )
            # 图鉴收集奖励判定（烛心/闲鱼/集齐）
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT ore_name FROM mining_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            rewards = await self._mining_grant_titles(session, user_id, collected)
            await session.execute(text(
                "UPDATE mining_stats SET collection_count=:c WHERE user_id=:u"
            ), {"u": user_id, "c": len(collected)})
            msg = f"📦 收矿成功！本次进仓 {total} 块：{'、'.join(details)}喵~"
            if new_species:
                msg += f"\n✨ 图鉴新收录：{'、'.join(new_species)}"
            for line in rewards:
                msg += f"\n{line}"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("矿仓")
    async def mining_barn(self, event: AstrMessageEvent):
        """/矿仓 —— 查看矿仓里所有矿石（按价值排序）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "矿仓")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            rows = (await session.execute(text(
                "SELECT ore_name, value_mult, count FROM mining_inventory WHERE user_id=:u "
                "ORDER BY count DESC"
            ), {"u": user_id})).all()
            if not rows:
                raise _BizError("矿仓空空如也喵~ 发 /挂机挖矿 开工吧")
            total_cnt = 0
            total_value = 0
            lines = ["📦 【矿仓】"]
            for name, mult, cnt in rows:
                name = str(name)
                cnt = int(cnt or 0)
                mult = float(mult or 1)
                base_price = ORE_POOL.get(name, (0,))[0]
                price = int(base_price * mult)
                total_cnt += cnt
                total_value += price * cnt
                rarity = ORE_POOL.get(name, ("", "未知"))[1]
                mark = "🪨" if mult >= self.FISHING_BIGFISH_MULT else ""
                lines.append(f"• {mark}{name}（{rarity}）×{cnt}　{price}积分/块")
            lines.append("─────────────")
            lines.append(f"共 {len(rows)} 种 {total_cnt} 块，总价值约 {total_value} 积分")
            lines.append("发 /卖矿 一键卖出")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("卖矿")
    async def mining_sell(self, event: AstrMessageEvent):
        """/卖矿 —— 一键卖出矿仓里所有矿石，按矿石售价换算积分"""
        ok_gate, msg_gate = await self._check_group_gate(event, "卖矿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            rows = (await session.execute(text(
                "SELECT ore_name, value_mult, count FROM mining_inventory WHERE user_id=:u"
            ), {"u": user_id})).all()
            if not rows:
                raise _BizError("矿仓里没有矿石可以卖喵~ 先 /挂机挖矿 再来")
            total = 0
            ore_cnt = 0
            details: list[str] = []
            best_name, best_value = None, 0
            for name, mult, cnt in rows:
                name = str(name)
                cnt = int(cnt or 0)
                mult = float(mult or 1)
                base_price = ORE_POOL.get(name, (0,))[0]
                price = int(base_price * mult)
                total += price * cnt
                ore_cnt += cnt
                details.append(f"{name}×{cnt}")
                if base_price > best_value:
                    best_name, best_value = name, base_price
            # 幸运日 buff：24 小时内卖矿收入翻倍
            st = (await session.execute(text(
                "SELECT lucky_day_expire FROM mining_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            lucky_on = bool(st and st[0] and float(st[0]) > time.time())
            if lucky_on:
                total = total * 2
            # 组队收益加成
            team_mult = await self._mteam_bonus_mult(session, user_id)
            if team_mult > 1.0:
                total = int(total * team_mult)
            # 修仙加成：境界（每大境界+5%）+ 宗门（每级+1.5%）
            x_realm_mult, x_sect_mult = await self._xiuxian_income_bonus(session, user_id)
            if x_realm_mult > 1.0:
                total = int(total * x_realm_mult)
            if x_sect_mult > 1.0:
                total = int(total * x_sect_mult)
            await self._add_points(session, user_id, total, "sell_ore", earned=total)
            await session.execute(text(
                "UPDATE mining_stats SET total_income=total_income+:t, "
                "total_ore_count=total_ore_count+:c WHERE user_id=:u"
            ), {"u": user_id, "t": total, "c": ore_cnt})
            # 维护最高价值矿
            current_best = (await session.execute(text(
                "SELECT best_ore_value FROM mining_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            if best_name and (not current_best or best_value > int(current_best[0] or 0)):
                await session.execute(text(
                    "UPDATE mining_stats SET best_ore_name=:n, best_ore_value=:v WHERE user_id=:u"
                ), {"u": user_id, "n": best_name, "v": best_value})
            await session.execute(
                text("DELETE FROM mining_inventory WHERE user_id=:u"), {"u": user_id}
            )
            new_bal = await self._balance(session, user_id)
            msg = (f"💰 卖出所有矿石，共 {len(rows)} 种，获得 {total} 积分"
                   f"{'（🔥幸运日翻倍）' if lucky_on else ''}\n"
                   f"明细：{'、'.join(details)}\n"
                   f"当前积分：{new_bal} 喵~")
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("矿图鉴")
    async def mining_collection_cmd(self, event: AstrMessageEvent):
        """/矿图鉴 —— 查看已收集矿石图鉴进度（按稀有度分组）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "矿图鉴")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT ore_name FROM mining_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            lines = [f"📔 【矿石图鉴】{len(collected)}/{len(ORE_POOL)} 种"]
            for rarity, (_tp, ores) in ORE_TABLE.items():
                names = list(dict.fromkeys(n for n, _p in ores))
                owned = [n for n in names if n in collected]
                lines.append(f"• {rarity}：{len(owned)}/{len(names)}")
            if not collected:
                lines.append("还没有收录任何矿石，发 /挂机挖矿 开挖吧喵~")
            else:
                lines.append("─────────────")
                lines.append(f"已收录：{'、'.join(sorted(collected))}")
            # 收集称号
            titles: list[str] = []
            if "烛心" in collected:
                titles.append("烛心矿主")
            if "闲鱼" in collected:
                titles.append("闲鱼矿主")
            if {"烛心", "闲鱼"} <= collected:
                titles.append("至高矿主")
            if len(collected) >= len(ORE_POOL):
                titles.append("万物矿主")
            if titles:
                lines.append(f"🎖 称号：{'、'.join(titles)}")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("矿镐列表")
    async def mining_pick_list(self, event: AstrMessageEvent):
        """/矿镐列表 —— 查看每把矿镐状态与体力余量"""
        ok_gate, msg_gate = await self._check_group_gate(event, "矿镐列表")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        status_text = {"idle": "待机", "mining": "挂机中", "broken": "已损坏"}

        async def fn(session):
            picks = (await session.execute(text(
                "SELECT slot, status FROM mining_picks WHERE user_id=:u ORDER BY slot"
            ), {"u": user_id})).all()
            if not picks:
                raise _BizError("你还没有矿镐，先 /买矿镐 喵~")
            energy = await self._mining_energy_count(session, user_id)
            lines = [f"⛏️ 矿镐列表（体力余量：{energy} 个）"]
            for slot, status in picks:
                lines.append(f"{int(slot)} 号镐：{status_text.get(str(status), str(status))}")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("修矿镐")
    async def mining_repair(self, event: AstrMessageEvent):
        """/修矿镐 [编号] —— 修理损坏的矿镐（不带编号=一键修好全部）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "修矿镐")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        args = self._strip_command(event, "修矿镐").strip()

        slot = None
        if args:
            try:
                slot = int(args.split()[0])
            except ValueError:
                yield event.plain_result("矿镐编号得是数字喵~ 不带编号则一键修理全部")
                return

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")

            if slot is not None:
                pick = (await session.execute(text(
                    "SELECT id, status FROM mining_picks WHERE user_id=:u AND slot=:s"
                ), {"u": user_id, "s": slot})).first()
                if not pick:
                    raise _BizError(f"没有 {slot} 号矿镐喵~ 发 /矿镐列表 查看你的矿镐")
                if pick[1] != "broken":
                    raise _BizError(f"{slot} 号矿镐没坏，不用修喵~")
                bal = await self._total_balance(session, user_id)
                if bal < self.MINING_REPAIR_COST:
                    raise _BizError(
                        f"积分不足喵~ 修矿镐需要 {self.MINING_REPAIR_COST} 积分，"
                        f"你只有 {bal} 积分"
                    )
                await self._add_points(
                    session, user_id, -self.MINING_REPAIR_COST, "repair_pick")
                await session.execute(
                    text("UPDATE mining_picks SET status='idle' WHERE id=:i"), {"i": pick[0]}
                )
                new_bal = await self._balance(session, user_id)
                return True, (
                    f"🔧 {slot} 号矿镐修好啦！花费 {self.MINING_REPAIR_COST} 积分，"
                    f"当前积分：{new_bal} 喵~"
                ), None

            broken = (await session.execute(text(
                "SELECT id, slot FROM mining_picks WHERE user_id=:u AND status='broken' "
                "ORDER BY slot"
            ), {"u": user_id})).all()
            if not broken:
                raise _BizError("没有损坏的矿镐喵~ 全部完好无损！")
            cost = self.MINING_REPAIR_COST * len(broken)
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"积分不足喵~ 修理 {len(broken)} 把矿镐需要 {cost} 积分"
                    f"（{self.MINING_REPAIR_COST}/把），你只有 {bal} 积分"
                )
            for pick in broken:
                await session.execute(
                    text("UPDATE mining_picks SET status='idle' WHERE id=:i"), {"i": pick[0]}
                )
            await self._add_points(session, user_id, -cost, "repair_pick")
            slots = "、".join(str(p[1]) for p in broken)
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🔧 一键修理完成！{slots} 号矿镐全部修好啦！\n"
                f"共修理 {len(broken)} 把，花费 {cost} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 矿洞养成 ====================
    @filter.command("矿洞")
    async def cave_status(self, event: AstrMessageEvent):
        """/矿洞 —— 查看自己的矿洞等级与加成效果"""
        ok_gate, msg_gate = await self._check_group_gate(event, "矿洞")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            row = (await session.execute(text(
                "SELECT cave_level FROM mining_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            level = int(row[0] or 1) if row else 1
            energy_red = self.CAVE_ENERGY_REDUCTION.get(level, 0)
            rare_bonus = self.CAVE_RARE_BONUS.get(level, 0)
            max_hours = self.CAVE_BASE_HOURS + self.CAVE_EXTRA_HOURS.get(level, 0)
            lines = [
                "🕳️ 【矿洞状态】",
                f"等级：{level}级",
                f"体力消耗：-{energy_red}%",
                f"稀有矿转化：普通矿有 {rare_bonus}% 概率升级为稀有矿",
                f"挂机时间上限：{max_hours}小时",
            ]
            if level < self.CAVE_MAX_LEVEL:
                nxt = level + 1
                cost = self.CAVE_UPGRADE_COST.get(nxt, 0)
                lines.append(f"升级到{nxt}级需要：{cost}积分")
                lines.append("发送 /升级矿洞 升级！")
            else:
                lines.append("✅ 已满级，矿洞灯火通明！")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("升级矿洞")
    async def cave_upgrade(self, event: AstrMessageEvent):
        """/升级矿洞 —— 花费积分永久提升挖矿收益"""
        ok_gate, msg_gate = await self._check_group_gate(event, "升级矿洞")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            row = (await session.execute(text(
                "SELECT cave_level FROM mining_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            level = int(row[0] or 1) if row else 1
            if level >= self.CAVE_MAX_LEVEL:
                raise _BizError(f"✅ 已满级！当前等级：{self.CAVE_MAX_LEVEL}级")
            nxt = level + 1
            cost = self.CAVE_UPGRADE_COST.get(nxt, 0)
            bal = await self._total_balance(session, user_id)
            if bal < cost:
                raise _BizError(
                    f"❌ 积分不足！升级需要 {cost} 积分，当前余额：{bal} 积分"
                )
            await self._add_points(session, user_id, -cost, "cave_upgrade", spent=cost)
            await session.execute(
                text("UPDATE mining_stats SET cave_level=:l WHERE user_id=:u"),
                {"u": user_id, "l": nxt},
            )
            energy_red = self.CAVE_ENERGY_REDUCTION.get(nxt, 0)
            rare_bonus = self.CAVE_RARE_BONUS.get(nxt, 0)
            extra = self.CAVE_EXTRA_HOURS.get(nxt, 0)
            new_bal = await self._balance(session, user_id)
            add_effects = [f"体力消耗-{energy_red}%", f"稀有矿概率+{rare_bonus}%"]
            if extra:
                add_effects.append(f"挂机上限+{extra}小时")
            return True, (
                f"✅ 矿洞升级成功！当前等级：{nxt}级\n"
                f"新增效果：{'，'.join(add_effects)}\n"
                f"花费 {cost} 积分，当前积分：{new_bal} 喵~"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 挖矿每日任务 ====================
    async def _ensure_daily_mining_tasks(self, session, user_id: str):
        """为今日生成每日挖矿任务（已有今日任务则跳过）"""
        today = date.today().isoformat()
        exist = (await session.execute(text(
            "SELECT 1 FROM mining_tasks WHERE user_id=:u AND task_date=:d LIMIT 1"
        ), {"u": user_id, "d": today})).first()
        if exist:
            return
        types = random.sample(self.MINING_TASK_TYPES, 3)
        for t in types:
            req_opts = self.MINING_TASK_REQUIREMENTS[t]
            req = random.choice(req_opts)
            lo, hi = self.MINING_TASK_REWARD_RANGES[t]
            reward = random.randint(lo, hi)
            target = str(req)
            if t == "specific":
                target = random.choice(list(ORE_POOL.keys()))
            elif t == "value":
                target = str(random.choice(self.MINING_TASK_REQUIREMENTS["value"]))
            req = int(target) if str(target).isdigit() else 1
            await session.execute(text(
                "INSERT INTO mining_tasks(user_id, task_date, task_type, task_target, "
                "task_requirement, task_reward) VALUES(:u,:d,:ty,:tg,:rq,:rw)"
            ), {"u": user_id, "d": today, "ty": t, "tg": target,
                "rq": req, "rw": reward})

    async def _mining_task_tick(self, session, user_id: str,
                                n_ore: int = 0, name: str = "", value: int = 0):
        await self._ensure_daily_mining_tasks(session, user_id)
        today = date.today().isoformat()
        tasks = (await session.execute(text(
            "SELECT id, task_type, task_target, task_requirement, task_progress, task_reward "
            "FROM mining_tasks WHERE user_id=:u AND task_date=:d AND task_status='pending'"
        ), {"u": user_id, "d": today})).all()
        if not tasks:
            return
        for t in tasks:
            tid, ty, tg, req, prog, reward = t
            req = int(req); prog = int(prog or 0)
            if ty == "collection":
                cnt = (await session.execute(text(
                    "SELECT COUNT(DISTINCT ore_name) FROM mining_collection WHERE user_id=:u"
                ), {"u": user_id})).first()
                distinct = int(cnt[0] or 0) if cnt else 0
                np = max(prog, min(distinct, req))
                await session.execute(text(
                    "UPDATE mining_tasks SET task_progress=:p WHERE id=:i"),
                    {"p": np, "i": tid})
                complete = distinct >= req
            elif ty == "count":
                np = min(prog + n_ore, req)
                await session.execute(text(
                    "UPDATE mining_tasks SET task_progress=:p WHERE id=:i"),
                    {"p": np, "i": tid})
                complete = np >= req
            elif ty == "specific":
                complete = name and name == tg and prog < 1
                if complete:
                    await session.execute(text(
                        "UPDATE mining_tasks SET task_progress=1 WHERE id=:i"), {"i": tid})
            elif ty == "value":
                complete = prog < 1 and value >= int(tg)
                if complete:
                    await session.execute(text(
                        "UPDATE mining_tasks SET task_progress=1 WHERE id=:i"), {"i": tid})
            else:  # combo
                complete = False
            if complete:
                await session.execute(text(
                    "UPDATE mining_tasks SET task_status='completed' WHERE id=:i"), {"i": tid})
                await self._add_points(session, user_id, int(reward), "mining_task")

    async def _mining_task_streak(self, session, user_id: str, broke: bool):
        """维护今日连续成功数并推进 combo 任务"""
        today = date.today().isoformat()
        row = (await session.execute(text(
            "SELECT today_success FROM mining_stats WHERE user_id=:u"
        ), {"u": user_id})).first()
        val = 0 if broke else (int(row[0] or 0) + 1)
        await session.execute(text(
            "UPDATE mining_stats SET today_success=:s WHERE user_id=:u"),
            {"s": val, "u": user_id})
        await self._ensure_daily_mining_tasks(session, user_id)
        tasks = (await session.execute(text(
            "SELECT id, task_target, task_requirement, task_progress, task_reward "
            "FROM mining_tasks WHERE user_id=:u AND task_date=:d "
            "AND task_type='combo' AND task_status='pending'"),
            {"u": user_id, "d": today})).all()
        for t in tasks:
            tid, tg, req, prog, reward = t
            req = int(req); nv = max(int(prog or 0), min(val, req))
            await session.execute(text(
                "UPDATE mining_tasks SET task_progress=:p WHERE id=:i"),
                {"p": nv, "i": tid})
            if nv >= req:
                await session.execute(text(
                    "UPDATE mining_tasks SET task_status='completed' WHERE id=:i"), {"i": tid})
                if int(reward or 0) > 0:
                    await self._add_points(session, user_id, int(reward), "mining_task")

    @filter.command("挖矿任务")
    async def mining_task_view(self, event: AstrMessageEvent):
        """/挖矿任务 —— 查看今日挖矿任务"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挖矿任务")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        today = date.today().isoformat()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            await self._ensure_daily_mining_tasks(session, user_id)
            tasks = (await session.execute(text(
                "SELECT task_type, task_target, task_requirement, task_progress, "
                "task_reward, task_status FROM mining_tasks "
                "WHERE user_id=:u AND task_date=:d ORDER BY id"),
                {"u": user_id, "d": today})).all()
            lines = ["📋 【今日挖矿任务】"]
            done = 0
            for ty, tg, req, prog, rwd, st in tasks:
                req = int(req); p = int(prog or 0)
                if ty == "count":
                    disp = f"挖到{tg}块矿"
                elif ty == "specific":
                    disp = f"挖到 1 块「{tg}」"
                elif ty == "value":
                    disp = f"挖到价值>{tg}的矿"
                elif ty == "combo":
                    disp = f"连续挖到{req}次（不空洞）"
                else:
                    disp = f"挖到{req}种不同矿"
                done += 1 if st == "completed" else 0
                mark = " ✅ 已领取" if st == "completed" else ""
                lines.append(f"• {disp}（{min(p,req)}/{req}）→ {rwd}积分{mark}")
            lines.append("─────────────")
            lines.append(f"完成进度：{done}/{len(tasks)}")
            if done < len(tasks):
                lines.append(f"还差 {len(tasks)-done} 个任务")
            else:
                bonus = (await session.execute(text(
                    "SELECT bonus_claimed FROM mining_tasks WHERE user_id=:u "
                    "AND task_date=:d LIMIT 1"), {"u": user_id, "d": today})).first()
                if bonus and int(bonus[0] or 0):
                    lines.append(f"✅ 全部完成！额外奖励 {self.MINING_TASK_BONUS} 积分已领取！")
                else:
                    lines.append(
                        f"🎉 全部完成！发 /领取挖矿奖励 领额外 {self.MINING_TASK_BONUS} 积分！")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("领取挖矿奖励")
    async def mining_task_claim(self, event: AstrMessageEvent):
        """/领取挖矿奖励 —— 全部完成时发额外奖励"""
        ok_gate, msg_gate = await self._check_group_gate(event, "领取挖矿奖励")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()
        today = date.today().isoformat()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            await self._ensure_daily_mining_tasks(session, user_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            pend = (await session.execute(text(
                "SELECT COUNT(*) FROM mining_tasks WHERE user_id=:u AND task_date=:d "
                "AND task_status='pending'"), {"u": user_id, "d": today})).first()
            if pend and int(pend[0] or 0) > 0:
                raise _BizError(f"还有 {int(pend[0])} 个任务未完成，完成后再来喵~")
            b = (await session.execute(text(
                "SELECT bonus_claimed FROM mining_tasks WHERE user_id=:u "
                "AND task_date=:d LIMIT 1"), {"u": user_id, "d": today})).first()
            if b and int(b[0] or 0):
                raise _BizError("今日额外奖励已领取喵~")
            await session.execute(text(
                "UPDATE mining_tasks SET bonus_claimed=1 WHERE user_id=:u AND task_date=:d"),
                {"u": user_id, "d": today})
            await self._add_points(
                session, user_id, self.MINING_TASK_BONUS, "mining_task_bonus")
            new_bal = await self._balance(session, user_id)
            return True, (
                f"🎉 全部完成！额外奖励 {self.MINING_TASK_BONUS} 积分已到账！\n"
                f"当前积分：{new_bal} 喵~"), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 挖矿天气 / 排行 / 统计 ====================
    @filter.command("挖矿天气")
    async def mining_weather_cmd(self, event: AstrMessageEvent):
        """/挖矿天气 —— 查看今日矿洞天气与加成效果"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挖矿天气")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return

        async def fn(session):
            wkey, wcfg = await self._mining_weather_today(session)
            # 刷新倒计时：距明日 0 点
            now = datetime.now(TZ)
            tomorrow = (now + timedelta(days=1)).replace(
                hour=0, minute=0, second=0, microsecond=0)
            remain_h = int((tomorrow - now).total_seconds() // 3600)
            remain_m = int(((tomorrow - now).total_seconds() % 3600) // 60)
            lines = [
                f"🌤️ 【今日矿洞天气】{wcfg['name']}",
                f"效果：{wcfg['desc']}",
                f"💡 {wcfg['advice']}",
                f"（{remain_h}小时{remain_m}分后刷新）",
            ]
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("挖矿排行")
    async def mining_rank(self, event: AstrMessageEvent):
        """/挖矿排行 [收入|数量|大矿|图鉴] —— 挖矿排行榜"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挖矿排行")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        subcmd = self._strip_command(event, "挖矿排行").strip() or "收入"

        async def fn(session):
            medals = ["👑", "🥈", "🥉"] + \
                [f"{i}." for i in range(4, self.MINING_RANK_SIZE + 1)]

            if subcmd == "收入":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), "
                    "s.total_income FROM mining_stats s LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.total_income > 0 ORDER BY s.total_income DESC LIMIT :n"
                ), {"n": self.MINING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人卖矿收入喵~ 快去 /挂机挖矿 抢占榜首！")
                lines = [f"📊 【挖矿排行·收入榜】TOP{len(rows)}"]
                for i, (uid, name, income) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(income)} 积分")

            elif subcmd == "数量":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), "
                    "s.total_ore_count FROM mining_stats s "
                    "LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.total_ore_count > 0 ORDER BY s.total_ore_count DESC LIMIT :n"
                ), {"n": self.MINING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人卖过矿喵~ 快去挖矿吧！")
                lines = [f"📊 【挖矿排行·数量榜】TOP{len(rows)}"]
                for i, (uid, name, count) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(count)} 块")

            elif subcmd == "大矿":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), "
                    "s.best_ore_name, s.best_ore_value FROM mining_stats s "
                    "LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.best_ore_value > 0 ORDER BY s.best_ore_value DESC LIMIT :n"
                ), {"n": self.MINING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人挖到大矿喵~ 快去碰碰运气！")
                lines = [f"📊 【挖矿排行·大矿榜】TOP{len(rows)}"]
                for i, (uid, name, ore_name, ore_value) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{ore_name}（{int(ore_value)} 积分）")

            elif subcmd == "图鉴":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), "
                    "s.collection_count FROM mining_stats s "
                    "LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.collection_count > 0 ORDER BY s.collection_count DESC LIMIT :n"
                ), {"n": self.MINING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人收集过矿石图鉴喵~")
                total_species = len(ORE_POOL)
                lines = [f"📊 【挖矿排行·图鉴榜】TOP{len(rows)}"]
                for i, (uid, name, count) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(count)}/{total_species} 种")

            elif subcmd == "连击":
                rows = (await session.execute(text(
                    "SELECT s.user_id, COALESCE(NULLIF(u.user_name, ''), s.user_id), "
                    "s.max_combo FROM mining_stats s LEFT JOIN users u ON u.user_id = s.user_id "
                    "WHERE s.max_combo > 0 ORDER BY s.max_combo DESC LIMIT :n"
                ), {"n": self.MINING_RANK_SIZE})).all()
                if not rows:
                    raise _BizError("还没有人触发过连击喵~")
                lines = [f"📊 【挖矿排行·连击榜】TOP{len(rows)}"]
                for i, (uid, name, combo) in enumerate(rows):
                    lines.append(f"{medals[i]} {name}：{int(combo)} 连击")

            else:
                raise _BizError("用法：/挖矿排行 [收入|数量|大矿|图鉴|连击]")

            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("挖矿统计")
    async def mining_stats_cmd(self, event: AstrMessageEvent):
        """/挖矿统计 —— 查看今日次数、体力消耗、累计收入、最高连击与称号"""
        ok_gate, msg_gate = await self._check_group_gate(event, "挖矿统计")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = event.get_sender_id()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            row = (await session.execute(text(
                "SELECT total_caught, total_income, total_energy_used, today_count, "
                "lucky_day_expire, current_combo, max_combo, storm_expire, cave_level "
                "FROM mining_stats WHERE user_id=:u"
            ), {"u": user_id})).first()
            collected = {str(r[0]) for r in (await session.execute(text(
                "SELECT ore_name FROM mining_collection WHERE user_id=:u"
            ), {"u": user_id})).all()}
            best_line = "暂无"
            if collected:
                best = max(collected, key=lambda n: ORE_POOL.get(n, (0,))[0])
                best_line = f"{best}（{ORE_POOL[best][0]}积分）"
            titles: list[str] = []
            if "烛心" in collected:
                titles.append("烛心矿主")
            if "闲鱼" in collected:
                titles.append("闲鱼矿主")
            if {"烛心", "闲鱼"} <= collected:
                rewarded = (await session.execute(text(
                    "SELECT 1 FROM point_transactions WHERE user_id=:u "
                    "AND operation='挖矿至高奖励'"
                ), {"u": user_id})).first()
                if rewarded:
                    titles.append("至高矿主")
            if len(collected) >= len(ORE_POOL):
                rewarded = (await session.execute(text(
                    "SELECT 1 FROM point_transactions WHERE user_id=:u "
                    "AND operation='挖矿集齐奖励'"
                ), {"u": user_id})).first()
                if rewarded:
                    titles.append("万物矿主")
            lines = [
                "📊 挖矿统计",
                f"今日挖矿：{int(row[3] or 0)} 次",
                f"累计挖矿：{int(row[0] or 0)} 块（消耗体力 {int(row[2] or 0)} 个）",
                f"累计卖矿收入：{int(row[1] or 0)} 积分",
                f"当前连击：{int(row[5] or 0)}（最高 {int(row[6] or 0)}）",
                f"矿洞等级：{int(row[8] or 1)} 级",
                f"最高价值矿：{best_line}",
                f"图鉴进度：{len(collected)}/{len(ORE_POOL)} 种",
            ]
            lucky_expire = float(row[4]) if row[4] else 0.0
            if lucky_expire > time.time():
                remain = int((lucky_expire - time.time()) / 60)
                lines.append(f"🍀 幸运日 buff 剩余 {remain} 分钟（卖矿翻倍）")
            storm_expire = float(row[7]) if row[7] else 0.0
            if storm_expire > time.time():
                remain = int((storm_expire - time.time()) / 60)
                lines.append(f"⛈️ 暴风雪停工中，剩余 {remain} 分钟")
            if titles:
                lines.append(f"🎖 称号：{'、'.join(titles)}")
            else:
                lines.append("🎖 称号：暂无（挖到烛心/闲鱼或集齐图鉴可获得）")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 矿洞偷矿 ====================
    @filter.command("偷矿")
    async def mining_steal(self, event: AstrMessageEvent):
        """/偷矿 @群友 —— 去别人的矿仓偷一块矿（30% 被发现，每天限 5 次）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "偷矿")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id()).strip()
        args = self._strip_command(event, "偷矿").split()
        target = self._extract_at(event)
        if not target:
            nums = [a for a in args if a.isdigit() and len(a) >= 5]
            target = nums[0] if nums else None
        if not target:
            yield event.plain_result("❌ 请@要偷矿的群友，如：/偷矿 @张三")
            return
        target = str(target).strip()
        if target == user_id:
            yield event.plain_result("❌ 不能偷自己的矿喵！")
            return
        today = date.today().isoformat()

        async def fn(session):
            await self._mining_ensure_stats(session, user_id)
            await self._mining_ensure_stats(session, target)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            # 每日次数
            srow = (await session.execute(text(
                "SELECT count FROM mining_steal WHERE user_id=:u AND date=:d"
            ), {"u": user_id, "d": today})).first()
            used = int(srow[0] or 0) if srow else 0
            if used >= self.MINING_STEAL_DAILY:
                raise _BizError(
                    f"今日偷矿次数已用完（{self.MINING_STEAL_DAILY}次/天），明天再来喵~")
            # 目标矿仓
            rows = (await session.execute(text(
                "SELECT ore_name, value_mult, count FROM mining_inventory WHERE user_id=:u"
            ), {"u": target})).all()
            if not rows:
                raise _BizError("对方的矿仓是空的，没啥可偷喵~")
            # 按数量加权随机挑一块
            names = [str(r[0]) for r in rows]
            weights = [max(int(r[2] or 0), 1) for r in rows]
            ore_name = random.choices(names, weights=weights)[0]
            vrow = (await session.execute(text(
                "SELECT value_mult, count FROM mining_inventory WHERE user_id=:u AND ore_name=:n"
            ), {"u": target, "n": ore_name})).first()
            mult = float(vrow[0] or 1)
            base_price = ORE_POOL.get(ore_name, (0,))[0]
            price = int(base_price * mult)
            spot = random.random() < (self.MINING_STEAL_SPOT_PCT / 100.0)
            await session.execute(text(
                "INSERT INTO mining_steal(user_id, date, count) VALUES(:u, :d, 1) "
                "ON CONFLICT(user_id, date) DO UPDATE SET count=mining_steal.count+1"
            ), {"u": user_id, "d": today})
            if spot:
                # 被发现：矿没偷到，按矿价 2 倍赔偿失主（最低 50）
                fine = max(50, price * 2)
                bal = await self._total_balance(session, user_id)
                if bal < fine:
                    raise _BizError(
                        f"被当场抓住了！赔偿需要 {fine} 积分，但你的积分不够赔喵…")
                await self._add_points(session, user_id, -fine, "steal_caught",
                                       spent=fine)
                await self._add_points(session, target, fine, "steal_compensation",
                                       earned=fine)
                tname = await self._user_name(session, target)
                return True, (
                    f"🚨 你摸进 {tname} 的矿仓，刚碰到 {ore_name} 就被当场抓住！\n"
                    f"矿没偷到，还倒赔 {fine} 积分给对方…（今日已偷 {used + 1}/{self.MINING_STEAL_DAILY} 次）"
                ), None
            # 偷窃成功：从失主矿仓扣 1 块，进小偷矿仓
            await session.execute(text(
                "UPDATE mining_inventory SET count=count-1 WHERE user_id=:u AND ore_name=:n"
            ), {"u": target, "n": ore_name})
            await session.execute(text(
                "DELETE FROM mining_inventory WHERE user_id=:u AND ore_name=:n AND count<=0"
            ), {"u": target, "n": ore_name})
            await session.execute(text(
                "INSERT INTO mining_inventory(user_id, ore_name, value_mult, count) "
                "VALUES(:u, :n, :m, 1) "
                "ON CONFLICT(user_id, ore_name) DO UPDATE SET "
                "count=mining_inventory.count+1"
            ), {"u": user_id, "n": ore_name, "m": mult})
            tname = await self._user_name(session, target)
            return True, (
                f"🥷 得手！从 {tname} 的矿仓顺走了一块 {ore_name}（{price}积分），已藏进自己的矿仓~\n"
                f"（今日已偷 {used + 1}/{self.MINING_STEAL_DAILY} 次，30% 概率被发现哦）"
            ), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _user_name(self, session, user_id: str) -> str:
        row = (await session.execute(text(
            "SELECT COALESCE(NULLIF(user_name, ''), user_id) FROM users WHERE user_id=:u"
        ), {"u": user_id})).first()
        return str(row[0]) if row else str(user_id)

    # ==================== 挖矿组队 ====================
    async def _mteam_for(self, session, user_id: str):
        """返回 用户所在挖矿队伍 row 或 None"""
        return (await session.execute(text(
            "SELECT id, captain_id, members, current_size, group_id FROM mining_teams "
            "WHERE members LIKE :like ESCAPE '\\' LIMIT 1"
        ), {"like": f'%"{user_id}"%'})).first()

    async def _mteam_bonus_mult(self, session, user_id: str) -> float:
        """用户挖矿收益加成倍率（队伍加成），默认 1.0"""
        row = await self._mteam_for(session, user_id)
        if not row:
            return 1.0
        _id, captain, members_json, size, _g = row
        base = self.MINING_TEAM_BONUS.get(int(size or 1), 0.0)
        if str(user_id) == str(captain):
            base += self.MINING_CAPTAIN_BONUS
        return 1.0 + base

    @filter.command("创建矿队")
    async def mteam_create(self, event: AstrMessageEvent):
        """/创建矿队 —— 组成挖矿小队（2-4人共享收益）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "创建矿队")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id() or "").strip()
        group_id = str(event.get_group_id() or "").strip() or "PM"

        async def fn(session):
            if await self._mteam_for(session, user_id):
                raise _BizError("你已在矿队中喵~")
            await session.execute(text(
                "INSERT INTO mining_teams(captain_id, members, current_size, group_id) "
                "VALUES(:c,:m,1,:g)"), {
                "c": user_id, "m": json.dumps([user_id]), "g": group_id})
            return True, ("⛏️ 矿队创建成功！\n当前队伍：1/4人\n"
                          "收益加成：0%（需2人以上）\n队友发送 /加入矿队 加入"), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("加入矿队")
    async def mteam_join(self, event: AstrMessageEvent):
        """/加入矿队 —— 加入本群已有挖矿小队"""
        ok_gate, msg_gate = await self._check_group_gate(event, "加入矿队")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id() or "").strip()
        group_id = str(event.get_group_id() or "").strip() or "PM"

        async def fn(session):
            if await self._mteam_for(session, user_id):
                raise _BizError("你已在矿队中喵~")
            row = (await session.execute(text(
                "SELECT id, captain_id, current_size FROM mining_teams "
                "WHERE group_id=:g AND current_size < :m ORDER BY id LIMIT 1"
            ), {"g": group_id, "m": self.MINING_TEAM_MAX_SIZE})).first()
            if not row:
                raise _BizError("本群没有可加入的矿队，先 /创建矿队 喵~")
            tid, captain, size = int(row[0]), row[1], int(row[2] or 1)
            cur = (await session.execute(text(
                "SELECT members FROM mining_teams WHERE id=:i"), {"i": tid})).first()
            members = json.loads(cur[0] or "[]")
            if user_id in members:
                raise _BizError("你已在矿队中喵~")
            members.append(user_id)
            await session.execute(text(
                "UPDATE mining_teams SET members=:m, current_size=:s WHERE id=:i"),
                {"m": json.dumps(members), "s": size + 1, "i": tid})
            full = (size + 1) >= self.MINING_TEAM_MAX_SIZE
            base = int(self.MINING_TEAM_BONUS.get(size + 1, 0) * 100)
            cap = base + int(self.MINING_CAPTAIN_BONUS * 100)
            tail = "（已满员）" if full else ""
            return True, (f"✅ {user_id} 加入矿队！当前：{size+1}/4人{tail}\n"
                          f"收益加成：成员+{base}%，队长+{cap}%"), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("矿队状态")
    async def mteam_status(self, event: AstrMessageEvent):
        """/矿队状态 —— 查看矿队成员与加成"""
        ok_gate, msg_gate = await self._check_group_gate(event, "矿队状态")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id() or "").strip()

        async def fn(session):
            row = await self._mteam_for(session, user_id)
            if not row:
                raise _BizError("你不在任何矿队中喵~")
            tid, captain, members_json, size, g = row
            members = json.loads(members_json or "[]")
            full = int(size) >= self.MINING_TEAM_MAX_SIZE
            base = int(self.MINING_TEAM_BONUS.get(int(size), 0) * 100)
            cap = base + int(self.MINING_CAPTAIN_BONUS * 100)
            ct = "（队长）" if str(user_id) == str(captain) else ""
            txt = [f"⛏️ 【矿队状态】队长：{captain}",
                   f"成员：{'、'.join(members)}（{size}/4人）",
                   f"收益加成：队长+{cap}%，其余+{base}%",
                   f"状态：✅ 已满员" if full else f"状态：欢迎加入（{self.MINING_TEAM_MAX_SIZE-int(size)}个空位）{ct}"]
            return True, "\n".join(txt), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("退出矿队")
    async def mteam_leave(self, event: AstrMessageEvent):
        """/退出矿队 —— 主动离开小队（队长退出即解散）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "退出矿队")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id() or "").strip()

        async def fn(session):
            row = await self._mteam_for(session, user_id)
            if not row:
                raise _BizError("你不在任何矿队中喵~")
            tid, captain, members_json, size, g = row
            members = json.loads(members_json or "[]")
            if str(user_id) == str(captain):
                await session.execute(text("DELETE FROM mining_teams WHERE id=:i"),
                                       {"i": int(tid)})
                return True, "⛏️ 矿队已解散（队长离开）", None
            members.remove(user_id)
            n = int(size) - 1
            if n <= 0:
                await session.execute(text("DELETE FROM mining_teams WHERE id=:i"),
                                       {"i": int(tid)})
                return True, "⛏️ 矿队已解散", None
            await session.execute(text(
                "UPDATE mining_teams SET members=:m,current_size=:s WHERE id=:i"),
                {"m": json.dumps(members), "s": n, "i": int(tid)})
            return True, f"✅ 已退出矿队，剩余 {n} 人", None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    @filter.command("解散矿队")
    async def mteam_disband(self, event: AstrMessageEvent):
        """/解散矿队 —— 队长解散"""
        ok_gate, msg_gate = await self._check_group_gate(event, "解散矿队")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        user_id = str(event.get_sender_id() or "").strip()

        async def fn(session):
            row = (await session.execute(text(
                "SELECT id FROM mining_teams WHERE captain_id=:c"), {"c": user_id})).first()
            if not row:
                raise _BizError("你不是矿队队长或无队伍喵~")
            await session.execute(text("DELETE FROM mining_teams WHERE id=:i"),
                                   {"i": int(row[0])})
            return True, "⛏️ 矿队已解散", None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ============================================================
    #  修仙系统（v4.25.0）：境界修炼/突破渡劫/灵根/兑换/功法/法宝/炼丹/秘境/宗门/灵兽/飞升
    # ============================================================
    def _xiuxian_help(self) -> str:
        return (
            "📖 【修仙指令】\n"
            "/修仙 信息 —— 查看修仙信息\n"
            "/修仙 修炼 —— 修炼获得修为（10积分，5分钟冷却）\n"
            "/修仙 突破 —— 小境界突破（100积分，修为满）\n"
            "/修仙 渡劫 —— 大境界渡劫（1000积分+渡劫丹，满层满修为）\n"
            "/修仙 灵根 —— 觉醒灵根（首次免费，重醒500积分）\n"
            "/修仙 兑换 [积分] —— 积分→灵石（10%手续费）\n"
            "/修仙 兑换 灵石 [数量] —— 灵石→积分\n"
            "/修仙 功法 —— 功法管理（抽取/修炼/装备）\n"
            "/修仙 法宝 —— 法宝管理（抽取/强化/装备）\n"
            "/修仙 炼丹 [丹名] —— 消耗积分+矿石炼丹\n"
            "/修仙 丹药 —— 丹药管理（使用）\n"
            "/修仙 秘境 —— 秘境探险（50积分）\n"
            "/修仙 宗门 —— 宗门管理（创建/加入/捐赠/升级/战/退出）\n"
            "/修仙 灵兽 —— 灵兽管理（捕捉/打工/收取/升级）\n"
            "/修仙 飞升 —— 渡劫9层满修为后飞升成仙"
        )

    def _xiuxian_max_cultivation(self, realm: str, level: int) -> int:
        """某境界某层的修为上限：base × mult^level"""
        idx = XIUXIAN_REALM_INDEX.get(realm, 0)
        r = XIUXIAN_REALMS[idx]
        return int(r["base"] * (r["mult"] ** int(level)))

    async def _xiuxian_ensure_player(self, session, user_id: str,
                                     platform_id: str = "", group_id: str = ""):
        """确保修仙玩家档案存在，并刷新活跃平台/群（必须在事务内调用）"""
        row = (await session.execute(text(
            "SELECT user_id FROM xiuxian_players WHERE user_id=:u"
        ), {"u": user_id})).first()
        if not row:
            await session.execute(text(
                "INSERT INTO xiuxian_players(user_id, realm, realm_level, cultivation, "
                "max_cultivation) VALUES(:u, '凡人', 0, 0, :m)"
            ), {"u": user_id, "m": self._xiuxian_max_cultivation("凡人", 0)})
        if platform_id or group_id:
            await session.execute(text(
                "UPDATE xiuxian_players SET platform_id=:p, group_id=:g WHERE user_id=:u"
            ), {"p": platform_id, "g": group_id, "u": user_id})

    async def _xiuxian_player(self, session, user_id: str):
        """读取修仙玩家档案行（必须在事务内调用）"""
        return (await session.execute(text(
            "SELECT realm, realm_level, cultivation, max_cultivation, spirit_root, "
            "constitution, sect_id, sect_position, spirit_stones, total_breakthrough, "
            "fail_count, cultivate_buff, secret_buff, break_bonus, last_cultivate "
            "FROM xiuxian_players WHERE user_id=:u"
        ), {"u": user_id})).first()

    async def _xiuxian_income_bonus(self, session, user_id: str) -> tuple[float, float]:
        """修仙收益加成（卖鱼/卖矿等处调用），返回 (境界倍率, 宗门倍率)。

        - 每提升一个大境界 +5%，封顶 +100%
        - 宗门每级成员 +1.5%
        """
        row = (await session.execute(text(
            "SELECT realm FROM xiuxian_players WHERE user_id=:u"
        ), {"u": user_id})).first()
        realm_mult = 1.0
        if row:
            idx = XIUXIAN_REALM_INDEX.get(str(row[0]), 0)
            realm_mult = min(1.0 + idx * self.XIUXIAN_BONUS_PER_REALM, self.XIUXIAN_BONUS_CAP)
        sect_mult = 1.0
        srow = (await session.execute(text(
            "SELECT p.sect_id, s.level FROM xiuxian_players p "
            "LEFT JOIN xiuxian_sects s ON s.id = p.sect_id WHERE p.user_id=:u"
        ), {"u": user_id})).first()
        if srow and srow[0] and srow[1]:
            sect_mult = 1.0 + int(srow[1]) * self.XIUXIAN_SECT_MEMBER_BONUS
        return realm_mult, sect_mult

    def _xiuxian_root_speed(self, spirit_root) -> float:
        return float(SPIRIT_ROOTS.get(spirit_root, {}).get("speed", 1.0))

    async def _xiuxian_equipped_tech_bonus(self, session, user_id: str) -> float:
        """已装备功法的修炼速度加成（品阶基础 + 每级2%）"""
        row = (await session.execute(text(
            "SELECT grade, level FROM xiuxian_techniques WHERE user_id=:u AND equipped=1"
        ), {"u": user_id})).first()
        if not row:
            return 0.0
        base = XIUXIAN_TECH_GRADES.get(str(row[0]), 0.0)
        return base + 0.02 * (int(row[1] or 1) - 1)

    async def _xiuxian_equipped_art_bonus(self, session, user_id: str) -> float:
        """已装备法宝的收益加成（品阶基础 + 每级2%）"""
        row = (await session.execute(text(
            "SELECT grade, level FROM xiuxian_artifacts WHERE user_id=:u AND equipped=1"
        ), {"u": user_id})).first()
        if not row:
            return 0.0
        base = XIUXIAN_ARTIFACT_GRADES.get(str(row[0]), 0.0)
        return base + 0.02 * (int(row[1] or 1) - 1)

    @filter.command("修仙")
    async def xiuxian_command(self, event: AstrMessageEvent):
        """/修仙 —— 修仙系统主指令（信息/修炼/突破/渡劫/灵根/兑换/功法/法宝/炼丹/丹药/秘境/宗门/灵兽/飞升）"""
        ok_gate, msg_gate = await self._check_group_gate(event, "修仙")
        if not ok_gate:
            yield event.plain_result(msg_gate)
            return
        args = self._strip_command(event, "修仙").strip().split()
        sub = args[0] if args else "信息"
        params = args[1:]
        handlers = {
            "信息": self._xiuxian_cmd_info, "状态": self._xiuxian_cmd_info,
            "修炼": self._xiuxian_cmd_cultivate, "打坐": self._xiuxian_cmd_cultivate,
            "突破": self._xiuxian_cmd_breakthrough,
            "渡劫": self._xiuxian_cmd_tribulation,
            "灵根": self._xiuxian_cmd_awaken, "觉醒": self._xiuxian_cmd_awaken,
            "兑换": self._xiuxian_cmd_exchange,
            "功法": self._xiuxian_cmd_techniques,
            "法宝": self._xiuxian_cmd_artifacts,
            "炼丹": self._xiuxian_cmd_alchemy,
            "丹药": self._xiuxian_cmd_pills,
            "秘境": self._xiuxian_cmd_secret, "探险": self._xiuxian_cmd_secret,
            "宗门": self._xiuxian_cmd_sect,
            "灵兽": self._xiuxian_cmd_spirit, "宠物": self._xiuxian_cmd_spirit,
            "飞升": self._xiuxian_cmd_ascend,
        }
        handler = handlers.get(sub)
        if handler is None:
            yield event.plain_result(self._xiuxian_help())
            return
        async for res in handler(event, params):
            yield res

    @staticmethod
    def _xiuxian_realm_display(realm: str, level: int) -> str:
        return f"{realm}{int(level) + 1}层" if realm != "道祖" else "道祖"

    async def _xiuxian_cmd_info(self, event: AstrMessageEvent, params: list):
        user_id = event.get_sender_id()

        async def fn(session):
            await self._xiuxian_ensure_player(session, user_id)
            p = await self._xiuxian_player(session, user_id)
            (realm, level, cult, maxc, root, consti, sect_id, position,
             stones, total_break, fails, cbuff, sbuff, bbonus, last_cult) = p
            idx = XIUXIAN_REALM_INDEX.get(str(realm), 0)
            speed = self._xiuxian_root_speed(root)
            tech_bonus = await self._xiuxian_equipped_tech_bonus(session, user_id)
            art_bonus = await self._xiuxian_equipped_art_bonus(session, user_id)
            realm_mult = min(1.0 + idx * self.XIUXIAN_BONUS_PER_REALM, self.XIUXIAN_BONUS_CAP)
            sect_row = None
            if sect_id:
                sect_row = (await session.execute(text(
                    "SELECT name, level FROM xiuxian_sects WHERE id=:i"
                ), {"i": int(sect_id)})).first()
            lines = [
                "🧙 【修仙信息】",
                f"境界：{self._xiuxian_realm_display(str(realm), int(level))}"
                f"（{str(realm)} · {len(XIUXIAN_REALMS)}大境界制）",
                f"修为：{int(cult)}/{int(maxc)}"
                + ("　✨ 可突破！" if int(cult) >= int(maxc) else ""),
                f"灵根：{root or '未觉醒'}（{SPIRIT_ROOTS.get(root, {}).get('desc', '发送 /修仙 灵根 觉醒')}）",
                f"体质：{consti or '凡胎'}",
                f"修炼速度：×{speed:.1f}"
                + (f" +功法{tech_bonus:.0%}" if tech_bonus > 0 else ""),
                f"积分玩法收益：×{realm_mult:.2f}（境界加成）",
            ]
            if art_bonus > 0:
                lines.append(f"法宝加成：卖鱼/卖矿收益 +{art_bonus:.0%}")
            if sect_row:
                lines.append(f"宗门：{sect_row[0]}（{position} · {int(sect_row[1])}级）")
            else:
                lines.append("宗门：散修（/修仙 宗门 创建|加入）")
            lines.append(f"灵石：{int(stones or 0)}（/修仙 兑换 与积分双向兑换）")
            lines.append(f"突破：累计 {int(total_break or 0)} 次，失败 {int(fails or 0)} 次")
            if int(bbonus or 0) > 0:
                lines.append(f"💊 破境丹加成：下次突破 +{int(bbonus) * 25}%")
            now = time.time()
            if cbuff and float(cbuff) > now:
                lines.append(f"💊 灵气丹生效：修炼收益+50%（剩 {int((float(cbuff)-now)/60)} 分钟）")
            if sbuff and float(sbuff) > now:
                lines.append(f"💊 福缘丹生效：秘境积分+50%（剩 {int((float(sbuff)-now)/60)} 分钟）")
            spirit = (await session.execute(text(
                "SELECT name, grade, level, attributes FROM xiuxian_spirits "
                "WHERE user_id=:u ORDER BY id LIMIT 1"
            ), {"u": user_id})).first()
            if spirit:
                lines.append(f"灵兽：{spirit[0]}（{spirit[1]} · {int(spirit[2])}级）")
            if str(realm) == "渡劫" and int(level) >= 8:
                lines.append("🌟 渡劫9层修为圆满后可 /修仙 飞升！")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _xiuxian_cmd_cultivate(self, event: AstrMessageEvent, params: list):
        """/修仙 修炼 —— 消耗10积分获得修为，5分钟冷却"""
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")

        async def fn(session):
            await self._xiuxian_ensure_player(session, user_id, platform_id, group_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            p = await self._xiuxian_player(session, user_id)
            realm, level, cult, maxc, root = p[0], p[1], p[2], p[3], p[4]
            if int(cult) >= int(maxc):
                raise _BizError("修为已圆满！发 /修仙 突破（或 /修仙 渡劫）冲击下一层喵~")
            # 冷却 5 分钟（独立于全局指令冷却）
            if p[14]:
                wait = self.XIUXIAN_CULTIVATE_COOLDOWN - (time.time() - float(p[14]))
                if wait > 0:
                    raise _BizError(f"⏳ 气息未平复，{int(wait // 60)} 分 {int(wait % 60)} 秒后再修炼")
            bal = await self._total_balance(session, user_id)
            if bal < self.XIUXIAN_CULTIVATE_COST:
                raise _BizError(
                    f"❌ 积分不足！修炼需要 {self.XIUXIAN_CULTIVATE_COST} 积分，当前余额：{bal}"
                )
            await self._add_points(
                session, user_id, -self.XIUXIAN_CULTIVATE_COST, "xiuxian_cultivate")
            speed = self._xiuxian_root_speed(root)
            tech_bonus = await self._xiuxian_equipped_tech_bonus(session, user_id)
            base_gain = random.randint(10, 30)
            gain = int(base_gain * speed * (1 + tech_bonus))
            now = time.time()
            buffed = p[11] and float(p[11]) > now
            if buffed:
                gain = int(gain * 1.5)
            new_cult = min(int(maxc), int(cult) + gain)
            await session.execute(text(
                "UPDATE xiuxian_players SET cultivation=:c, last_cultivate=:t WHERE user_id=:u"
            ), {"c": new_cult, "t": now, "u": user_id})
            msg = (f"🧘 修炼成功！获得 {gain} 修为"
                   f"{'（💊灵气丹×1.5）' if buffed else ''}\n"
                   f"当前修为：{new_cult}/{int(maxc)}")
            if new_cult >= int(maxc):
                if int(level) < XIUXIAN_REALMS[XIUXIAN_REALM_INDEX.get(str(realm), 0)]["levels"] - 1:
                    msg += "\n✨ 修为已满，发 /修仙 突破 冲击下一层！"
                else:
                    msg += "\n⚡ 此境界已至圆满，发 /修仙 渡劫 冲击大境界！"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _xiuxian_cmd_breakthrough(self, event: AstrMessageEvent, params: list):
        """/修仙 突破 —— 小境界突破：100积分，修为满才可突破"""
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")

        async def fn(session):
            await self._xiuxian_ensure_player(session, user_id, platform_id, group_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            p = await self._xiuxian_player(session, user_id)
            realm, level, cult, maxc = str(p[0]), int(p[1]), int(p[2]), int(p[3])
            idx = XIUXIAN_REALM_INDEX.get(realm, 0)
            r = XIUXIAN_REALMS[idx]
            if realm == "道祖":
                raise _BizError("👑 你已证道祖之位，诸天万界再无更高处！")
            if cult < maxc:
                raise _BizError(f"修为不足（{cult}/{maxc}），先 /修仙 修炼 积累修为喵~")
            if level < r["levels"] - 1:
                # ---- 小境界突破 ----
                bal = await self._total_balance(session, user_id)
                if bal < self.XIUXIAN_BREAK_COST:
                    raise _BizError(
                        f"❌ 积分不足！突破需要 {self.XIUXIAN_BREAK_COST} 积分，当前余额：{bal}"
                    )
                await self._add_points(
                    session, user_id, -self.XIUXIAN_BREAK_COST, "xiuxian_break")
                bonus_uses = int(p[13] or 0)
                rate = min(100, self.XIUXIAN_BREAK_RATE + bonus_uses * 25)
                if random.random() * 100 < rate:
                    new_level = level + 1
                    new_max = self._xiuxian_max_cultivation(realm, new_level)
                    await session.execute(text(
                        "UPDATE xiuxian_players SET realm_level=:l, cultivation=0, "
                        "max_cultivation=:m, total_breakthrough=total_breakthrough+1, "
                        "break_bonus=MAX(break_bonus-1, 0) WHERE user_id=:u"
                    ), {"l": new_level, "m": new_max, "u": user_id})
                    await session.execute(text(
                        "INSERT INTO xiuxian_records(user_id, type, detail) "
                        "VALUES(:u, 'breakthrough', :d)"
                    ), {"u": user_id, "d": f"{realm}{level+1}层 → {realm}{new_level+1}层"})
                    msg = (f"🌈 突破成功！进入 {self._xiuxian_realm_display(realm, new_level)}！\n"
                           f"修为上限提升至 {new_max}，继续修炼吧！")
                else:
                    lost = cult // 2
                    await session.execute(text(
                        "UPDATE xiuxian_players SET cultivation=:c, "
                        "fail_count=fail_count+1, break_bonus=MAX(break_bonus-1, 0) "
                        "WHERE user_id=:u"
                    ), {"c": cult - lost, "u": user_id})
                    msg = (f"💢 突破失败！走火入魔损失 {lost} 修为…\n"
                           f"当前修为：{cult - lost}/{maxc}（穿戴破境丹可提高成功率）")
                return True, msg, None
            raise _BizError("此境界已圆满！发 /修仙 渡劫 冲击大境界喵~")

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _xiuxian_cmd_tribulation(self, event: AstrMessageEvent, params: list):
        """/修仙 渡劫 —— 大境界突破：1000积分+渡劫丹，成功率受体质影响"""
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")

        async def fn(session):
            await self._xiuxian_ensure_player(session, user_id, platform_id, group_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            p = await self._xiuxian_player(session, user_id)
            realm, level, cult, maxc, consti = str(p[0]), int(p[1]), int(p[2]), int(p[3]), p[5]
            idx = XIUXIAN_REALM_INDEX.get(realm, 0)
            r = XIUXIAN_REALMS[idx]
            if realm == "道祖":
                raise _BizError("👑 你已证道祖之位，诸天万界再无更高处！")
            if level < r["levels"] - 1:
                raise _BizError(f"尚未圆满（第{level+1}层），先把小境界修满再来渡劫喵~")
            if cult < maxc:
                raise _BizError(f"修为不足（{cult}/{maxc}），先 /修仙 修炼 圆满修为喵~")
            # 渡劫丹检查
            pill = (await session.execute(text(
                "SELECT count FROM xiuxian_pills WHERE user_id=:u AND name='渡劫丹'"
            ), {"u": user_id})).first()
            if not pill or int(pill[0] or 0) < 1:
                raise _BizError(
                    "❌ 渡劫需要 1 颗【渡劫丹】！\n"
                    "炼制：/修仙 炼丹 渡劫丹（2000积分 + 5块珍稀矿）")
            bal = await self._total_balance(session, user_id)
            if bal < self.XIUXIAN_TRIB_COST:
                raise _BizError(
                    f"❌ 积分不足！渡劫需要 {self.XIUXIAN_TRIB_COST} 积分，当前余额：{bal}"
                )
            await self._add_points(session, user_id, -self.XIUXIAN_TRIB_COST, "xiuxian_tribulation")
            await session.execute(text(
                "UPDATE xiuxian_pills SET count=count-1 WHERE user_id=:u AND name='渡劫丹'"
            ), {"u": user_id})
            await session.execute(text(
                "DELETE FROM xiuxian_pills WHERE user_id=:u AND name='渡劫丹' AND count<=0"
            ), {"u": user_id})
            consti_bonus = XIUXIAN_CONSTITUTIONS.get(consti or "凡胎", (0, 0.0))[1]
            rate = self.XIUXIAN_TRIB_RATE + consti_bonus
            if random.random() * 100 < rate:
                new_realm = XIUXIAN_REALMS[idx + 1]["name"]
                new_max = self._xiuxian_max_cultivation(new_realm, 0)
                await session.execute(text(
                    "UPDATE xiuxian_players SET realm=:r, realm_level=0, cultivation=0, "
                    "max_cultivation=:m, total_breakthrough=total_breakthrough+1 "
                    "WHERE user_id=:u"
                ), {"r": new_realm, "m": new_max, "u": user_id})
                await session.execute(text(
                    "INSERT INTO xiuxian_records(user_id, type, detail) VALUES(:u, 'tribulation', :d)"
                ), {"u": user_id, "d": f"{realm} → {new_realm}"})
                msg = (f"⚡⚡⚡ 渡劫成功！天雷洗礼，肉身重塑！\n"
                       f"🎉 你已踏入【{new_realm}】！修为上限 {new_max}\n"
                       f"💰 所有积分玩法收益 +{(XIUXIAN_REALM_INDEX[new_realm]) * 5}%！")
                broadcasts = None
                if new_realm in self.XIUXIAN_REALM_BROADCAST:
                    uname = await self._user_name(session, user_id)
                    img_chain = await self._zhuxi_render_image(
                        "修仙界异象 · 渡劫",
                        [{"name": f"{uname} 渡劫成功",
                          "count": new_realm,
                          "events": [
                              f"晋入【{new_realm}】！雷云散去，天地异象",
                              f"修为上限提升至 {new_max}",
                              f"所有积分玩法收益 +{XIUXIAN_REALM_INDEX[new_realm] * 5}%",
                          ]}],
                    )
                    chain = [At(qq=str(user_id))]
                    if img_chain:
                        chain.extend(img_chain)
                    else:
                        chain.append(Plain(
                            f" ⚡⚡⚡ 渡劫成功，晋入【{new_realm}】！"
                            f"雷云散去，天地异象，众人皆惊！"))
                    broadcasts = [(platform_id, group_id, chain)]
                return True, msg, (broadcasts or [])
            lost = int(cult * 0.6)
            await session.execute(text(
                "UPDATE xiuxian_players SET cultivation=:c, fail_count=fail_count+1 "
                "WHERE user_id=:u"
            ), {"c": lost, "u": user_id})
            await session.execute(text(
                "INSERT INTO xiuxian_records(user_id, type, detail) VALUES(:u, 'trib_fail', :d)"
            ), {"u": user_id, "d": f"{realm} 渡劫失败"})
            return True, (
                f"💥 渡劫失败！天雷轰体，修为暴跌 {cult - lost} 点…\n"
                f"当前修为：{lost}/{maxc}（提升体质或再接再厉！）"), []

        ok, msg, data = await self._tx(fn)
        yield event.plain_result(msg)
        for platform, group, chain in (data or []):
            await self._send_with_fallback(platform, group, chain, "修仙渡劫播报",
                                               cross_group_fallback=False)

    async def _xiuxian_cmd_awaken(self, event: AstrMessageEvent, params: list):
        """/修仙 灵根 —— 觉醒灵根：首次免费，重新觉醒 500 积分"""
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")

        async def fn(session):
            await self._xiuxian_ensure_player(session, user_id, platform_id, group_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            p = await self._xiuxian_player(session, user_id)
            old_root, old_consti = p[4], p[5]
            cost = 0 if not old_root else 500
            if cost > 0:
                bal = await self._total_balance(session, user_id)
                if bal < cost:
                    raise _BizError(
                        f"❌ 重新觉醒需要 {cost} 积分洗练根骨，当前余额：{bal}")
                await self._add_points(session, user_id, -cost, "xiuxian_awaken")
            roots = list(SPIRIT_ROOTS.keys())
            weights = [SPIRIT_ROOTS[k]["rarity"] for k in roots]
            new_root = random.choices(roots, weights=weights)[0]
            constis = list(XIUXIAN_CONSTITUTIONS.keys())
            cweights = [XIUXIAN_CONSTITUTIONS[k][0] for k in constis]
            new_consti = random.choices(constis, weights=cweights)[0]
            await session.execute(text(
                "UPDATE xiuxian_players SET spirit_root=:r, constitution=:c WHERE user_id=:u"
            ), {"r": new_root, "c": new_consti, "u": user_id})
            await session.execute(text(
                "INSERT INTO xiuxian_records(user_id, type, detail) VALUES(:u, 'awaken', :d)"
            ), {"u": user_id, "d": f"{new_root}/{new_consti}"})
            msg = (f"🔮 灵根觉醒！测出【{new_root}】\n"
                   f"{SPIRIT_ROOTS[new_root]['desc']}\n"
                   f"附带体质：【{new_consti}】（渡劫成功率+{XIUXIAN_CONSTITUTIONS[new_consti][1]:.0f}%）")
            if cost > 0:
                msg = f"（洗练根骨消耗 {cost} 积分，原灵根：{old_root}）\n" + msg
            else:
                msg = "（首次觉醒免费）\n" + msg
            if new_root in ("天灵根", "单灵根"):
                msg += "\n🌟 此等资质，百年难遇！"
            return True, msg, None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    async def _xiuxian_cmd_exchange(self, event: AstrMessageEvent, params: list):
        """/修仙 兑换 [积分] —— 积分→灵石；/修仙 兑换 灵石 [数量] —— 灵石→积分（10%手续费）"""
        user_id = event.get_sender_id()
        # 方向：默认积分→灵石；第一个参数为"灵石"时反向
        direction = "points"
        rest = list(params)
        if rest and rest[0] in ("灵石", "积分"):
            direction = "stones" if rest[0] == "灵石" else "points"
            rest = rest[1:]
        nums = [x for x in rest if x.isdigit()]
        if not nums:
            yield event.plain_result("❌ 格式：/修仙 兑换 [积分数量] 或 /修仙 兑换 灵石 [灵石数量]")
            return
        amount = int(nums[-1])
        if amount <= 0:
            yield event.plain_result("❌ 数量必须大于0")
            return
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")

        async def fn(session):
            await self._xiuxian_ensure_player(session, user_id, platform_id, group_id)
            remaining = await self._enforce_cooldown(session, user_id)
            if remaining > 0:
                raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
            fee = int(amount * self.XIUXIAN_EXCHANGE_FEE / 100)
            got = amount - fee
            if direction == "points":
                bal = await self._total_balance(session, user_id)
                if bal < amount:
                    raise _BizError(f"❌ 积分不足！当前余额：{bal}")
                await self._add_points(session, user_id, -amount, "xiuxian_exchange",
                                       spent=amount)
                await session.execute(text(
                    "UPDATE xiuxian_players SET spirit_stones=spirit_stones+:s WHERE user_id=:u"
                ), {"s": got, "u": user_id})
                return True, (
                    f"💎 兑换成功！\n消耗积分：{amount}（手续费{fee}）\n"
                    f"获得灵石：{got}"), None
            # 灵石 → 积分
            p = await self._xiuxian_player(session, user_id)
            stones = int(p[8] or 0)
            if stones < amount:
                raise _BizError(f"❌ 灵石不足！当前灵石：{stones}")
            await session.execute(text(
                "UPDATE xiuxian_players SET spirit_stones=spirit_stones-:s WHERE user_id=:u"
            ), {"s": amount, "u": user_id})
            await self._add_points(session, user_id, got, "xiuxian_exchange_in",
                                   earned=got)
            return True, (
                f"💎 兑换成功！\n消耗灵石：{amount}（手续费{fee}）\n"
                f"获得积分：{got}"), None

        ok, msg, _ = await self._tx(fn)
        yield event.plain_result(msg)

    # ==================== 功法 ====================
    async def _xiuxian_cmd_techniques(self, event: AstrMessageEvent, params: list):
        """/修仙 功法 —— 查看；抽取（500积分）；修炼 [编号]（200×等级灵石）；装备 [编号]"""
        user_id = event.get_sender_id()
        platform_id = str(event.get_platform_id() or "")
        group_id = str(event.get_group_id() or "")
        sub = params[0] if params else ""

        if sub == "抽取":
            async def fn_draw(session):
                await self._xiuxian_ensure_player(session, user_id, platform_id, group_id)
                remaining = await self._enforce_cooldown(session, user_id)
                if remaining > 0:
                    raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
                cnt = (await session.execute(text(
                    "SELECT COUNT(*) FROM xiuxian_techniques WHERE user_id=:u"
                ), {"u": user_id})).first()
                if int(cnt[0]) >= self.XIUXIAN_MAX_TECHS:
                    raise _BizError(f"功法已满 {self.XIUXIAN_MAX_TECHS} 本，无法再参悟新的喵~")
                bal = await self._total_balance(session, user_id)
                if bal < self.XIUXIAN_TECH_DRAW_COST:
                    raise _BizError(
                        f"❌ 积分不足！参悟功法需要 {self.XIUXIAN_TECH_DRAW_COST} 积分")
                await self._add_points(
                    session, user_id, -self.XIUXIAN_TECH_DRAW_COST, "xiuxian_tech_draw")
                grades = list(XIUXIAN_TECH_GRADES.keys())
                grade = random.choices(grades, weights=XIUXIAN_TECH_WEIGHTS)[0]
                name = random.choice(XIUXIAN_TECH_NAMES)
                dup = (await session.execute(text(
                    "SELECT 1 FROM xiuxian_techniques WHERE user_id=:u AND name=:n"
                ), {"u": user_id, "n": name})).first()
                if dup:
                    name = name + "·改"
                await session.execute(text(
                    "INSERT INTO xiuxian_techniques(user_id, name, grade, level, equipped, "
                    "attributes) VALUES(:u, :n, :g, 1, 0, :a)"
                ), {"u": user_id, "n": name, "g": grade,
                    "a": f"修炼速度+{XIUXIAN_TECH_GRADES[grade]:.0%}"})
                return True, (
                    f"📜 参悟成功！获得【{grade} · {name}】\n"
                    f"效果：修炼速度+{XIUXIAN_TECH_GRADES[grade]:.0%}（升级每级+2%）\n"
                    f"发 /修仙 功法 装备 [编号] 装备"), None
            ok, msg, _ = await self._tx(fn_draw)
            yield event.plain_result(msg)
            return

        if sub == "装备":
            if not params[1:]:
                yield event.plain_result("❌ 格式：/修仙 功法 装备 [编号]")
                return
            try:
                tid = int(params[1])
            except ValueError:
                yield event.plain_result("❌ 编号得是数字喵~")
                return

            async def fn_eq(session):
                await self._xiuxian_ensure_player(session, user_id)
                row = (await session.execute(text(
                    "SELECT id, name, grade FROM xiuxian_techniques "
                    "WHERE user_id=:u AND id=:i"
                ), {"u": user_id, "i": tid})).first()
                if not row:
                    raise _BizError(f"没有编号 {tid} 的功法，发 /修仙 功法 查看")
                await session.execute(text(
                    "UPDATE xiuxian_techniques SET equipped=0 WHERE user_id=:u"
                ), {"u": user_id})
                await session.execute(text(
                    "UPDATE xiuxian_techniques SET equipped=1 WHERE id=:i"
                ), {"i": tid})
                return True, f"📖 已装备【{row[2]} · {row[1]}】，修炼事半功倍！", None
            ok, msg, _ = await self._tx(fn_eq)
            yield event.plain_result(msg)
            return

        if sub == "修炼":
            if not params[1:]:
                yield event.plain_result("❌ 格式：/修仙 功法 修炼 [编号]（消耗 200×当前等级 灵石）")
                return
            try:
                tid = int(params[1])
            except ValueError:
                yield event.plain_result("❌ 编号得是数字喵~")
                return

            async def fn_up(session):
                await self._xiuxian_ensure_player(session, user_id)
                remaining = await self._enforce_cooldown(session, user_id)
                if remaining > 0:
                    raise _BizError(f"操作太频繁啦，请 {remaining} 秒后再试喵~")
                row = (await session.execute(text(
                    "SELECT id, name, grade, level FROM xiuxian_techniques "
                    "WHERE user_id=:u AND id=:i"
                ), {"u": user_id, "i": tid})).first()
                if not row:
                    raise _BizError(f"没有编号 {tid} 的功法，发 /修仙 功法 查看")
                level = int(row[3])
                if level >= 9:
                    raise _BizError("此功法已臻大成（9级），无法再精进喵~")
                cost = self.XIUXIAN_TECH_UP_COST * level
                p = await self._xiuxian_player(session, user_id)
                stones = int(p[8] or 0)
                if stones < cost:
                    raise _BizError(
                        f"❌ 灵石不足！参悟需要 {cost} 灵石（/修仙 兑换 用积分换灵石）")
                await session.execute(text(
                    "UPDATE xiuxian_players SET spirit_stones=spirit_stones-:s WHERE user_id=:u"
                ), {"s": cost, "u": user_id})
                await session.execute(text(
                    "UPDATE xiuxian_techniques SET level=:l, exp=exp+100 WHERE id=:i"
                ), {"l": level + 1, "i": tid})
                return True, (
                    f"📖 【{row[2]} · {row[1]}】参悟至 {level + 1} 层！\n"
                    f"修炼速度加成：{XIUXIAN_TECH_GRADES.get(row[2], 0):.0%}+"
                    f"{(level) * 2}%（共消耗 {cost} 灵石）"), None
            ok, msg, _ = await self._tx(fn_up)
            yield event.plain_result(msg)
            return

        # 默认：查看
        async def fn_view(session):
            await self._xiuxian_ensure_player(session, user_id)
            rows = (await session.execute(text(
                "SELECT id, name, grade, level, equipped FROM xiuxian_techniques "
                "WHERE user_id=:u ORDER BY id"
            ), {"u": user_id})).all()
            if not rows:
                return True, (
                    "📜 你还没有功法喵~\n"
                    f"发 /修仙 功法 抽取 参悟（{self.XIUXIAN_TECH_DRAW_COST} 积分，"
                    f"黄阶+5%/玄阶+10%/地阶+20%/天阶+35% 修炼速度）"), None
            lines = ["📜 【功法列表】"]
            for tid, name, grade, level, eq in rows:
                mark = "✅装备中" if int(eq or 0) else ""
                lines.append(f"{tid}. 【{grade} · {name}】{level}级 {mark}")
            lines.append("抽取/修炼/装备：/修仙 功法 抽取｜修炼 [编号]｜装备 [编号]")
            return True, "\n".join(lines), None

        ok, msg, _ = await self._tx(fn_view)
        yield event.plain_result(msg)

